SELECT MAX(`Free Meal Count (K-12)` / `Enrollment (K-12)`) AS highest_eligible_free_rate FROM frpm WHERE `County Name` = 'Alameda';
SELECT      `Free Meal Count (Ages 5-17)` / `Enrollment (Ages 5-17)` AS eligible_free_rate FROM      frpm WHERE      `School Type` = 'Continuation'     AND `Enrollment (Ages 5-17)` > 0 ORDER BY      eligible_free_rate ASC LIMIT 3;
SELECT     s.Zip FROM schools AS s JOIN frpm AS f     ON s.CDSCode = f.CDSCode WHERE     f.`Charter School (Y/N)` = 1     AND s.District = 'Fresno County Office of Education';
SELECT s.MailStreet FROM frpm f JOIN schools s ON f.CDSCode = s.CDSCode ORDER BY f.`FRPM Count (K-12)` DESC LIMIT 1;
SELECT     s.Phone FROM schools AS s JOIN frpm AS f     ON s.CDSCode = f.CDSCode WHERE     f.`Charter School (Y/N)` = 1     AND f.`Charter Funding Type` = 'Directly funded'     AND s.OpenDate > '2000-01-01';
SELECT COUNT(*) FROM satscores WHERE AvgScrMath > 400   AND cds IN (     SELECT CDSCode     FROM schools     WHERE Virtual = 'F'   );
SELECT s.School FROM schools s JOIN satscores st ON s.CDSCode = st.cds WHERE st.NumTstTakr > 500   AND s.Magnet = 1;
SELECT s.Phone FROM schools s JOIN satscores st ON s.CDSCode = st.cds ORDER BY st.NumGE1500 DESC LIMIT 1;
SELECT   s.NumTstTakr FROM satscores AS s JOIN frpm AS f   ON s.cds = f.CDSCode WHERE f.`FRPM Count (K-12)` = (     SELECT MAX(`FRPM Count (K-12)`)     FROM frpm );
SELECT COUNT(*) FROM satscores s JOIN frpm f ON s.cds = f.CDSCode WHERE s.AvgScrMath > 560   AND f.`Charter Funding Type` = 'Directly funded';
WITH highest_reading AS (     SELECT          s.cds,         s.AvgScrRead     FROM          satscores s     WHERE          s.AvgScrRead IS NOT NULL     ORDER BY          s.AvgScrRead DESC     LIMIT 1 ) SELECT      f.`FRPM Count (Ages 5-17)` FROM      frpm f JOIN      highest_reading hr ON f.CDSCode = hr.cds;
SELECT   CDSCode FROM   frpm WHERE   (     COALESCE(`Enrollment (K-12)`, 0) + COALESCE(`Enrollment (Ages 5-17)`, 0)   ) > 500;
SELECT     MAX(f."Free Meal Count (Ages 5-17)" / f."Enrollment (Ages 5-17)") AS highest_eligible_free_rate FROM frpm AS f JOIN satscores AS s     ON f.CDSCode = s.cds WHERE s.NumTstTakr > 0   AND (s.NumGE1500 * 1.0 / s.NumTstTakr) > 0.3;
SELECT     s.Phone FROM     satscores AS sat JOIN     schools AS s     ON sat.cds = s.CDSCode ORDER BY     CAST(sat.NumGE1500 AS REAL) / sat.NumTstTakr DESC LIMIT 3;
SELECT     s.NCESSchool FROM     frpm f JOIN     schools s     ON f.CDSCode = s.CDSCode ORDER BY     f.`Enrollment (Ages 5-17)` DESC LIMIT 5;
SELECT   s.District FROM schools s JOIN satscores t   ON s.CDSCode = t.cds WHERE   s.StatusType = 'Active'   AND t.rtype = 'D' GROUP BY   s.District ORDER BY   AVG(t.AvgScrRead) DESC LIMIT 1;
SELECT COUNT(*) FROM satscores WHERE dname = 'Alameda Unified'   AND NumTstTakr < 100;
WITH RankedSchools AS (     SELECT          s.CDSCode,         s.School,         s.CharterNum,         ss.AvgScrWrite,         RANK() OVER (ORDER BY ss.AvgScrWrite DESC) AS Rank     FROM          satscores ss     JOIN          schools s ON ss.cds = s.CDSCode     WHERE          ss.AvgScrWrite > 499         AND s.CharterNum IS NOT NULL ) SELECT      Rank,     CDSCode,     School,     CharterNum,     AvgScrWrite FROM      RankedSchools ORDER BY      Rank;
SELECT COUNT(*) FROM satscores JOIN schools ON satscores.cds = schools.CDSCode WHERE schools.County = 'Fresno'   AND schools.FundingType = 'Directly funded'   AND satscores.NumTstTakr <= 250;
SELECT s.Phone FROM schools s JOIN satscores ss ON s.CDSCode = ss.cds ORDER BY ss.AvgScrMath DESC LIMIT 1;
SELECT COUNT(*) FROM frpm WHERE County Name = 'Amador'   AND Low Grade = '9'   AND High Grade = '12';
SELECT COUNT(*) AS school_count FROM frpm WHERE "County Name" = 'Los Angeles'   AND "Free Meal Count (K-12)" > 500   AND "FRPM Count (K-12)" < 700;
SELECT     s.School FROM     schools s JOIN     satscores st ON s.CDSCode = st.cds WHERE     s.County = 'Contra Costa' ORDER BY     st.NumTstTakr DESC LIMIT 1;
SELECT     frpm.`School Name`,     schools.`Street` FROM frpm JOIN schools     ON frpm.`CDSCode` = schools.`CDSCode` WHERE     frpm.`Enrollment (K-12)` - frpm.`Enrollment (Ages 5-17)` > 30;
SELECT     s.School FROM schools s JOIN frpm f     ON s.CDSCode = f.CDSCode JOIN satscores st     ON s.CDSCode = st.cds WHERE     f."Enrollment (K-12)" > 0     AND (f."Free Meal Count (K-12)" / f."Enrollment (K-12)") > 0.1     AND st.NumGE1500 > 0;
SELECT     s.FundingType FROM     schools s JOIN     satscores sat ON s.CDSCode = sat.cds WHERE     s.County = 'Riverside' GROUP BY     s.FundingType HAVING     SUM(sat.AvgScrMath) / COUNT(sat.cds) > 400;
SELECT     s.School AS SchoolName,     s.Street AS Street,     s.City AS City,     s.State AS State,     s.Zip AS Zip FROM schools s JOIN frpm f     ON s.CDSCode = f.CDSCode WHERE     f.`School Type` = 'High'     AND s.County = 'Monterey'     AND f.`Free Meal Count (Ages 5-17)` > 800;
SELECT     s.School,     sats.AvgScrWrite,     s.Phone FROM schools s JOIN satscores sats     ON s.CDSCode = sats.cds WHERE     (s.OpenDate > '1991-12-31')     OR     (s.ClosedDate < '2000-01-01');
WITH avg_diff AS (     SELECT AVG(`Enrollment (K-12)` - `Enrollment (Ages 5-17)`) AS avg_difference     FROM frpm     WHERE `Charter Funding Type` = 'Locally funded' ) SELECT s.`School`, s.`DOCType` FROM frpm f JOIN schools s ON f.`CDSCode` = s.`CDSCode` CROSS JOIN avg_diff ad WHERE f.`Charter Funding Type` = 'Locally funded'   AND (f.`Enrollment (K-12)` - f.`Enrollment (Ages 5-17)`) > ad.avg_difference;
SELECT s.OpenDate FROM schools s JOIN frpm f ON s.CDSCode = f.CDSCode WHERE f.`Low Grade` = 'K'   AND f.`High Grade` = '12' ORDER BY f.`Enrollment (K-12)` DESC LIMIT 1;
SELECT     s.City FROM schools s JOIN frpm f     ON s.CDSCode = f.CDSCode ORDER BY     f.`Enrollment (K-12)` ASC LIMIT 5;
SELECT      "Free Meal Count (K-12)" / "Enrollment (K-12)" AS eligible_free_rate FROM frpm ORDER BY "Enrollment (K-12)" DESC LIMIT 2 OFFSET 9;
SELECT     T1."FRPM Count (K-12)" / T1."Enrollment (K-12)" AS eligible_free_or_reduced_price_meal_rate FROM frpm AS T1 JOIN schools AS T2     ON T1.CDSCode = T2.CDSCode WHERE     T2.DOC = '66'     AND T1."Low Grade" = 'K'     AND T1."High Grade" = '12' ORDER BY     T1."FRPM Count (K-12)" DESC LIMIT 5;
SELECT     s.Website,     s.School FROM schools s JOIN frpm f     ON s.CDSCode = f.CDSCode WHERE f.`Free Meal Count (Ages 5-17)` BETWEEN 1900 AND 2000;
SELECT   T1.`Free Meal Count (Ages 5-17)` / T1.`Enrollment (Ages 5-17)` AS free_rate FROM frpm AS T1 JOIN schools AS T2   ON T1.CDSCode = T2.CDSCode WHERE   T2.`AdmFName1` = 'Kacey'   AND T2.`AdmLName1` = 'Gibson'
SELECT s.AdmEmail1 FROM frpm f JOIN schools s ON f.CDSCode = s.CDSCode WHERE f.`Charter School (Y/N)` = 1 ORDER BY f.`Enrollment (K-12)` ASC LIMIT 1;
SELECT   s.AdmFName1 || ' ' || s.AdmLName1 AS full_name_1,   s.AdmFName2 || ' ' || s.AdmLName2 AS full_name_2,   s.AdmFName3 || ' ' || s.AdmLName3 AS full_name_3 FROM schools s JOIN satscores sat ON s.CDSCode = sat.cds ORDER BY sat.NumGE1500 DESC LIMIT 1;
SELECT     s.Street,     s.City,     s.Zip,     s.State FROM schools s JOIN satscores ss ON s.CDSCode = ss.cds ORDER BY     CASE         WHEN ss.NumTstTakr = 0 THEN NULL         ELSE CAST(ss.NumGE1500 AS REAL) / ss.NumTstTakr     END ASC LIMIT 1;
SELECT s.Website FROM schools s JOIN satscores t ON s.CDSCode = t.cds WHERE s.County = 'Los Angeles'   AND t.NumTstTakr BETWEEN 2000 AND 3000;
SELECT AVG(T1.NumTstTakr) FROM satscores AS T1 INNER JOIN schools AS T2   ON T1.cds = T2.CDSCode WHERE T2.County = 'Fresno'   AND T2.OpenDate BETWEEN '1980-01-01' AND '1980-12-31';
SELECT s.Phone FROM schools s JOIN satscores ss ON s.CDSCode = ss.cds WHERE s.District = 'Fresno Unified' ORDER BY ss.AvgScrRead ASC LIMIT 1;
WITH VirtualSchools AS (     SELECT          s.CDSCode,         s.School,         s.County     FROM schools s     WHERE s.Virtual = 'F' ), RankedSchools AS (     SELECT          vs.School,         vs.County,         ss.AvgScrRead,         RANK() OVER (PARTITION BY vs.County ORDER BY ss.AvgScrRead DESC) AS rank_in_county     FROM VirtualSchools vs     JOIN satscores ss ON vs.CDSCode = ss.cds     WHERE ss.AvgScrRead IS NOT NULL ) SELECT DISTINCT School FROM RankedSchools WHERE rank_in_county <= 5 ORDER BY School;
SELECT s.EdOpsName FROM satscores t JOIN schools s ON t.cds = s.CDSCode ORDER BY t.AvgScrMath DESC LIMIT 1;
SELECT      satscores.AvgScrMath,     satscores.cname FROM satscores WHERE (satscores.AvgScrMath + satscores.AvgScrRead + satscores.AvgScrWrite) = (     SELECT MIN(AvgScrMath + AvgScrRead + AvgScrWrite)     FROM satscores     WHERE AvgScrMath IS NOT NULL       AND AvgScrRead IS NOT NULL       AND AvgScrWrite IS NOT NULL );
SELECT     satscores.AvgScrWrite,     schools.City FROM satscores JOIN schools     ON satscores.cds = schools.CDSCode WHERE satscores.NumGE1500 = (     SELECT MAX(NumGE1500)     FROM satscores );
SELECT     s.School,     AVG(ss.AvgScrWrite) AS AvgWritingScore FROM schools s JOIN satscores ss ON s.CDSCode = ss.cds WHERE s.AdmLName1 = 'Ulrich'   AND s.AdmFName1 = 'Ricci' GROUP BY s.School;
SELECT s.School FROM schools s JOIN frpm f ON s.CDSCode = f.CDSCode WHERE s.DOC = '31' ORDER BY f.`Enrollment (K-12)` DESC LIMIT 1;
SELECT   COUNT(*) / 12.0 AS monthly_average FROM   schools WHERE   County = 'Alameda'   AND DOC = '52'   AND OpenDate LIKE '1980-%';
SELECT      CAST(SUM(CASE WHEN DOC = '54' THEN 1 ELSE 0 END) AS REAL) * 1.0 /      NULLIF(SUM(CASE WHEN DOC = '52' THEN 1 ELSE 0 END), 0) AS ratio FROM schools WHERE County = 'Orange'   AND StatusType = 'Merged'   AND DOC IN ('52', '54');
WITH ClosedSchools AS (     SELECT          s.County,         s.School,         s.ClosedDate     FROM schools s     WHERE s.StatusType = 'Closed' ), CountyCounts AS (     SELECT          County,         COUNT(*) AS ClosedSchoolCount     FROM ClosedSchools     GROUP BY County ), TopCounty AS (     SELECT          County     FROM CountyCounts     ORDER BY ClosedSchoolCount DESC     LIMIT 1 ) SELECT      cs.County,     cs.School,     cs.ClosedDate FROM ClosedSchools cs JOIN TopCounty tc ON cs.County = tc.County ORDER BY cs.ClosedDate;
SELECT     s.MailStreet,     s.School FROM satscores AS t JOIN schools AS s   ON t.cds = s.CDSCode ORDER BY     t.AvgScrMath DESC LIMIT 1 OFFSET 6;
SELECT     s.MailStreet,     s.School FROM schools s JOIN satscores t     ON s.CDSCode = t.cds ORDER BY t.AvgScrRead ASC LIMIT 1;
SELECT COUNT(*) FROM satscores s JOIN schools sc ON s.cds = sc.CDSCode WHERE (s.AvgScrRead + s.AvgScrMath + s.AvgScrWrite) >= 1500   AND sc.MailCity = 'Lakeport';
SELECT     SUM(T1.NumTstTakr) FROM satscores AS T1 INNER JOIN schools AS T2     ON T1.cds = T2.CDSCode WHERE     T2.MailCity = 'Fresno';
SELECT      s.School,     s.MailZip FROM      schools s WHERE      s.AdmFName1 = 'Avetik' AND s.AdmLName1 = 'Atoian'     OR s.AdmFName2 = 'Avetik' AND s.AdmLName2 = 'Atoian'     OR s.AdmFName3 = 'Avetik' AND s.AdmLName3 = 'Atoian';
SELECT      CAST(SUM(CASE WHEN County = 'Colusa' THEN 1 ELSE 0 END) AS REAL) /      SUM(CASE WHEN County = 'Humboldt' THEN 1 ELSE 0 END) AS ratio FROM schools WHERE MailState = 'CA';
SELECT COUNT(*) FROM schools WHERE MailState = 'CA'   AND City = 'San Joaquin'   AND StatusType = 'Active';
SELECT     s.Phone,     s.Ext FROM satscores AS t JOIN schools AS s     ON t.cds = s.CDSCode ORDER BY     t.AvgScrWrite DESC LIMIT 1 OFFSET 332;
SELECT s.Phone, s.Ext, s.School FROM schools s WHERE s.Zip = '95203-3704';
SELECT T1.Website FROM schools AS T1 WHERE T1.AdmFName1 = 'Mike' AND T1.AdmLName1 = 'Larson'    OR T1.AdmFName1 = 'Dante' AND T1.AdmLName1 = 'Alvarez'    OR T1.AdmFName2 = 'Mike' AND T1.AdmLName2 = 'Larson'    OR T1.AdmFName2 = 'Dante' AND T1.AdmLName2 = 'Alvarez'    OR T1.AdmFName3 = 'Mike' AND T1.AdmLName3 = 'Larson'    OR T1.AdmFName3 = 'Dante' AND T1.AdmLName3 = 'Alvarez';
SELECT     s.Website FROM     schools AS s WHERE     s.Virtual = 'P'     AND s.Charter = 1     AND s.County = 'San Joaquin';
SELECT COUNT(*) FROM schools WHERE City = 'Hickman'   AND Charter = 1   AND DOC = '52';
SELECT COUNT(*) FROM frpm WHERE `County Name` = 'Los Angeles'   AND `Charter School (Y/N)` = 0   AND `Free Meal Count (K-12)` * 100.0 / `Enrollment (K-12)` < 0.18;
SELECT     s.School AS school_name,     s.City AS city,     s.AdmFName1 || ' ' || s.AdmLName1 AS administrator_1,     s.AdmFName2 || ' ' || s.AdmLName2 AS administrator_2,     s.AdmFName3 || ' ' || s.AdmLName3 AS administrator_3 FROM schools s WHERE s.Charter = 1   AND s.CharterNum = '00D2';
SELECT COUNT(*) FROM schools WHERE MailCity = 'Hickman' AND CharterNum = '00D4';
SELECT   CAST(SUM(CASE WHEN s.FundingType = 'Locally Funded' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(*) FROM schools s WHERE s.County = 'Santa Clara'   AND s.FundingType IS NOT NULL;
SELECT COUNT(*) FROM schools WHERE County = 'Stanislaus'   AND FundingType = 'Directly Funded'   AND OpenDate BETWEEN '2000-01-01' AND '2005-12-31';
SELECT   COUNT(*) AS total_closure_count FROM schools WHERE   DOCType = 'Community College District'   AND ClosedDate LIKE '1989%'   AND City = 'San Francisco';
SELECT     s.County FROM     schools s WHERE     s.SOC = '11'     AND s.ClosedDate IS NOT NULL     AND s.ClosedDate >= '1980-01-01'     AND s.ClosedDate < '1990-01-01' GROUP BY     s.County ORDER BY     COUNT(*) DESC LIMIT 1;
SELECT NCESDist FROM schools WHERE SOC = '31';
SELECT COUNT(*) FROM schools WHERE County = 'Alpine'   AND DOCType = 'District Community Day School'   AND StatusType IN ('Active', 'Closed');
SELECT DISTINCT     frpm.`District Code` FROM frpm JOIN schools     ON frpm.`CDSCode` = schools.`CDSCode` WHERE     schools.`Magnet` = 0     AND schools.`City` = 'Fresno';
SELECT     f."Enrollment (Ages 5-17)" FROM frpm AS f JOIN schools AS s     ON f.CDSCode = s.CDSCode WHERE     s.EdOpsCode = 'SSS'     AND s.City = 'Fremont'     AND f."Academic Year" = '2014-2015';
SELECT     T1.`Free Meal Count (Ages 5-17)` FROM frpm AS T1 INNER JOIN schools AS T2     ON T1.CDSCode = T2.CDSCode WHERE     T2.School = 'Youth Authority School'     AND T2.MailStreet = 'PO Box 1040';
SELECT     frpm.`Low Grade` FROM     frpm JOIN     schools ON     frpm.`CDSCode` = schools.`CDSCode` WHERE     schools.`EdOpsCode` = 'SPECON'     AND schools.`NCESDist` = '0613360' ORDER BY     frpm.`Low Grade` ASC LIMIT 1;
SELECT     T1."Educational Option Type",     T1."School Name" FROM frpm AS T1 WHERE     T1."NSLP Provision Status" = 'Breakfast Provision 2'     AND T1."County Code" = '37'
SELECT s.City FROM schools s JOIN frpm f ON s.CDSCode = f.CDSCode WHERE s.EILCode = 'HS'   AND f.`NSLP Provision Status` = '2'   AND f.`Low Grade` = '9'   AND f.`High Grade` = '12'   AND f.`County Name` = 'Merced';
SELECT     s.School,     (f.`FRPM Count (Ages 5-17)` / f.`Enrollment (Ages 5-17)` * 100) AS `Percent (%) Eligible FRPM (Ages 5-17)` FROM     schools s JOIN     frpm f ON s.CDSCode = f.CDSCode WHERE     s.County = 'Los Angeles'     AND s.GSserved = 'K-9';
SELECT s.GSserved FROM schools s WHERE s.City = 'Adelanto' GROUP BY s.GSserved ORDER BY COUNT(*) DESC LIMIT 1;
SELECT      s.County,     COUNT(*) AS school_count FROM      schools s WHERE      s.County IN ('San Diego', 'Santa Barbara')     AND s.Virtual = 'F' GROUP BY      s.County ORDER BY      school_count DESC LIMIT 1;
SELECT     s.School,     s.Latitude,     f.`School Type` FROM schools s JOIN frpm f ON s.CDSCode = f.CDSCode ORDER BY s.Latitude DESC LIMIT 1;
SELECT     s.City,     f.`Low Grade`,     s.School FROM schools s JOIN frpm f     ON s.CDSCode = f.CDSCode WHERE s.State = 'CA' ORDER BY s.Latitude ASC LIMIT 1;
SELECT   GSoffered FROM   schools ORDER BY   ABS(Longitude) DESC LIMIT 1;
SELECT     s.City,     COUNT(*) AS num_schools FROM schools s JOIN frpm f     ON s.CDSCode = f.CDSCode WHERE s.Magnet = 1   AND s.GSserved = 'K-8'   AND f.`NSLP Provision Status` = 'Multiple Provision Types' GROUP BY s.City;
WITH admin_names AS (     SELECT         AdmFName1 AS first_name,         District     FROM schools     WHERE AdmFName1 IS NOT NULL AND AdmFName1 != ''     UNION ALL     SELECT         AdmFName2 AS first_name,         District     FROM schools     WHERE AdmFName2 IS NOT NULL AND AdmFName2 != ''     UNION ALL     SELECT         AdmFName3 AS first_name,         District     FROM schools     WHERE AdmFName3 IS NOT NULL AND AdmFName3 != '' ), name_counts AS (     SELECT         first_name,         COUNT(*) AS cnt     FROM admin_names     GROUP BY first_name     ORDER BY cnt DESC     LIMIT 2 ) SELECT     an.first_name,     an.District FROM admin_names an JOIN name_counts nc ON an.first_name = nc.first_name ORDER BY nc.cnt DESC, an.first_name, an.District;
SELECT     f."District Code",     (f."Free Meal Count (K-12)" / f."Enrollment (K-12)") * 100 AS "Percent (%) Eligible Free (K-12)" FROM frpm AS f JOIN schools AS s   ON f.CDSCode = s.CDSCode WHERE     s."AdmFName1" = 'Alusine'     OR s."AdmFName2" = 'Alusine'     OR s."AdmFName3" = 'Alusine';
SELECT     s.AdmLName1,     s.District,     s.County,     s.School FROM schools AS s WHERE s.CharterNum = '40';
SELECT   AdmEmail1 FROM   schools WHERE   County = 'San Bernardino'   AND District = 'San Bernardino City Unified'   AND OpenDate BETWEEN '2009-01-01' AND '2010-12-31'   AND SOC = '62'   AND DOC = '54';
WITH RankedSchools AS (     SELECT          s.CDSCode,         s.School,         s.AdmEmail1,         sats.NumGE1500,         ROW_NUMBER() OVER (ORDER BY sats.NumGE1500 DESC) AS rn     FROM schools s     JOIN satscores sats ON s.CDSCode = sats.cds     WHERE sats.NumGE1500 IS NOT NULL ) SELECT      rs.School,     rs.AdmEmail1 FROM RankedSchools rs WHERE rs.rn = 1;
SELECT COUNT(*) AS account_count FROM account a JOIN district d ON a.district_id = d.district_id WHERE a.frequency = 'POPLATEK PO OBRATU'   AND d.A3 = 'East Bohemia';
SELECT COUNT(*) AS eligible_accounts FROM account a JOIN district d ON a.district_id = d.district_id WHERE d.A3 = 'Prague'   AND EXISTS (     SELECT 1     FROM loan l     WHERE l.account_id = a.account_id   );
SELECT      CASE          WHEN AVG(A12) > AVG(A13) THEN '1995'         ELSE '1996'     END AS higher_unemployment_year FROM district;
SELECT COUNT(DISTINCT d.district_id) FROM district d JOIN client c ON d.district_id = c.district_id WHERE c.gender = 'F'   AND d.A11 > 6000   AND d.A11 < 10000;
SELECT COUNT(*) AS count FROM client c JOIN district d   ON c.district_id = d.district_id WHERE c.gender = 'M'   AND d.A3 = 'North Bohemia'   AND d.A11 > 8000;
WITH client_district AS (     SELECT         c.client_id,         c.gender,         c.birth_date,         d.A11 AS avg_salary     FROM client c     JOIN district d ON c.district_id = d.district_id     WHERE c.gender = 'F' ), ranked AS (     SELECT         cd.*,         ROW_NUMBER() OVER (ORDER BY cd.birth_date ASC, cd.avg_salary ASC) AS rn     FROM client_district cd ), min_max AS (     SELECT         MIN(avg_salary) AS min_salary,         MAX(avg_salary) AS max_salary     FROM client_district ) SELECT     a.account_id,     mm.max_salary - mm.min_salary AS gap FROM ranked r JOIN disp d ON r.client_id = d.client_id JOIN account a ON d.account_id = a.account_id CROSS JOIN min_max mm WHERE r.rn = 1;
SELECT     c.client_id FROM     client c JOIN     district d ON     c.district_id = d.district_id WHERE     c.birth_date = (         SELECT             MAX(c2.birth_date)         FROM             client c2         JOIN             district d2         ON             c2.district_id = d2.district_id         WHERE             d2.A11 = (                 SELECT                     MAX(d3.A11)                 FROM                     district d3             )     )     AND d.A11 = (         SELECT             MAX(d4.A11)         FROM             district d4     );
SELECT COUNT(*) FROM disp d JOIN account a ON d.account_id = a.account_id WHERE a.frequency = 'POPLATEK TYDNE'   AND d.type = 'OWNER';
SELECT DISTINCT c.client_id FROM client c JOIN disp d ON c.client_id = d.client_id JOIN account a ON d.account_id = a.account_id JOIN trans t ON a.account_id = t.account_id WHERE d.type = 'DISPONENT'   AND a.frequency = 'POPLATEK PO OBRATU';
WITH ApprovedLoans1997 AS (     SELECT          l.account_id,         l.amount     FROM loan l     WHERE l.status = 'A'       AND strftime('%Y', l.date) = '1997' ), MinAmount AS (     SELECT MIN(amount) AS min_amount     FROM ApprovedLoans1997 ) SELECT      a.account_id FROM ApprovedLoans1997 al JOIN account a ON al.account_id = a.account_id CROSS JOIN MinAmount ma WHERE al.amount = ma.min_amount   AND a.frequency = 'POPLATEK TYDNE';
SELECT     a.account_id FROM account AS a JOIN loan AS l     ON a.account_id = l.account_id WHERE     l.duration > 12     AND a.date LIKE '1993%'     AND l.amount = (         SELECT MAX(l2.amount)         FROM loan AS l2         WHERE l2.duration > 12     );
SELECT COUNT(*) FROM client c JOIN district d ON c.district_id = d.district_id JOIN disp dp ON c.client_id = dp.client_id JOIN account a ON dp.account_id = a.account_id WHERE c.gender = 'F'   AND c.birth_date < '1950-01-01'   AND d.A2 = 'Sokolov';
SELECT     a.account_id FROM account AS a JOIN trans AS t     ON a.account_id = t.account_id WHERE     strftime('%Y', t.date) = '1995'     AND t.date = (         SELECT MIN(t2.date)         FROM trans AS t2         WHERE strftime('%Y', t2.date) = '1995'     );
SELECT DISTINCT a.account_id FROM account a JOIN trans t ON a.account_id = t.account_id WHERE a.date < '1997-01-01'   AND t.amount > 3000;
SELECT c.client_id FROM client c JOIN disp d ON c.client_id = d.client_id JOIN card cd ON d.disp_id = cd.disp_id WHERE cd.issued = '1994-03-03';
SELECT a.date FROM trans t JOIN account a ON t.account_id = a.account_id WHERE t.amount = 840   AND t.date = '1998-10-14';
SELECT a.district_id FROM loan l JOIN account a ON l.account_id = a.account_id WHERE l.date = '1994-08-25';
SELECT MAX(T.amount) FROM trans AS T JOIN disp AS D   ON T.account_id = D.account_id JOIN card AS C   ON D.disp_id = C.disp_id WHERE C.issued = '1996-10-21';
WITH highest_avg_salary_district AS (     SELECT          district_id     FROM          district     ORDER BY          A11 DESC     LIMIT 1 ) SELECT      c.gender FROM      client c JOIN      disp d ON c.client_id = d.client_id JOIN      account a ON d.account_id = a.account_id JOIN      highest_avg_salary_district h ON a.district_id = h.district_id ORDER BY      c.birth_date ASC LIMIT 1;
WITH client_loans AS (     SELECT         c.client_id,         l.loan_id,         l.amount AS loan_amount,         a.date AS account_date     FROM client c     JOIN disp d ON c.client_id = d.client_id     JOIN account a ON d.account_id = a.account_id     JOIN loan l ON a.account_id = l.account_id ), biggest_loan_client AS (     SELECT         client_id,         account_date     FROM client_loans     ORDER BY loan_amount DESC     LIMIT 1 ), first_trans AS (     SELECT         t.amount     FROM trans t     JOIN account a ON t.account_id = a.account_id     JOIN disp d ON a.account_id = d.account_id     JOIN client c ON d.client_id = c.client_id     WHERE c.client_id = (SELECT client_id FROM biggest_loan_client)       AND t.date >= (SELECT account_date FROM biggest_loan_client)     ORDER BY t.date ASC, t.trans_id ASC     LIMIT 1 ) SELECT amount FROM first_trans;
SELECT COUNT(*) AS count FROM client c JOIN disp d ON c.client_id = d.client_id JOIN account a ON d.account_id = a.account_id JOIN district dist ON a.district_id = dist.district_id WHERE c.gender = 'F'   AND dist.A2 = 'Jesenik';
SELECT d.disp_id FROM disp AS d JOIN trans AS t ON d.account_id = t.account_id WHERE t.amount = 5100   AND t.date = '1998-09-02';
SELECT COUNT(*) AS account_count FROM account a JOIN district d ON a.district_id = d.district_id WHERE d.A2 = 'Litomerice'   AND strftime('%Y', a.date) = '1996';
SELECT d.A2 FROM client c JOIN district d ON c.district_id = d.district_id WHERE c.gender = 'F'   AND c.birth_date = '1976-01-29';
SELECT c.birth_date FROM client c JOIN disp d ON c.client_id = d.client_id JOIN loan l ON d.account_id = l.account_id WHERE l.amount = 98832   AND l.date = '1996-01-03';
SELECT a.account_id FROM account a JOIN district d ON a.district_id = d.district_id WHERE d.A3 = 'Prague' ORDER BY a.date ASC LIMIT 1;
SELECT      CAST(SUM(CASE WHEN c.gender = 'M' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(c.client_id) AS percentage_male FROM client c JOIN district d ON c.district_id = d.district_id WHERE d.A3 = 'south Bohemia'   AND d.A4 = (       SELECT MAX(A4)       FROM district       WHERE A3 = 'south Bohemia'   );
WITH first_loan AS (     SELECT         l.account_id     FROM loan l     WHERE l.date = '1993-07-05'     ORDER BY l.loan_id     LIMIT 1 ), balances AS (     SELECT         t.account_id,         t.date,         t.balance     FROM trans t     WHERE t.account_id = (SELECT account_id FROM first_loan)       AND t.date IN ('1993-03-22', '1998-12-27') ) SELECT     (         (SELECT balance FROM balances WHERE date = '1998-12-27') -         (SELECT balance FROM balances WHERE date = '1993-03-22')     ) * 100.0 /     (SELECT balance FROM balances WHERE date = '1993-03-22') AS increase_rate FROM first_loan;
SELECT      CAST(SUM(CASE WHEN status = 'A' THEN amount ELSE 0 END) AS REAL) * 100 / SUM(amount) AS percentage FROM loan;
SELECT      CAST(SUM(CASE WHEN status = 'C' THEN amount ELSE 0 END) AS REAL) * 100 / SUM(amount) AS percentage FROM loan WHERE amount < 100000;
SELECT     a.account_id,     d.A2 AS district_name,     d.A3 AS district_region FROM account a JOIN district d     ON a.district_id = d.district_id WHERE     a.frequency = 'POPLATEK PO OBRATU'     AND strftime('%Y', a.date) = '1993';
SELECT     a.account_id,     a.frequency FROM account a JOIN district d     ON a.district_id = d.district_id JOIN disp dp     ON a.account_id = dp.account_id WHERE     d.A3 = 'east Bohemia'     AND a.date BETWEEN '1995-01-01' AND '2000-12-31'     AND dp.type = 'OWNER';
SELECT     a.account_id,     a.date FROM account AS a JOIN district AS d     ON a.district_id = d.district_id WHERE d.A2 = 'Prachatice';
SELECT d.A2, d.A3 FROM loan l JOIN account a ON l.account_id = a.account_id JOIN district d ON a.district_id = d.district_id WHERE l.loan_id = 4990;
SELECT     l.account_id,     d.A2 AS district,     d.A3 AS region FROM loan AS l JOIN account AS a     ON l.account_id = a.account_id JOIN district AS d     ON a.district_id = d.district_id WHERE l.amount > 300000;
SELECT     l.loan_id,     d.A3,     d.A11 FROM loan AS l JOIN account AS a     ON l.account_id = a.account_id JOIN district AS d     ON a.district_id = d.district_id WHERE     l.duration = 60;
SELECT     d.A2,     d.A3,     ((d.A13 - d.A12) / d.A12) * 100 AS unemployment_increment_rate FROM loan l JOIN account a     ON l.account_id = a.account_id JOIN district d     ON a.district_id = d.district_id WHERE l.status = 'D';
WITH accounts_in_1993 AS (     SELECT          a.account_id,         d.A2 AS district_name     FROM account a     JOIN district d ON a.district_id = d.district_id     WHERE strftime('%Y', a.date) = '1993' ), total_accounts_1993 AS (     SELECT COUNT(*) AS total_count     FROM accounts_in_1993 ), decin_accounts_1993 AS (     SELECT COUNT(*) AS decin_count     FROM accounts_in_1993     WHERE district_name = 'Decin' ) SELECT      (da.decin_count * 100.0) / ta.total_count AS percentage FROM decin_accounts_1993 da CROSS JOIN total_accounts_1993 ta;
SELECT account_id FROM account WHERE frequency = 'POPLATEK MESICNE';
SELECT      d.A2 AS district,     COUNT(c.client_id) AS female_account_holders FROM district d JOIN client c ON d.district_id = c.district_id JOIN disp disp ON c.client_id = disp.client_id JOIN account a ON disp.account_id = a.account_id WHERE c.gender = 'F'   AND disp.type = 'OWNER' GROUP BY d.district_id, d.A2 ORDER BY female_account_holders DESC, d.A2 ASC LIMIT 9;
SELECT     d.A2,     t.amount FROM trans t JOIN account a     ON t.account_id = a.account_id JOIN district d     ON a.district_id = d.district_id WHERE     t.type = 'VYDAJ'     AND t.date LIKE '1996-01%' ORDER BY     t.amount DESC LIMIT 10;
SELECT COUNT(*) FROM account a JOIN district d ON a.district_id = d.district_id WHERE d.A3 = 'South Bohemia'   AND NOT EXISTS (     SELECT 1     FROM disp dp     JOIN card c ON dp.disp_id = c.disp_id     WHERE dp.account_id = a.account_id       AND dp.type = 'OWNER'   );
SELECT d.A3 FROM loan l JOIN account a ON l.account_id = a.account_id JOIN district d ON a.district_id = d.district_id WHERE l.status IN ('C', 'D') ORDER BY l.amount DESC LIMIT 1;
SELECT AVG(l.amount) AS average_loan_amount FROM loan l JOIN account a ON l.account_id = a.account_id JOIN disp d ON a.account_id = d.account_id JOIN client c ON d.client_id = c.client_id WHERE c.gender = 'M';
SELECT     d.A4 AS branch_location,     d.A2 AS district_name FROM district d WHERE d.A13 = (     SELECT MAX(d2.A13)     FROM district d2 );
SELECT COUNT(a.account_id) AS num_accounts FROM account a JOIN district d ON a.district_id = d.district_id WHERE d.A16 = (     SELECT MAX(A16)     FROM district );
SELECT COUNT(DISTINCT T1.account_id) AS count FROM trans AS T1 JOIN account AS T2   ON T1.account_id = T2.account_id WHERE T1.operation = 'VYBER KARTOU'   AND T1.balance < 0   AND T2.frequency = 'POPLATEK MESICNE';
SELECT COUNT(*) FROM loan l JOIN account a ON l.account_id = a.account_id WHERE a.frequency = 'POPLATEK MESICNE'   AND l.date BETWEEN '1995-01-01' AND '1997-12-31'   AND l.amount >= 250000;
SELECT COUNT(*) AS account_count FROM loan l JOIN account a ON l.account_id = a.account_id WHERE l.status IN ('C', 'D')   AND a.district_id = 1;
WITH crime_counts AS (     SELECT          district_id,         A15 AS crimes_1995     FROM district     WHERE A15 IS NOT NULL ), ranked_crimes AS (     SELECT          district_id,         crimes_1995,         DENSE_RANK() OVER (ORDER BY crimes_1995 DESC) AS rank     FROM crime_counts ), second_highest_districts AS (     SELECT DISTINCT district_id     FROM ranked_crimes     WHERE rank = 2 ) SELECT COUNT(*) AS male_client_count FROM client WHERE gender = 'M'   AND district_id IN (SELECT district_id FROM second_highest_districts);
SELECT COUNT(*) FROM card c JOIN disp d ON c.disp_id = d.disp_id WHERE c.type = 'gold'   AND d.type = 'OWNER';
SELECT COUNT(*) AS account_count FROM account a JOIN district d ON a.district_id = d.district_id WHERE d.A2 = 'Pisek';
SELECT DISTINCT d.district_id FROM district d JOIN account a ON d.district_id = a.district_id JOIN trans t ON a.account_id = t.account_id WHERE t.amount > 10000   AND strftime('%Y', t.date) = '1997';
SELECT DISTINCT o.account_id FROM `order` o JOIN account a ON o.account_id = a.account_id JOIN district d ON a.district_id = d.district_id WHERE o.k_symbol = 'SIPO'   AND d.A2 = 'Pisek';
SELECT DISTINCT a.account_id FROM account AS a JOIN disp AS d ON a.account_id = d.account_id JOIN card AS c ON d.disp_id = c.disp_id WHERE c.type = 'gold';
SELECT AVG(amount) AS average_amount FROM trans WHERE operation = 'VYBER KARTOU'   AND strftime('%Y', date) = '2021';
SELECT DISTINCT c.client_id FROM client c JOIN disp d ON c.client_id = d.client_id JOIN trans t ON d.account_id = t.account_id WHERE d.type = 'OWNER'   AND t.date LIKE '1998%'   AND t.operation = 'VYBER KARTOU'   AND t.amount < (     SELECT AVG(amount)     FROM trans     WHERE date LIKE '1998%'       AND operation = 'VYBER KARTOU'   );
SELECT DISTINCT c.client_id FROM client c JOIN disp d   ON c.client_id = d.client_id  AND d.type = 'OWNER' JOIN card cd   ON d.disp_id = cd.disp_id JOIN loan l   ON d.account_id = l.account_id WHERE c.gender = 'F';
SELECT COUNT(*) FROM client c JOIN disp d ON c.client_id = d.client_id JOIN account a ON d.account_id = a.account_id JOIN district dist ON a.district_id = dist.district_id WHERE c.gender = 'F'   AND dist.A3 LIKE '%south Bohemia%';
SELECT     a.account_id FROM account AS a JOIN district AS d     ON a.district_id = d.district_id JOIN disp AS dp     ON a.account_id = dp.account_id WHERE     d.A2 = 'Tabor'     AND dp.type = 'OWNER';
SELECT DISTINCT     d.type AS account_type,     di.A11 AS average_income FROM disp d JOIN account a     ON d.account_id = a.account_id JOIN district di     ON a.district_id = di.district_id WHERE d.type <> 'OWNER'   AND di.A11 > 8000   AND di.A11 <= 9000;
SELECT COUNT(DISTINCT t.account_id) AS account_count FROM trans t JOIN account a ON t.account_id = a.account_id JOIN district d ON a.district_id = d.district_id WHERE d.A3 = 'North Bohemia'   AND t.bank = 'AB';
SELECT DISTINCT d.A2 FROM district d JOIN account a ON d.district_id = a.district_id JOIN trans t ON a.account_id = t.account_id WHERE t.type = 'VYDAJ';
SELECT AVG(d.A15) FROM district d JOIN account a ON d.district_id = a.district_id WHERE d.A15 > 4000   AND a.date >= '1997-01-01';
SELECT COUNT(*) FROM card c JOIN disp d ON c.disp_id = d.disp_id WHERE c.type = 'classic'   AND d.type = 'OWNER';
SELECT COUNT(*) FROM client c JOIN district d ON c.district_id = d.district_id WHERE c.gender = 'M'   AND d.A2 = 'Hl.m. Praha';
SELECT      CAST(SUM(CASE WHEN type = 'gold' AND issued < '1998-01-01' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(*) AS percent FROM card;
