SELECT COUNT(*) FROM account a JOIN disp d ON a.account_id = d.account_id WHERE d.type = 'OWNER'   AND a.frequency = 'POPLATEK PO OBRATU';
SELECT   l.amount,   l.status FROM loan AS l JOIN disp AS d   ON l.account_id = d.account_id WHERE d.client_id = 992;
SELECT      t.balance AS sum_after_transaction,     c.gender AS owner_gender FROM trans t JOIN disp d ON t.account_id = d.account_id AND d.type = 'OWNER' JOIN client c ON d.client_id = c.client_id WHERE t.trans_id = 851   AND c.client_id = 4;
SELECT c.type FROM card c JOIN disp d ON c.disp_id = d.disp_id WHERE d.client_id = 9;
SELECT     SUM(t.amount) AS total_paid FROM trans t JOIN disp d     ON t.account_id = d.account_id JOIN client c     ON d.client_id = c.client_id WHERE     c.client_id = 617     AND t.type = 'VYDAJ'     AND strftime('%Y', t.date) = '1998';
SELECT DISTINCT c.client_id FROM client c JOIN disp d ON c.client_id = d.client_id JOIN account a ON d.account_id = a.account_id JOIN district dist ON a.district_id = dist.district_id WHERE c.birth_date BETWEEN '1983-01-01' AND '1987-12-31'   AND dist.A3 = 'East Bohemia';
SELECT   c.client_id FROM client AS c JOIN disp AS d   ON c.client_id = d.client_id JOIN loan AS l   ON d.account_id = l.account_id WHERE c.gender = 'F' ORDER BY l.amount DESC LIMIT 3;
SELECT COUNT(*) AS count FROM client c JOIN disp d ON c.client_id = d.client_id JOIN trans t ON d.account_id = t.account_id WHERE c.gender = 'M'   AND c.birth_date BETWEEN '1974-01-01' AND '1976-12-31'   AND t.k_symbol = 'SIPO'   AND t.amount > 4000;
SELECT COUNT(*) FROM account a JOIN district d ON a.district_id = d.district_id WHERE d.A2 = 'Beroun'   AND a.date > '1996-12-31';
SELECT COUNT(*) FROM client c JOIN disp d ON c.client_id = d.client_id JOIN card cd ON d.disp_id = cd.disp_id WHERE c.gender = 'F'   AND cd.type = 'junior';
SELECT   CAST(SUM(CASE WHEN c.gender = 'F' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(*) FROM client c JOIN disp d ON c.client_id = d.client_id JOIN account a ON d.account_id = a.account_id JOIN district dist ON a.district_id = dist.district_id WHERE dist.A3 = 'Prague';
SELECT   CAST(SUM(CASE WHEN c.gender = 'M' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(*) FROM client c JOIN disp d   ON c.client_id = d.client_id JOIN account a   ON d.account_id = a.account_id WHERE a.frequency = 'POPLATEK TYDNE';
SELECT COUNT(*) FROM client c JOIN disp d ON c.client_id = d.client_id JOIN account a ON d.account_id = a.account_id WHERE d.type = 'OWNER'   AND a.frequency = 'POPLATEK TYDNE';
SELECT     a.account_id FROM     account a JOIN     loan l ON     a.account_id = l.account_id WHERE     l.duration > 24     AND a.date < '1997-01-01'     AND l.amount = (         SELECT             MIN(l2.amount)         FROM             loan l2         JOIN             account a2         ON             l2.account_id = a2.account_id         WHERE             l2.duration > 24             AND a2.date < '1997-01-01'     );
SELECT a.account_id FROM account a JOIN disp d ON a.account_id = d.account_id JOIN client c ON d.client_id = c.client_id JOIN district dist ON c.district_id = dist.district_id WHERE c.gender = 'F' ORDER BY c.birth_date ASC, dist.A11 ASC LIMIT 1;
SELECT COUNT(*) FROM client c JOIN district d ON c.district_id = d.district_id WHERE c.birth_date LIKE '1920-%'   AND d.A3 = 'east Bohemia';
SELECT COUNT(*) FROM loan l JOIN account a ON l.account_id = a.account_id WHERE l.duration = 24   AND a.frequency = 'POPLATEK TYDNE';
SELECT AVG(l.amount) FROM loan l JOIN account a ON l.account_id = a.account_id WHERE l.status IN ('C', 'D')   AND a.frequency = 'POPLATEK PO OBRATU';
SELECT DISTINCT c.client_id, c.district_id FROM client c JOIN disp d ON c.client_id = d.client_id WHERE d.type = 'OWNER';
SELECT   c.client_id,   (strftime('%Y', 'now') - strftime('%Y', c.birth_date)) AS age FROM client c JOIN disp d   ON c.client_id = d.client_id JOIN card cd   ON d.disp_id = cd.disp_id WHERE   cd.type = 'gold'   AND d.type = 'OWNER';
SELECT bond_type FROM bond GROUP BY bond_type ORDER BY COUNT(bond_type) DESC LIMIT 1;
SELECT COUNT(DISTINCT m.molecule_id) AS count FROM molecule m JOIN atom a ON m.molecule_id = a.molecule_id WHERE m.label = '-'   AND a.element = 'cl';
SELECT AVG(CASE WHEN a.element = 'o' THEN 1 ELSE 0 END) AS avg_oxygen_atoms FROM atom a JOIN bond b ON a.molecule_id = b.molecule_id WHERE b.bond_type = '-';
SELECT   CAST(SUM(CASE WHEN b.bond_type = '-' THEN 1 ELSE 0 END) AS REAL) / COUNT(a.atom_id) AS average_single_bonds FROM molecule m JOIN atom a   ON m.molecule_id = a.molecule_id JOIN connected c   ON a.atom_id = c.atom_id JOIN bond b   ON c.bond_id = b.bond_id WHERE m.label = '+';
SELECT COUNT(*) AS non_carcinogenic_count FROM molecule m JOIN atom a ON m.molecule_id = a.molecule_id WHERE a.element = 'na'   AND m.label = '-';
SELECT DISTINCT m.molecule_id FROM molecule m JOIN bond b ON m.molecule_id = b.molecule_id WHERE b.bond_type = '#'   AND m.label = '+';
SELECT      CAST(SUM(CASE WHEN a.element = 'c' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(a.atom_id) AS percentage FROM atom a JOIN bond b ON a.molecule_id = b.molecule_id WHERE b.bond_type = '=';
SELECT COUNT(*) FROM bond WHERE bond_type = '#';
SELECT COUNT(*) FROM atom WHERE element != 'br';
SELECT COUNT(*) AS carcinogenic_count FROM molecule WHERE molecule_id BETWEEN 'TR000' AND 'TR099'   AND label = '+';
SELECT DISTINCT m.molecule_id FROM molecule m JOIN atom a ON m.molecule_id = a.molecule_id WHERE a.element = 'c';
SELECT DISTINCT a.element FROM atom a JOIN connected c ON a.atom_id = c.atom_id WHERE c.bond_id = 'TR004_8_9';
SELECT DISTINCT a.element FROM atom a JOIN connected c ON a.atom_id = c.atom_id JOIN bond b ON c.bond_id = b.bond_id WHERE b.bond_type = '=';
SELECT     m.label FROM atom AS a JOIN molecule AS m     ON a.molecule_id = m.molecule_id WHERE     a.element = 'h' GROUP BY     m.label ORDER BY     COUNT(*) DESC LIMIT 1;
SELECT DISTINCT b.bond_type FROM bond b JOIN connected c ON b.bond_id = c.bond_id JOIN atom a ON c.atom_id = a.atom_id WHERE a.element = 'cl';
SELECT c.atom_id, c.atom_id2 FROM connected c JOIN bond b ON c.bond_id = b.bond_id WHERE b.bond_type = '-';
SELECT     c.atom_id,     c.atom_id2 FROM connected AS c JOIN molecule AS m     ON c.bond_id = (         SELECT b.bond_id         FROM bond AS b         WHERE b.bond_id = c.bond_id         LIMIT 1     )     AND m.molecule_id = (         SELECT b.molecule_id         FROM bond AS b         WHERE b.bond_id = c.bond_id         LIMIT 1     ) WHERE m.label = '-';
SELECT     a.element FROM atom AS a JOIN molecule AS m     ON a.molecule_id = m.molecule_id WHERE     m.label = '-' GROUP BY     a.element ORDER BY     COUNT(a.element) ASC LIMIT 1;
SELECT b.bond_type FROM connected c JOIN bond b ON c.bond_id = b.bond_id WHERE (c.atom_id = 'TR004_8' AND c.atom_id2 = 'TR004_20')    OR (c.atom_id = 'TR004_20' AND c.atom_id2 = 'TR004_8');
SELECT DISTINCT m.label FROM molecule m WHERE m.molecule_id NOT IN (     SELECT DISTINCT a.molecule_id     FROM atom a     WHERE a.element <> 'sn' )
SELECT COUNT(DISTINCT a.atom_id) FROM atom a JOIN molecule m ON a.molecule_id = m.molecule_id JOIN bond b ON a.molecule_id = b.molecule_id WHERE a.element IN ('i', 's')   AND b.bond_type = '-';
SELECT c.atom_id, c.atom_id2 FROM connected c JOIN bond b ON c.bond_id = b.bond_id WHERE b.bond_type = '#';
SELECT DISTINCT a.atom_id FROM atom a JOIN connected c ON a.atom_id = c.atom_id JOIN atom a2 ON c.atom_id2 = a2.atom_id WHERE a2.molecule_id = 'TR181';
SELECT      CAST(SUM(CASE WHEN a.element != 'f' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(DISTINCT a.molecule_id) AS percentage FROM      atom a JOIN      molecule m ON a.molecule_id = m.molecule_id WHERE      m.label = '+';
SELECT   CAST(SUM(CASE WHEN T1.bond_type = '#' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(T1.bond_id) AS percent FROM bond AS T1 JOIN molecule AS T2   ON T1.molecule_id = T2.molecule_id WHERE   T2.label = '+';
SELECT element FROM atom WHERE molecule_id = 'TR000' GROUP BY element ORDER BY element ASC LIMIT 3;
SELECT atom_id, atom_id2 FROM connected WHERE bond_id = 'TR001_2_6';
SELECT      SUM(CASE WHEN label = '+' THEN 1 ELSE 0 END) -      SUM(CASE WHEN label = '-' THEN 1 ELSE 0 END) AS difference FROM      molecule;
SELECT atom_id, atom_id2 FROM connected WHERE bond_id = 'TR000_2_5';
SELECT bond_id FROM connected WHERE atom_id2 = 'TR000_2';
SELECT DISTINCT m.molecule_id FROM molecule m JOIN bond b ON m.molecule_id = b.molecule_id WHERE b.bond_type = '=' ORDER BY m.molecule_id ASC LIMIT 5;
SELECT      CAST(SUM(CASE WHEN bond_type = '=' THEN 1 ELSE 0 END) AS REAL) * 100.0 / COUNT(bond_id) AS percentage FROM bond WHERE molecule_id = 'TR008';
SELECT      CAST(SUM(CASE WHEN label = '+' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(molecule_id) AS percentage FROM      molecule;
SELECT      CAST(SUM(CASE WHEN element = 'h' THEN 1 ELSE 0 END) AS REAL) * 100.0 / COUNT(atom_id) AS percentage FROM      atom WHERE      molecule_id = 'TR206';
SELECT DISTINCT b.bond_type FROM bond b WHERE b.molecule_id = 'TR000';
SELECT     a.element,     m.label FROM atom AS a JOIN molecule AS m     ON a.molecule_id = m.molecule_id WHERE     m.molecule_id = 'TR060';
WITH bond_counts AS (     SELECT          b.bond_type,         COUNT(*) AS cnt     FROM bond b     WHERE b.molecule_id = 'TR010'     GROUP BY b.bond_type ), top_bond AS (     SELECT          bond_type,         cnt,         ROW_NUMBER() OVER (ORDER BY cnt DESC) AS rn     FROM bond_counts ) SELECT      tb.bond_type,     CASE          WHEN m.label = '+' THEN 'carcinogenic'         ELSE 'not carcinogenic'     END AS carcinogenic_status FROM top_bond tb JOIN molecule m ON m.molecule_id = 'TR010' WHERE tb.rn = 1;
SELECT DISTINCT m.molecule_id FROM molecule m JOIN bond b ON m.molecule_id = b.molecule_id WHERE m.label = '-'   AND b.bond_type = '-' ORDER BY m.molecule_id LIMIT 3;
SELECT bond_id FROM bond WHERE molecule_id = 'TR006' ORDER BY bond_id ASC LIMIT 2;
