SELECT COUNT(DISTINCT b.molecule_id) AS molecule_count FROM bond b WHERE b.bond_type = '#';
SELECT COUNT(bond_id) AS connection_count FROM connected WHERE atom_id LIKE 'TR%_19'    OR atom_id2 LIKE 'TR%_19';
SELECT element FROM atom WHERE molecule_id = 'TR004';
SELECT COUNT(*) FROM molecule WHERE label = '-';
SELECT DISTINCT m.molecule_id FROM atom a JOIN molecule m ON a.molecule_id = m.molecule_id WHERE SUBSTR(a.atom_id, 7, 2) BETWEEN '21' AND '25'   AND m.label = '+';
SELECT DISTINCT b.bond_id FROM bond b JOIN connected c1 ON b.bond_id = c1.bond_id JOIN atom a1 ON c1.atom_id = a1.atom_id JOIN connected c2 ON b.bond_id = c2.bond_id JOIN atom a2 ON c2.atom_id2 = a2.atom_id WHERE a1.element = 'p'   AND a2.element = 'n';
WITH double_bond_counts AS (     SELECT          b.molecule_id,         COUNT(*) AS double_bond_count     FROM bond b     WHERE b.bond_type = '='     GROUP BY b.molecule_id ), ranked_molecules AS (     SELECT          d.molecule_id,         d.double_bond_count,         ROW_NUMBER() OVER (ORDER BY d.double_bond_count DESC) AS rn     FROM double_bond_counts d ) SELECT      CASE          WHEN m.label = '+' THEN 'Yes'         ELSE 'No'     END AS is_carcinogenic FROM ranked_molecules r JOIN molecule m ON r.molecule_id = m.molecule_id WHERE r.rn = 1;
SELECT   CAST(COUNT(DISTINCT T1.bond_id) AS REAL) / COUNT(DISTINCT T2.atom_id) AS average_bonds FROM bond AS T1 JOIN connected AS T2   ON T1.bond_id = T2.bond_id JOIN atom AS T3   ON T2.atom_id = T3.atom_id WHERE T3.element = 'i';
SELECT b.bond_type, b.bond_id FROM bond b JOIN connected c ON b.bond_id = c.bond_id JOIN atom a ON c.atom_id = a.atom_id WHERE CAST(SUBSTR(a.atom_id, 7, 2) AS INTEGER) = 45;
SELECT DISTINCT a.element FROM atom a WHERE a.atom_id NOT IN (     SELECT atom_id     FROM connected     UNION     SELECT atom_id2     FROM connected );
SELECT c.atom_id, c.atom_id2 FROM connected c JOIN bond b ON c.bond_id = b.bond_id WHERE b.molecule_id = 'TR041'   AND b.bond_type = '#';
SELECT DISTINCT a.element FROM atom a JOIN connected c ON a.atom_id = c.atom_id WHERE c.bond_id = 'TR144_8_19';
SELECT m.molecule_id FROM molecule m JOIN bond b ON m.molecule_id = b.molecule_id WHERE m.label = '+'   AND b.bond_type = '=' GROUP BY m.molecule_id ORDER BY COUNT(*) DESC LIMIT 1;
SELECT a.element FROM atom a JOIN molecule m ON a.molecule_id = m.molecule_id WHERE m.label = '+' GROUP BY a.element ORDER BY COUNT(*) ASC LIMIT 1;
SELECT DISTINCT c.atom_id2 FROM connected c JOIN atom a ON c.atom_id = a.atom_id WHERE a.element = 'pb';
SELECT DISTINCT a.element FROM atom a JOIN connected c ON a.atom_id = c.atom_id JOIN bond b ON c.bond_id = b.bond_id WHERE b.bond_type = '#';
WITH bond_elements AS (     SELECT         b.bond_id,         a1.element AS elem1,         a2.element AS elem2     FROM bond b     JOIN connected c ON b.bond_id = c.bond_id     JOIN atom a1 ON c.atom_id = a1.atom_id     JOIN atom a2 ON c.atom_id2 = a2.atom_id     WHERE a1.atom_id < a2.atom_id ), element_counts AS (     SELECT         elem1,         elem2,         COUNT(*) AS cnt     FROM bond_elements     GROUP BY elem1, elem2 ), max_count AS (     SELECT MAX(cnt) AS max_cnt     FROM element_counts ), total_bonds AS (     SELECT COUNT(*) AS total     FROM bond ) SELECT     CAST(100.0 * SUM(CASE WHEN ec.cnt = mc.max_cnt THEN ec.cnt ELSE 0 END) AS REAL) / tb.total AS percentage FROM element_counts ec CROSS JOIN max_count mc CROSS JOIN total_bonds tb;
SELECT      CAST(SUM(CASE WHEN m.label = '+' THEN 1 ELSE 0 END) AS REAL) * 100.0 / COUNT(b.bond_id) AS proportion FROM bond b JOIN molecule m ON b.molecule_id = m.molecule_id WHERE b.bond_type = '-';
SELECT COUNT(*) FROM atom WHERE element IN ('c', 'h');
SELECT c.atom_id2 FROM connected c JOIN atom a ON c.atom_id = a.atom_id WHERE a.element = 's';
SELECT DISTINCT b.bond_type FROM bond b JOIN connected c ON b.bond_id = c.bond_id JOIN atom a ON c.atom_id = a.atom_id WHERE a.element = 'sn';
SELECT COUNT(DISTINCT a.element) FROM atom a JOIN bond b ON a.molecule_id = b.molecule_id WHERE b.bond_type = '-';
SELECT COUNT(*) AS total_atoms FROM atom a JOIN bond b ON a.molecule_id = b.molecule_id WHERE b.bond_type = '#'   AND a.element IN ('p', 'br');
SELECT b.bond_id FROM bond b JOIN molecule m ON b.molecule_id = m.molecule_id WHERE m.label = '+';
SELECT DISTINCT b.molecule_id FROM bond b JOIN molecule m ON b.molecule_id = m.molecule_id WHERE b.bond_type = '-'   AND m.label = '-';
SELECT   CAST(SUM(CASE WHEN T1.element = 'cl' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(T1.atom_id) AS percent FROM atom AS T1 JOIN bond AS T2   ON T1.molecule_id = T2.molecule_id WHERE T2.bond_type = '-';
SELECT label FROM molecule WHERE molecule_id IN ('TR000', 'TR001', 'TR002');
SELECT molecule_id FROM molecule WHERE label = '-';
SELECT COUNT(*) AS total_carcinogenic_molecules FROM molecule WHERE label = '+'   AND molecule_id BETWEEN 'TR000' AND 'TR030';
SELECT bond_type FROM bond WHERE molecule_id BETWEEN 'TR000' AND 'TR050';
SELECT a.element FROM atom a JOIN connected c ON a.atom_id = c.atom_id WHERE c.bond_id = 'TR001_10_11';
SELECT COUNT(DISTINCT b.bond_id) FROM bond b JOIN connected c ON b.bond_id = c.bond_id JOIN atom a ON c.atom_id = a.atom_id WHERE a.element = 'i';
SELECT MAX(m.label) AS label FROM molecule m JOIN atom a ON m.molecule_id = a.molecule_id WHERE a.element = 'ca';
SELECT   CASE     WHEN COUNT(DISTINCT a.element) = 2      AND SUM(CASE WHEN a.element = 'cl' THEN 1 ELSE 0 END) > 0      AND SUM(CASE WHEN a.element = 'c' THEN 1 ELSE 0 END) > 0     THEN 'Yes'     ELSE 'No'   END AS has_cl_and_c FROM connected c JOIN atom a   ON a.atom_id = c.atom_id WHERE c.bond_id = 'TR001_1_8';
SELECT DISTINCT m.molecule_id FROM molecule m JOIN bond b ON m.molecule_id = b.molecule_id JOIN atom a ON m.molecule_id = a.molecule_id WHERE m.label = '-'   AND b.bond_type = '#'   AND a.element = 'c' LIMIT 2;
SELECT      CAST(SUM(CASE WHEN a.element = 'cl' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(a.molecule_id) AS percentage FROM atom a JOIN molecule m ON a.molecule_id = m.molecule_id WHERE m.label = '+';
SELECT element FROM atom WHERE molecule_id = 'TR001';
SELECT molecule_id FROM bond WHERE bond_type = '=';
SELECT     c.atom_id,     c.atom_id2 FROM connected AS c JOIN bond AS b   ON c.bond_id = b.bond_id WHERE b.bond_type = '#';
SELECT T1.element FROM atom AS T1 JOIN connected AS T2 ON T1.atom_id = T2.atom_id WHERE T2.bond_id = 'TR000_1_2';
SELECT COUNT(DISTINCT b.molecule_id) AS count FROM bond b JOIN molecule m ON b.molecule_id = m.molecule_id WHERE b.bond_type = '-'   AND m.label = '-';
SELECT m.label FROM bond b JOIN molecule m ON b.molecule_id = m.molecule_id WHERE b.bond_id = 'TR001_10_11';
SELECT     b.bond_id,     CASE         WHEN m.label = '+' THEN 'carcinogenic'         ELSE 'non-carcinogenic'     END AS carcinogenic FROM bond AS b JOIN molecule AS m     ON b.molecule_id = m.molecule_id WHERE b.bond_type = '#';
SELECT     a.element FROM atom AS a JOIN molecule AS m     ON a.molecule_id = m.molecule_id WHERE     m.label = '+'     AND substr(a.atom_id, 7, 1) = '4';
SELECT      m.label,     CAST(SUM(CASE WHEN a.element = 'h' THEN 1 ELSE 0 END) AS REAL) * 1.0 / COUNT(a.element) AS ratio FROM      atom a JOIN      molecule m ON a.molecule_id = m.molecule_id WHERE      a.molecule_id = 'TR006' GROUP BY      m.label;
SELECT      CASE          WHEN m.label = '+' THEN 'carcinogenic'         WHEN m.label = '-' THEN 'non-carcinogenic'         ELSE 'unknown'     END AS carcinogenic_status FROM molecule m JOIN atom a ON m.molecule_id = a.molecule_id WHERE a.element = 'ca';
SELECT DISTINCT b.bond_type FROM bond b JOIN atom a ON b.molecule_id = a.molecule_id WHERE a.element = 'c';
SELECT DISTINCT   CASE a.element     WHEN 'cl' THEN 'Chlorine'     WHEN 'c' THEN 'Carbon'     WHEN 'h' THEN 'Hydrogen'     WHEN 'o' THEN 'Oxygen'     WHEN 's' THEN 'Sulfur'     WHEN 'n' THEN 'Nitrogen'     WHEN 'p' THEN 'Phosphorus'     WHEN 'na' THEN 'Sodium'     WHEN 'br' THEN 'Bromine'     WHEN 'f' THEN 'Fluorine'     WHEN 'i' THEN 'Iodine'     WHEN 'sn' THEN 'Tin'     WHEN 'pb' THEN 'Lead'     WHEN 'te' THEN 'Tellurium'     WHEN 'ca' THEN 'Calcium'     ELSE a.element   END AS element_name FROM atom a WHERE a.atom_id IN (   'TR001_' || SUBSTR('TR001_10_11', 7, 2),   'TR001_' || SUBSTR('TR001_10_11', 10, 2) );
SELECT      CAST(SUM(CASE WHEN b.bond_type = '#' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(DISTINCT m.molecule_id) AS percent FROM molecule m LEFT JOIN bond b ON m.molecule_id = b.molecule_id;
SELECT      CAST(SUM(CASE WHEN bond_type = '=' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(bond_id) AS percent FROM bond WHERE molecule_id = 'TR047';
SELECT      CASE          WHEN m.label = '+' THEN 'carcinogenic'          ELSE 'not carcinogenic'      END AS carcinogenic_status FROM      atom a JOIN      molecule m ON a.molecule_id = m.molecule_id WHERE      a.atom_id = 'TR001_1';
SELECT label FROM molecule WHERE molecule_id = 'TR151';
SELECT DISTINCT a.element FROM atom a WHERE a.molecule_id = 'TR151'   AND a.element IN ('cl', 'br', 'i', 'sn', 'pb', 'te');
SELECT COUNT(*) FROM molecule WHERE label = '+';
SELECT a.atom_id FROM atom a JOIN molecule m ON a.molecule_id = m.molecule_id WHERE a.element = 'c'   AND CAST(SUBSTR(a.molecule_id, 3, 3) AS INTEGER) >= 10   AND CAST(SUBSTR(a.molecule_id, 3, 3) AS INTEGER) <= 50;
SELECT COUNT(*) AS atom_count FROM atom a JOIN molecule m ON a.molecule_id = m.molecule_id WHERE m.label = '+';
SELECT b.bond_id FROM bond b JOIN molecule m ON b.molecule_id = m.molecule_id WHERE b.bond_type = '='   AND m.label = '+';
SELECT COUNT(*) AS atom_count FROM atom WHERE element = 'h'   AND molecule_id IN (     SELECT molecule_id     FROM molecule     WHERE label = '+'   );
SELECT b.molecule_id FROM bond b JOIN connected c ON b.bond_id = c.bond_id WHERE b.bond_id = 'TR000_1_2'   AND c.atom_id = 'TR000_1';
SELECT a.atom_id FROM atom a JOIN molecule m ON a.molecule_id = m.molecule_id WHERE a.element = 'c'   AND m.label = '-';
SELECT      CAST(SUM(CASE WHEN m.label = '+' AND a.element = 'h' THEN 1 ELSE 0 END) AS REAL) * 100.0 / COUNT(DISTINCT m.molecule_id) AS percentage FROM molecule m JOIN atom a ON m.molecule_id = a.molecule_id;
SELECT label FROM molecule WHERE molecule_id = 'TR124';
SELECT atom_id FROM atom WHERE molecule_id = 'TR186';
SELECT bond_type FROM bond WHERE bond_id = 'TR007_4_19';
SELECT DISTINCT a.element FROM connected c JOIN atom a ON c.atom_id = a.atom_id WHERE c.bond_id = 'TR001_2_4' UNION SELECT DISTINCT a.element FROM connected c JOIN atom a ON c.atom_id2 = a.atom_id WHERE c.bond_id = 'TR001_2_4';
SELECT      COUNT(CASE WHEN b.bond_type = '=' THEN 1 END) AS double_bond_count,     CASE          WHEN m.label = '+' THEN 'carcinogenic'          ELSE 'non-carcinogenic'      END AS carcinogenic_status FROM molecule m LEFT JOIN bond b ON m.molecule_id = b.molecule_id WHERE m.molecule_id = 'TR006';
SELECT DISTINCT m.molecule_id, a.element FROM molecule m JOIN atom a ON m.molecule_id = a.molecule_id WHERE m.label = '+' ORDER BY m.molecule_id, a.element;
SELECT     b.bond_id,     a1.atom_id AS atom1,     a2.atom_id AS atom2,     m.molecule_id FROM bond b JOIN connected c     ON b.bond_id = c.bond_id JOIN atom a1     ON c.atom_id = a1.atom_id JOIN atom a2     ON c.atom_id2 = a2.atom_id JOIN molecule m     ON b.molecule_id = m.molecule_id WHERE b.bond_type = '-';
SELECT DISTINCT m.molecule_id, a.element FROM molecule m JOIN bond b ON m.molecule_id = b.molecule_id JOIN atom a ON m.molecule_id = a.molecule_id WHERE b.bond_type = '#';
SELECT DISTINCT a.element FROM atom a JOIN connected c ON a.atom_id = c.atom_id WHERE c.bond_id = 'TR000_2_3';
SELECT COUNT(*) AS bond_count FROM bond b JOIN connected c ON b.bond_id = c.bond_id JOIN atom a ON c.atom_id = a.atom_id WHERE a.element = 'cl';
SELECT     a.atom_id,     COUNT(DISTINCT b.bond_type) AS bond_type_count FROM atom a LEFT JOIN connected c     ON a.atom_id = c.atom_id LEFT JOIN bond b     ON c.bond_id = b.bond_id WHERE a.molecule_id = 'TR346' GROUP BY a.atom_id;
SELECT   COUNT(DISTINCT b.molecule_id) AS total_molecules_with_double_bond,   COUNT(DISTINCT CASE WHEN m.label = '+' THEN b.molecule_id END) AS carcinogenic_molecules FROM bond b JOIN molecule m ON b.molecule_id = m.molecule_id WHERE b.bond_type = '=';
SELECT COUNT(DISTINCT m.molecule_id) AS count FROM molecule m WHERE NOT EXISTS (     SELECT 1     FROM atom a     WHERE a.molecule_id = m.molecule_id       AND a.element = 's' ) AND NOT EXISTS (     SELECT 1     FROM bond b     WHERE b.molecule_id = m.molecule_id       AND b.bond_type = '=' );
SELECT m.label FROM bond b JOIN molecule m ON b.molecule_id = m.molecule_id WHERE b.bond_id = 'TR001_2_4';
SELECT COUNT(*) FROM atom WHERE molecule_id = 'TR001';
SELECT COUNT(*) FROM bond WHERE bond_type = '-';
SELECT DISTINCT m.molecule_id FROM molecule m JOIN atom a ON m.molecule_id = a.molecule_id WHERE a.element = 'cl'   AND m.label = '+';
SELECT DISTINCT m.molecule_id FROM molecule m JOIN atom a ON m.molecule_id = a.molecule_id WHERE a.element = 'c'   AND m.label = '-';
SELECT      CAST(SUM(CASE WHEN m.label = '+' AND a.element = 'cl' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(DISTINCT m.molecule_id) AS percentage FROM molecule m LEFT JOIN atom a ON m.molecule_id = a.molecule_id;
SELECT molecule_id FROM bond WHERE bond_id = 'TR001_1_7';
SELECT COUNT(DISTINCT a.element) AS element_count FROM connected c JOIN atom a ON c.atom_id = a.atom_id WHERE c.bond_id = 'TR001_3_4';
SELECT b.bond_type FROM connected c JOIN bond b ON c.bond_id = b.bond_id WHERE c.atom_id = 'TR000_1' AND c.atom_id2 = 'TR000_2';
SELECT T1.molecule_id FROM atom AS T1 JOIN atom AS T2 ON T1.molecule_id = T2.molecule_id WHERE T1.atom_id = 'TR000_2'   AND T2.atom_id = 'TR000_4';
SELECT element FROM atom WHERE atom_id = 'TR000_1';
SELECT      CASE          WHEN m.label = '+' THEN 'carcinogenic'         WHEN m.label = '-' THEN 'non-carcinogenic'         ELSE 'unknown'     END AS carcinogenic_status FROM      molecule m WHERE      m.molecule_id = 'TR000';
SELECT      CAST(SUM(CASE WHEN b.bond_type = '-' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(b.bond_id) AS percentage FROM bond b;
SELECT COUNT(DISTINCT m.molecule_id) AS carcinogenic_molecules_with_nitrogen FROM molecule m JOIN atom a ON m.molecule_id = a.molecule_id WHERE m.label = '+'   AND a.element = 'n';
SELECT DISTINCT m.molecule_id FROM molecule m JOIN atom a ON m.molecule_id = a.molecule_id JOIN connected c ON a.atom_id = c.atom_id JOIN bond b ON c.bond_id = b.bond_id WHERE a.element = 's'   AND b.bond_type = '=';
SELECT m.molecule_id FROM molecule m JOIN atom a ON m.molecule_id = a.molecule_id WHERE m.label = '-' GROUP BY m.molecule_id HAVING COUNT(a.molecule_id) > 5;
SELECT DISTINCT a.element FROM atom a JOIN connected c ON a.atom_id = c.atom_id JOIN bond b ON c.bond_id = b.bond_id WHERE b.bond_type = '='   AND a.molecule_id = 'TR024';
SELECT m.molecule_id FROM molecule m JOIN atom a ON m.molecule_id = a.molecule_id WHERE m.label = '+' GROUP BY m.molecule_id ORDER BY COUNT(a.molecule_id) DESC LIMIT 1;
WITH carcinogenic_molecules AS (     SELECT DISTINCT m.molecule_id     FROM molecule m     WHERE m.label = '+' ), triple_bonded_hydrogen_molecules AS (     SELECT DISTINCT a.molecule_id     FROM atom a     JOIN connected c ON a.atom_id = c.atom_id     JOIN bond b ON c.bond_id = b.bond_id     WHERE a.element = 'h'       AND b.bond_type = '#' ) SELECT      CAST(COUNT(DISTINCT tm.molecule_id) AS REAL) * 100.0 / COUNT(DISTINCT cm.molecule_id) AS percentage FROM carcinogenic_molecules cm LEFT JOIN triple_bonded_hydrogen_molecules tm ON cm.molecule_id = tm.molecule_id;
SELECT COUNT(*) FROM molecule WHERE label = '+';
SELECT COUNT(DISTINCT b.molecule_id) AS count FROM bond b WHERE b.molecule_id BETWEEN 'TR004' AND 'TR010'   AND b.bond_type = '-';
SELECT COUNT(*) FROM atom WHERE molecule_id = 'TR008' AND element = 'c';
SELECT a.element FROM atom a JOIN molecule m ON a.molecule_id = m.molecule_id WHERE a.atom_id = 'TR004_7'   AND m.label = '-';
SELECT COUNT(DISTINCT m.molecule_id) AS total_molecules FROM molecule m JOIN bond b ON m.molecule_id = b.molecule_id JOIN connected c ON b.bond_id = c.bond_id JOIN atom a ON c.atom_id = a.atom_id WHERE a.element = 'o'   AND b.bond_type = '=';
SELECT COUNT(DISTINCT m.molecule_id) AS non_carcinogenic_count FROM molecule m JOIN bond b ON m.molecule_id = b.molecule_id WHERE b.bond_type = '#'   AND m.label = '-';
SELECT DISTINCT a.element, b.bond_type FROM atom a JOIN bond b ON a.molecule_id = b.molecule_id WHERE a.molecule_id = 'TR002';
SELECT     a.atom_id FROM atom AS a JOIN connected AS c     ON a.atom_id = c.atom_id JOIN bond AS b     ON c.bond_id = b.bond_id WHERE     a.element = 'c'     AND b.bond_type = '='     AND a.molecule_id = 'TR012';
SELECT a.atom_id FROM atom a JOIN molecule m ON a.molecule_id = m.molecule_id WHERE m.label = '+'   AND a.element = 'o';
SELECT name FROM cards WHERE cardKingdomFoilId IS NOT NULL   AND cardKingdomId IS NOT NULL;
SELECT     c.name FROM     cards c WHERE     c.borderColor = 'borderless'     AND c.cardKingdomFoilId IS NULL     AND c.cardKingdomId IS NOT NULL;
SELECT     c.name FROM     cards c WHERE     c.faceConvertedManaCost = (         SELECT             MAX(c2.faceConvertedManaCost)         FROM             cards c2     );
SELECT     c.name FROM     cards c WHERE     c.frameVersion = '2015'     AND c.edhrecRank < 100;
SELECT c.name FROM cards c JOIN legalities l ON c.uuid = l.uuid WHERE c.rarity = 'mythic'   AND l.status = 'Banned'   AND l.format = 'gladiator';
SELECT     l.status FROM     cards c JOIN     legalities l     ON c.uuid = l.uuid WHERE     c.types = 'Artifact'     AND c.side IS NULL     AND l.format = 'vintage';
SELECT     c.id,     c.artist FROM cards AS c JOIN legalities AS l     ON c.uuid = l.uuid WHERE     l.format = 'commander'     AND l.status = 'Legal'     AND (         c.power = '*'         OR c.power IS NULL     );
SELECT     c.id,     r.text FROM cards AS c LEFT JOIN rulings AS r     ON c.uuid = r.uuid WHERE c.artist = 'Stephen Daniele'   AND c.hasContentWarning = 1;
SELECT r.text FROM rulings r JOIN cards c ON r.uuid = c.uuid WHERE c.name = 'Sublime Epiphany'   AND c.number = '74s';
SELECT     c.name,     c.artist,     c.isPromo FROM cards c JOIN rulings r ON c.uuid = r.uuid GROUP BY c.uuid ORDER BY COUNT(r.uuid) DESC LIMIT 1;
SELECT DISTINCT fd.language FROM foreign_data fd JOIN cards c ON fd.uuid = c.uuid WHERE c.name = 'Annul'   AND c.number = '29';
SELECT c.name FROM cards c JOIN foreign_data fd ON c.uuid = fd.uuid WHERE fd.language = 'Japanese';
SELECT      CAST(SUM(CASE WHEN language = 'Chinese Simplified' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(id) AS percentage FROM      set_translations;
SELECT      s.name AS set_name,     s.totalSetSize AS total_number_of_cards FROM sets s JOIN set_translations st ON s.code = st.setCode WHERE st.language = 'Italian';
SELECT COUNT(DISTINCT c.type) FROM cards c WHERE c.artist = 'Aaron Boyd';
SELECT keywords FROM cards WHERE name = 'Angel of Mercy';
SELECT COUNT(*) FROM cards WHERE power = '*';
SELECT promoTypes FROM cards WHERE name = 'Duress';
SELECT borderColor FROM cards WHERE name = 'Ancestor''s Chosen';
SELECT originalType FROM cards WHERE name = 'Ancestor''s Chosen';
SELECT DISTINCT st.language FROM cards c JOIN sets s ON c.setCode = s.code JOIN set_translations st ON s.code = st.setCode WHERE c.name = 'Angel of Mercy';
SELECT COUNT(*) FROM cards c JOIN legalities l ON c.uuid = l.uuid WHERE l.status = 'restricted'   AND c.isTextless = 0;
SELECT     r.text FROM rulings AS r JOIN cards AS c     ON r.uuid = c.uuid WHERE     c.name = 'Condemn';
SELECT COUNT(*) AS count FROM cards c JOIN legalities l ON c.uuid = l.uuid WHERE l.status = 'restricted'   AND c.isStarter = 1;
SELECT l.status FROM cards c JOIN legalities l ON c.uuid = l.uuid WHERE c.name = 'Cloudchaser Eagle';
SELECT type FROM cards WHERE name = 'Benalish Knight';
SELECT T1.format FROM legalities AS T1 INNER JOIN cards AS T2   ON T1.uuid = T2.uuid WHERE T2.name = 'Benalish Knight';
SELECT DISTINCT c.artist FROM cards c JOIN foreign_data fd ON c.uuid = fd.uuid WHERE fd.language = 'Phyrexian';
SELECT      CAST(SUM(CASE WHEN borderColor = 'borderless' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(id) AS percentage FROM      cards;
SELECT COUNT(*) AS count FROM cards c JOIN foreign_data fd ON c.uuid = fd.uuid WHERE fd.language = 'German'   AND c.isReprint = 1;
SELECT COUNT(*) AS count FROM cards c JOIN foreign_data fd ON c.uuid = fd.uuid WHERE c.borderColor = 'borderless'   AND fd.language = 'Russian';
SELECT   CAST(COUNT(CASE WHEN fd.language = 'French' THEN c.id END) AS REAL) * 100 / COUNT(c.id) FROM cards c LEFT JOIN foreign_data fd   ON c.uuid = fd.uuid WHERE c.isStorySpotlight = 1;
SELECT COUNT(*) FROM cards WHERE toughness = '99';
SELECT name FROM cards WHERE artist = 'Aaron Boyd';
SELECT COUNT(*) FROM cards WHERE borderColor = 'black' AND availability = 'mtgo';
SELECT id FROM cards WHERE convertedManaCost = 0;
SELECT     c.layout FROM     cards AS c WHERE     c.keywords LIKE '%flying%';
SELECT COUNT(*) AS count FROM cards WHERE originalType = 'Summon - Angel'   AND subtypes IS NOT NULL   AND subtypes <> 'Angel';
SELECT id FROM cards WHERE cardKingdomFoilId IS NOT NULL   AND cardKingdomId IS NOT NULL;
SELECT id FROM cards WHERE duelDeck = 'a';
SELECT edhrecRank FROM cards WHERE frameVersion = '2015';
SELECT DISTINCT c.artist FROM cards c JOIN foreign_data fd ON c.uuid = fd.uuid WHERE fd.language = 'Chinese Simplified';
SELECT c.name FROM cards c JOIN foreign_data fd ON c.uuid = fd.uuid WHERE c.availability = 'paper'   AND fd.language = 'Japanese';
SELECT COUNT(*) AS count FROM cards c JOIN legalities l ON c.uuid = l.uuid WHERE l.status = 'Banned'   AND c.borderColor = 'white';
SELECT     l.uuid,     fd.language FROM legalities AS l JOIN foreign_data AS fd     ON l.uuid = fd.uuid WHERE l.format = 'legacy';
SELECT     r.text FROM rulings AS r JOIN cards AS c     ON r.uuid = c.uuid WHERE     c.name = 'Beacon of Immortality';
SELECT     COUNT(DISTINCT c.id) AS card_count,     l.status AS legality_status FROM cards c JOIN legalities l ON c.uuid = l.uuid WHERE c.frameVersion = 'future' GROUP BY l.status;
SELECT     c.name,     c.colors FROM     cards AS c WHERE     c.setCode = 'OGW';
SELECT     c.name AS card_name,     st.translation AS translation,     st.language AS language FROM     cards c JOIN     set_translations st     ON c.setCode = st.setCode WHERE     c.setCode = '10E'     AND c.convertedManaCost = 5;
SELECT     c.name,     r.date FROM cards AS c JOIN rulings AS r     ON c.uuid = r.uuid WHERE c.originalType = 'Creature - Elf';
SELECT     c.colors,     l.format FROM cards AS c LEFT JOIN legalities AS l     ON c.uuid = l.uuid WHERE c.id BETWEEN 1 AND 20;
SELECT c.name FROM cards c JOIN foreign_data fd ON c.uuid = fd.uuid WHERE c.originalType = 'Artifact'   AND c.colors = 'B';
SELECT     c.name FROM cards c JOIN rulings r   ON c.uuid = r.uuid WHERE c.rarity = 'uncommon' ORDER BY r.date ASC LIMIT 3;
SELECT COUNT(*) FROM cards WHERE artist = 'John Avon'   AND cardKingdomId IS NOT NULL   AND cardKingdomFoilId IS NOT NULL;
SELECT COUNT(*) FROM cards WHERE borderColor = 'white' AND cardKingdomFoilId IS NOT NULL AND cardKingdomId IS NOT NULL;
SELECT COUNT(*) FROM cards WHERE artist = 'UDON'   AND availability = 'mtgo'   AND hand = '-1';
SELECT COUNT(*) FROM cards WHERE frameVersion = '1993' AND availability = 'paper' AND hasContentWarning = 1;
SELECT     c.manaCost FROM     cards c WHERE     c.layout = 'normal'     AND c.frameVersion = '2003'     AND c.borderColor = 'black'     AND c.availability = 'mtgo,paper';
SELECT SUM(CAST(manaCost AS REAL)) AS total_unconverted_mana FROM cards WHERE artist = 'Rob Alexander';
SELECT     subtypes,     supertypes FROM     cards WHERE     availability = 'arena';
SELECT DISTINCT c.setCode FROM cards c JOIN foreign_data fd ON c.uuid = fd.uuid WHERE fd.language = 'Spanish';
SELECT   CAST(SUM(CASE WHEN isOnlineOnly = 1 THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(id) AS percentage FROM cards WHERE frameEffects = 'legendary';
SELECT   c.id,   (     SELECT       CAST(COUNT(*) AS REAL) * 100 / (         SELECT COUNT(*) FROM cards       )     FROM cards c     WHERE c.isStorySpotlight = 1       AND c.isTextless = 0   ) AS percentage FROM cards c WHERE c.isStorySpotlight = 1   AND c.isTextless = 0;
WITH spanish_cards AS (     SELECT          c.name,         c.id     FROM cards c     JOIN foreign_data fd ON c.uuid = fd.uuid     WHERE fd.language = 'Spanish' ), total_cards AS (     SELECT COUNT(id) AS total_count     FROM cards ), spanish_count AS (     SELECT COUNT(id) AS spanish_count     FROM spanish_cards ) SELECT      sc.name,     (sc_count.spanish_count * 100.0) / tc.total_count AS percentage FROM spanish_cards sc CROSS JOIN spanish_count sc_count CROSS JOIN total_cards tc ORDER BY sc.name;
