SELECT c.colour FROM superhero s JOIN colour c ON s.eye_colour_id = c.id WHERE s.full_name = 'Abraham Sapien';
SELECT s.superhero_name FROM superhero s JOIN hero_power hp ON s.id = hp.hero_id JOIN superpower sp ON hp.power_id = sp.id WHERE sp.power_name = 'Flight';
SELECT     ec.colour AS eyes,     hc.colour AS hair,     sc.colour AS skin_colour FROM superhero s JOIN gender g ON s.gender_id = g.id JOIN publisher p ON s.publisher_id = p.id JOIN colour ec ON s.eye_colour_id = ec.id JOIN colour hc ON s.hair_colour_id = hc.id JOIN colour sc ON s.skin_colour_id = sc.id WHERE     g.gender = 'Female'     AND p.publisher_name = 'Dark Horse Comics';
SELECT     s.superhero_name,     p.publisher_name FROM superhero AS s JOIN publisher AS p     ON s.publisher_id = p.id WHERE     s.hair_colour_id = s.skin_colour_id     AND s.hair_colour_id = s.eye_colour_id;
SELECT r.race FROM superhero s JOIN race r ON s.race_id = r.id WHERE s.superhero_name = 'A-Bomb';
SELECT   CAST(SUM(CASE WHEN c.colour = 'Blue' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(*) FROM superhero s JOIN gender g ON s.gender_id = g.id JOIN colour c ON s.skin_colour_id = c.id WHERE g.gender = 'Female';
SELECT s.superhero_name, r.race FROM superhero s JOIN race r ON s.race_id = r.id WHERE s.full_name = 'Charles Chandler';
SELECT g.gender FROM superhero s JOIN gender g ON s.gender_id = g.id WHERE s.superhero_name = 'Agent 13';
SELECT s.superhero_name FROM superhero s JOIN hero_power hp ON s.id = hp.hero_id JOIN superpower sp ON hp.power_id = sp.id WHERE sp.power_name = 'Adaptation';
SELECT COUNT(*) FROM hero_power JOIN superhero ON hero_power.hero_id = superhero.id WHERE superhero.superhero_name = 'Amazo';
SELECT sp.power_name FROM superhero s JOIN hero_power hp ON s.id = hp.hero_id JOIN superpower sp ON hp.power_id = sp.id WHERE s.full_name = 'Hunter Zolomon';
SELECT     s.height_cm FROM superhero AS s JOIN colour AS c     ON s.eye_colour_id = c.id WHERE     c.colour = 'Amber';
SELECT s.superhero_name FROM superhero s JOIN colour c1 ON s.eye_colour_id = c1.id JOIN colour c2 ON s.hair_colour_id = c2.id WHERE c1.colour = 'Black'   AND c2.colour = 'Black';
SELECT     c1.colour FROM superhero AS s JOIN colour AS c1     ON s.eye_colour_id = c1.id JOIN colour AS c2     ON s.skin_colour_id = c2.id WHERE     c2.colour = 'Gold';
SELECT s.full_name FROM superhero s JOIN race r ON s.race_id = r.id WHERE r.race = 'Vampire';
SELECT s.superhero_name FROM superhero s JOIN alignment a ON s.alignment_id = a.id WHERE a.alignment = 'Neutral';
SELECT COUNT(*) FROM hero_attribute ha JOIN attribute a ON ha.attribute_id = a.id WHERE a.attribute_name = 'Strength'   AND ha.attribute_value = (     SELECT MAX(ha2.attribute_value)     FROM hero_attribute ha2     JOIN attribute a2 ON ha2.attribute_id = a2.id     WHERE a2.attribute_name = 'Strength'   );
SELECT     r.race,     a.alignment FROM superhero s JOIN race r ON s.race_id = r.id JOIN alignment a ON s.alignment_id = a.id WHERE s.superhero_name = 'Cameron Hicks';
SELECT   CAST(SUM(CASE WHEN g.gender = 'Female' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(*) FROM superhero s JOIN gender g ON s.gender_id = g.id JOIN publisher p ON s.publisher_id = p.id WHERE p.publisher_name = 'Marvel Comics';
SELECT AVG(s.weight_kg) AS average_weight FROM superhero s JOIN race r ON s.race_id = r.id WHERE r.race = 'Alien';
SELECT      (SELECT SUM(weight_kg) FROM superhero WHERE full_name = 'Emil Blonsky') -      (SELECT SUM(weight_kg) FROM superhero WHERE full_name = 'Charles Chandler') AS difference;
SELECT      s.superhero_name,     CAST(SUM(s.height_cm) AS FLOAT) / COUNT(*) AS average_height FROM superhero s GROUP BY s.id;
SELECT sp.power_name FROM superhero s JOIN hero_power hp ON s.id = hp.hero_id JOIN superpower sp ON hp.power_id = sp.id WHERE s.superhero_name = 'Abomination';
SELECT COUNT(*) AS count FROM superhero s JOIN gender g ON s.gender_id = g.id WHERE s.race_id = 21 AND g.id = 1;
SELECT s.superhero_name FROM superhero s JOIN hero_attribute ha ON s.id = ha.hero_id JOIN attribute a ON ha.attribute_id = a.id WHERE a.attribute_name = 'Speed' ORDER BY ha.attribute_value DESC LIMIT 1;
SELECT COUNT(*) FROM superhero WHERE alignment_id = 3;
SELECT     a.attribute_name,     ha.attribute_value FROM hero_attribute ha JOIN superhero s     ON s.id = ha.hero_id JOIN attribute a     ON a.id = ha.attribute_id WHERE s.superhero_name = '3-D Man';
SELECT s.superhero_name FROM superhero s JOIN colour c1 ON s.eye_colour_id = c1.id JOIN colour c2 ON s.hair_colour_id = c2.id WHERE c1.colour = 'Blue'   AND c2.colour = 'Brown';
SELECT p.publisher_name FROM superhero s JOIN publisher p ON s.publisher_id = p.id WHERE s.superhero_name IN ('Hawkman', 'Karate Kid', 'Speedy');
SELECT COUNT(*) FROM superhero WHERE publisher_id = 1;
SELECT   CAST(SUM(CASE WHEN c.colour = 'Blue' THEN 1 ELSE 0 END) AS REAL) * 100.0 / COUNT(s.superhero_name) AS percentage FROM superhero s JOIN colour c ON s.eye_colour_id = c.id;
SELECT   CAST(SUM(CASE WHEN g.gender = 'Male' THEN 1 ELSE 0 END) AS REAL) /   NULLIF(SUM(CASE WHEN g.gender = 'Female' THEN 1 ELSE 0 END), 0) AS ratio FROM superhero s JOIN gender g ON s.gender_id = g.id;
SELECT s.superhero_name FROM superhero s ORDER BY s.height_cm DESC LIMIT 1;
SELECT id FROM superpower WHERE power_name = 'Cryokinesis';
SELECT superhero_name FROM superhero WHERE id = 294;
SELECT     s.full_name FROM superhero AS s WHERE s.weight_kg IS NULL    OR s.weight_kg = 0;
SELECT c.colour FROM superhero s JOIN colour c ON s.eye_colour_id = c.id WHERE s.full_name = 'Karen Beecher-Duncan';
SELECT sp.power_name FROM superhero s JOIN hero_power hp ON s.id = hp.hero_id JOIN superpower sp ON hp.power_id = sp.id WHERE s.full_name = 'Helen Parr';
SELECT r.race FROM superhero s JOIN race r ON s.race_id = r.id WHERE s.weight_kg = 108   AND s.height_cm = 188;
SELECT p.publisher_name FROM superhero s JOIN publisher p ON s.publisher_id = p.id WHERE s.id = 38;
SELECT r.race FROM superhero s JOIN hero_attribute ha ON s.id = ha.hero_id JOIN race r ON s.race_id = r.id WHERE ha.attribute_value = (     SELECT MAX(attribute_value)     FROM hero_attribute );
SELECT     a.alignment,     sp.power_name FROM superhero s JOIN alignment a ON s.alignment_id = a.id JOIN hero_power hp ON s.id = hp.hero_id JOIN superpower sp ON hp.power_id = sp.id WHERE s.superhero_name = 'Atom IV';
SELECT     s.full_name FROM superhero AS s JOIN colour AS c     ON s.eye_colour_id = c.id WHERE     c.colour = 'Blue' LIMIT 5;
SELECT AVG(ha.attribute_value) AS average_attribute_value FROM hero_attribute ha JOIN superhero s ON ha.hero_id = s.id WHERE s.alignment_id = 3;
SELECT     c.colour FROM superhero AS s JOIN hero_attribute AS ha     ON s.id = ha.hero_id JOIN colour AS c     ON s.skin_colour_id = c.id WHERE     ha.attribute_value = 100;
SELECT COUNT(*) FROM superhero s JOIN alignment a ON s.alignment_id = a.id JOIN gender g ON s.gender_id = g.id WHERE a.id = 1   AND g.id = 2;
SELECT T1.superhero_name FROM superhero AS T1 JOIN hero_attribute AS T2   ON T1.id = T2.hero_id WHERE T2.attribute_value BETWEEN 75 AND 80;
SELECT r.race FROM superhero s JOIN gender g ON s.gender_id = g.id JOIN colour c ON s.hair_colour_id = c.id JOIN race r ON s.race_id = r.id WHERE g.gender = 'Male'   AND c.colour = 'Blue';
SELECT   CAST(SUM(CASE WHEN g.id = 2 THEN 1 ELSE 0 END) AS REAL) * 100.0 / COUNT(*) FROM superhero s JOIN alignment a ON s.alignment_id = a.id JOIN gender g ON s.gender_id = g.id WHERE a.id = 2;
SELECT   SUM(CASE WHEN s.eye_colour_id = 7 THEN 1 ELSE 0 END) -   SUM(CASE WHEN s.eye_colour_id = 1 THEN 1 ELSE 0 END) AS difference FROM superhero s WHERE s.weight_kg IS NULL OR s.weight_kg = 0;
SELECT     ha.attribute_value FROM hero_attribute AS ha JOIN attribute AS a     ON ha.attribute_id = a.id JOIN superhero AS s     ON ha.hero_id = s.id WHERE     a.attribute_name = 'Strength'     AND s.superhero_name = 'Hulk';
SELECT sp.power_name FROM superhero s JOIN hero_power hp ON s.id = hp.hero_id JOIN superpower sp ON hp.power_id = sp.id WHERE s.superhero_name = 'Ajax';
SELECT COUNT(*) FROM superhero s JOIN colour c ON s.skin_colour_id = c.id JOIN alignment a ON s.alignment_id = a.id WHERE c.colour = 'Green'   AND a.alignment = 'Bad';
SELECT COUNT(*) FROM superhero s JOIN gender g ON s.gender_id = g.id JOIN publisher p ON s.publisher_id = p.id WHERE g.gender = 'Female'   AND p.publisher_name = 'Marvel Comics';
SELECT     s.superhero_name FROM superhero AS s JOIN hero_power AS hp     ON s.id = hp.hero_id JOIN superpower AS sp     ON hp.power_id = sp.id WHERE     sp.power_name = 'Wind Control' ORDER BY     s.superhero_name ASC;
SELECT g.gender FROM superhero s JOIN hero_power hp ON s.id = hp.hero_id JOIN superpower sp ON hp.power_id = sp.id JOIN gender g ON s.gender_id = g.id WHERE sp.power_name = 'Phoenix Force';
SELECT s.superhero_name FROM superhero s JOIN publisher p ON s.publisher_id = p.id WHERE p.publisher_name = 'DC Comics' ORDER BY s.weight_kg DESC LIMIT 1;
SELECT AVG(s.height_cm) FROM superhero s JOIN race r ON s.race_id = r.id JOIN publisher p ON s.publisher_id = p.id WHERE r.race <> 'Human'   AND p.publisher_name = 'Dark Horse Comics';
SELECT COUNT(*) FROM hero_attribute ha JOIN attribute a ON ha.attribute_id = a.id WHERE a.attribute_name = 'Speed'   AND ha.attribute_value = 100;
SELECT      SUM(CASE WHEN p.publisher_name = 'DC Comics' THEN 1 ELSE 0 END) -      SUM(CASE WHEN p.publisher_name = 'Marvel Comics' THEN 1 ELSE 0 END) AS difference FROM superhero s JOIN publisher p ON s.publisher_id = p.id WHERE p.publisher_name IN ('DC Comics', 'Marvel Comics');
SELECT     a.attribute_name FROM superhero AS s JOIN hero_attribute AS ha     ON s.id = ha.hero_id JOIN attribute AS a     ON ha.attribute_id = a.id WHERE     s.superhero_name = 'Black Panther' ORDER BY     ha.attribute_value ASC LIMIT 1;
SELECT c.colour FROM superhero s JOIN colour c ON s.eye_colour_id = c.id WHERE s.superhero_name = 'Abomination';
SELECT s.superhero_name FROM superhero s ORDER BY s.height_cm DESC LIMIT 1;
SELECT superhero_name FROM superhero WHERE full_name = 'Charles Chandler';
SELECT      CAST(SUM(CASE WHEN g.gender = 'Female' THEN 1 ELSE 0 END) AS REAL) * 100.0 / COUNT(*) AS percentage FROM superhero s JOIN publisher p ON s.publisher_id = p.id JOIN gender g ON s.gender_id = g.id WHERE p.publisher_name = 'George Lucas';
SELECT     CAST(SUM(CASE WHEN a.alignment = 'Good' THEN 1 ELSE 0 END) AS REAL) * 100.0 / COUNT(*) FROM superhero s JOIN publisher p ON s.publisher_id = p.id JOIN alignment a ON s.alignment_id = a.id WHERE p.publisher_name = 'Marvel Comics';
SELECT COUNT(*) FROM superhero WHERE full_name LIKE 'John%';
SELECT hero_id FROM hero_attribute ORDER BY attribute_value ASC LIMIT 1;
SELECT s.full_name FROM superhero s JOIN race r ON s.race_id = r.id WHERE r.race = 'Alien';
SELECT     s.full_name FROM superhero AS s WHERE     s.weight_kg < 100     AND s.eye_colour_id = (         SELECT c.id         FROM colour AS c         WHERE c.colour = 'Brown'     );
SELECT     ha.attribute_value FROM superhero AS s JOIN hero_attribute AS ha     ON s.id = ha.hero_id WHERE     s.superhero_name = 'Aquababy';
SELECT s.weight_kg, r.race FROM superhero s JOIN race r ON s.race_id = r.id WHERE s.id = 40;
SELECT AVG(s.height_cm) AS average_height FROM superhero s JOIN alignment a ON s.alignment_id = a.id WHERE a.alignment = 'Neutral';
SELECT     hp.hero_id FROM hero_power AS hp JOIN superpower AS sp     ON hp.power_id = sp.id WHERE sp.power_name = 'Intelligence';
SELECT c.colour FROM superhero s JOIN colour c ON s.eye_colour_id = c.id WHERE s.superhero_name = 'Blackwulf';
SELECT     sp.power_name FROM superhero AS s JOIN hero_power AS hp     ON s.id = hp.hero_id JOIN superpower AS sp     ON hp.power_id = sp.id WHERE s.height_cm > (     SELECT AVG(height_cm) * 0.8     FROM superhero );
SELECT     d.driverRef FROM qualifying AS q JOIN drivers AS d   ON q.driverId = d.driverId WHERE q.raceId = 20   AND q.q1 IN (       SELECT q1       FROM qualifying       WHERE raceId = 20       ORDER BY q1 DESC       LIMIT 5   );
SELECT d.surname FROM qualifying q JOIN drivers d ON q.driverId = d.driverId WHERE q.raceId = 19   AND q.q2 IS NOT NULL ORDER BY q.q2 ASC LIMIT 1;
SELECT DISTINCT r.year FROM races r JOIN circuits c ON r.circuitId = c.circuitId WHERE c.location = 'Shanghai';
SELECT r.url FROM races r JOIN circuits c ON r.circuitId = c.circuitId WHERE c.name = 'Circuit de Barcelona-Catalunya';
SELECT r.name FROM races r JOIN circuits c ON r.circuitId = c.circuitId WHERE c.country = 'Germany';
SELECT     c.circuitId FROM circuits AS c JOIN races AS r   ON c.circuitId = r.circuitId JOIN constructorResults AS cr   ON r.raceId = cr.raceId JOIN constructors AS cons   ON cr.constructorId = cons.constructorId WHERE cons.name = 'Renault';
SELECT COUNT(*) FROM races r JOIN circuits c ON r.circuitId = c.circuitId WHERE r.year = 2010   AND c.country NOT IN ('Asia', 'Europe');
SELECT r.name FROM races r JOIN circuits c ON r.circuitId = c.circuitId WHERE c.country = 'Spain';
SELECT     c.lat,     c.lng FROM circuits AS c JOIN races AS r     ON c.circuitId = r.circuitId WHERE r.name = 'Australian Grand Prix';
SELECT r.url FROM races r JOIN circuits c ON r.circuitId = c.circuitId WHERE c.name = 'Sepang International Circuit';
SELECT     r.time FROM races AS r JOIN circuits AS c     ON r.circuitId = c.circuitId WHERE c.name = 'Sepang International Circuit';
SELECT     c.lat,     c.lng FROM races AS r JOIN circuits AS c     ON r.circuitId = c.circuitId WHERE r.name = 'Abu Dhabi Grand Prix';
SELECT c.nationality FROM constructorResults cr JOIN constructors c ON cr.constructorId = c.constructorId WHERE cr.raceId = 24   AND cr.points = 1;
SELECT     q.q1 FROM qualifying AS q JOIN drivers AS d     ON q.driverId = d.driverId JOIN races AS r     ON q.raceId = r.raceId WHERE     d.forename = 'Bruno'     AND d.surname = 'Senna'     AND r.raceId = 354;
SELECT d.nationality FROM qualifying q JOIN drivers d ON q.driverId = d.driverId WHERE q.raceId = 355   AND q.q2 = '0:01:40';
SELECT     d.number FROM qualifying AS q JOIN drivers AS d   ON q.driverId = d.driverId WHERE     q.raceId = 903     AND q.q3 LIKE '1:54%';
SELECT COUNT(*) AS count FROM results r JOIN races ra ON r.raceId = ra.raceId WHERE ra.name = 'Bahrain Grand Prix'   AND ra.year = 2007   AND r.time IS NULL;
SELECT s.url FROM seasons s JOIN races r ON s.year = r.year WHERE r.raceId = 901;
SELECT COUNT(DISTINCT r.driverId) FROM results r JOIN races ra ON r.raceId = ra.raceId WHERE ra.date = '2015-11-29'   AND r.time IS NOT NULL;
SELECT d.* FROM drivers d JOIN results r ON d.driverId = r.driverId WHERE r.raceId = 592   AND r.time IS NOT NULL ORDER BY d.dob ASC LIMIT 1;
SELECT d.url FROM lapTimes lt JOIN drivers d ON lt.driverId = d.driverId WHERE lt.raceId = 161   AND lt.time LIKE '1:27%';
SELECT d.nationality FROM results r JOIN drivers d ON r.driverId = d.driverId WHERE r.raceId = 933 ORDER BY r.fastestLapSpeed DESC LIMIT 1;
SELECT c.lat, c.lng FROM races r JOIN circuits c ON r.circuitId = c.circuitId WHERE r.name = 'Malaysian Grand Prix';
SELECT     c.url FROM constructorResults AS cr JOIN constructors AS c     ON cr.constructorId = c.constructorId WHERE     cr.raceId = 9 ORDER BY     cr.points DESC LIMIT 1;
SELECT q.q1 FROM qualifying q JOIN drivers d ON q.driverId = d.driverId WHERE d.forename = 'Lucas'   AND d.surname = 'di Grassi'   AND q.raceId = 345;
SELECT d.nationality FROM qualifying q JOIN drivers d ON q.driverId = d.driverId WHERE q.raceId = 347   AND q.q2 = '0:01:15';
SELECT d.code FROM qualifying q JOIN drivers d ON q.driverId = d.driverId WHERE q.raceId = 45   AND q.q3 LIKE '1:33%';
SELECT     r.time FROM results AS r JOIN drivers AS d     ON r.driverId = d.driverId WHERE     r.raceId = 743     AND d.forename = 'Bruce'     AND d.surname = 'McLaren';
SELECT     d.forename,     d.surname FROM results r JOIN races ra     ON r.raceId = ra.raceId JOIN drivers d     ON r.driverId = d.driverId WHERE ra.name = 'San Marino Grand Prix'   AND ra.year = 2006   AND r.position = 2;
SELECT s.url FROM seasons s JOIN races r ON s.year = r.year WHERE r.raceId = 901;
SELECT COUNT(DISTINCT r.driverId) AS drivers_not_finished FROM results r JOIN races ra ON r.raceId = ra.raceId JOIN status s ON r.statusId = s.statusId WHERE ra.date = '2015-11-29'   AND s.status <> 'Finished'   AND r.time IS NOT NULL;
SELECT d.* FROM drivers d JOIN results r   ON d.driverId = r.driverId WHERE r.raceId = 872   AND r.time IS NOT NULL ORDER BY d.dob DESC LIMIT 1;
SELECT     d.forename,     d.surname FROM lapTimes AS lt JOIN drivers AS d     ON lt.driverId = d.driverId WHERE lt.raceId = 348 ORDER BY lt.time ASC LIMIT 1;
SELECT d.nationality FROM results r JOIN drivers d ON r.driverId = d.driverId WHERE r.fastestLapSpeed = (     SELECT MAX(fastestLapSpeed)     FROM results     WHERE fastestLapSpeed IS NOT NULL );
SELECT   CAST((r853.fastestLapSpeed - r854.fastestLapSpeed) AS REAL) * 100 / r853.fastestLapSpeed FROM   results AS r853   JOIN drivers AS d853     ON r853.driverId = d853.driverId   JOIN results AS r854     ON r854.raceId = 854   JOIN drivers AS d854     ON r854.driverId = d854.driverId WHERE   r853.raceId = 853   AND d853.forename = 'Paul'   AND d853.surname = 'di Resta'   AND d854.forename = 'Paul'   AND d854.surname = 'di Resta';
SELECT   CAST(COUNT(CASE WHEN r.time IS NOT NULL THEN r.driverId END) AS REAL) * 100 / COUNT(r.driverId) AS race_completion_rate FROM results r JOIN races ra ON r.raceId = ra.raceId WHERE ra.date = '1983-07-16';
SELECT MIN(r.year) AS year FROM races r JOIN circuits c ON r.circuitId = c.circuitId WHERE r.name = 'Singapore Grand Prix';
SELECT COUNT(*) AS race_count,        GROUP_CONCAT(name, ' | ') AS race_names FROM races WHERE year = 2005 ORDER BY raceId DESC;
SELECT r.name FROM races r WHERE strftime('%Y-%m', r.date) = (     SELECT strftime('%Y-%m', MIN(date))     FROM races );
SELECT     r.name,     r.date FROM races AS r WHERE r.year = 1999 ORDER BY r.round DESC LIMIT 1;
SELECT year FROM races GROUP BY year ORDER BY COUNT(raceId) DESC LIMIT 1;
SELECT r.name FROM races r WHERE r.year = 2017   AND r.circuitId NOT IN (     SELECT r2.circuitId     FROM races r2     WHERE r2.year = 2000   );
SELECT   c.country,   c.name AS circuit,   c.location FROM races r JOIN circuits c   ON r.circuitId = c.circuitId WHERE r.name = 'European Grand Prix' ORDER BY r.year ASC LIMIT 1;
SELECT     MAX(r.year) FROM races AS r JOIN circuits AS c   ON r.circuitId = c.circuitId WHERE     c.name = 'Brands Hatch'     AND r.name = 'British Grand Prix';
SELECT COUNT(DISTINCT r.year) AS seasons FROM races r JOIN circuits c ON r.circuitId = c.circuitId WHERE c.name = 'Silverstone Circuit'   AND r.name = 'British Grand Prix';
SELECT     d.forename,     d.surname FROM driverStandings AS ds JOIN races AS r     ON ds.raceId = r.raceId JOIN drivers AS d     ON ds.driverId = d.driverId WHERE r.year = 2010   AND r.name = 'Singapore Grand Prix' ORDER BY ds.position;
WITH DriverPoints AS (     SELECT          d.driverId,         d.forename,         d.surname,         SUM(r.points) AS total_points     FROM          drivers d     JOIN          results r ON d.driverId = r.driverId     GROUP BY          d.driverId, d.forename, d.surname ), RankedDrivers AS (     SELECT          driverId,         forename,         surname,         total_points,         RANK() OVER (ORDER BY total_points DESC) AS rank     FROM          DriverPoints ) SELECT      forename,     surname,     total_points FROM      RankedDrivers WHERE      rank = 1 LIMIT 1;
SELECT     d.forename,     d.surname,     r.points FROM results r JOIN races ra ON r.raceId = ra.raceId JOIN drivers d ON r.driverId = d.driverId WHERE ra.year = 2017   AND ra.name = 'Chinese Grand Prix' ORDER BY r.position ASC LIMIT 3;
SELECT     d.forename,     d.surname,     r.name FROM lapTimes AS lt JOIN drivers AS d     ON lt.driverId = d.driverId JOIN races AS r     ON lt.raceId = r.raceId ORDER BY lt.milliseconds ASC LIMIT 1;
SELECT AVG(lt.milliseconds) AS average_lap_time FROM lapTimes lt JOIN drivers d ON lt.driverId = d.driverId JOIN races r ON lt.raceId = r.raceId WHERE d.forename = 'Lewis'   AND d.surname = 'Hamilton'   AND r.name = 'Malaysian Grand Prix'   AND r.year = 2009;
SELECT   CAST(COUNT(CASE WHEN r.position > 1 THEN r.raceId END) AS REAL) * 100.0 / COUNT(r.raceId) FROM results r JOIN drivers d ON r.driverId = d.driverId JOIN races ra ON r.raceId = ra.raceId WHERE d.surname = 'Hamilton'   AND ra.year >= 2010;
WITH driver_wins AS (     SELECT         d.driverId,         d.forename,         d.surname,         d.nationality,         SUM(ds.wins) AS total_wins     FROM drivers d     JOIN driverStandings ds ON d.driverId = ds.driverId     GROUP BY d.driverId, d.forename, d.surname, d.nationality ), max_wins AS (     SELECT MAX(total_wins) AS max_total_wins     FROM driver_wins ), driver_max_points AS (     SELECT         d.driverId,         MAX(ds.points) AS max_points     FROM drivers d     JOIN driverStandings ds ON d.driverId = ds.driverId     GROUP BY d.driverId ) SELECT     dw.forename,     dw.surname,     dw.nationality,     dmp.max_points FROM driver_wins dw JOIN max_wins mw ON dw.total_wins = mw.max_total_wins JOIN driver_max_points dmp ON dw.driverId = dmp.driverId;
SELECT      (strftime('%Y', 'now') - strftime('%Y', dob)) AS age,     forename || ' ' || surname AS name FROM      drivers WHERE      nationality = 'Japanese' ORDER BY      dob DESC LIMIT 1;
SELECT c.circuitId FROM circuits c JOIN races r ON c.circuitId = r.circuitId WHERE r.year BETWEEN 1990 AND 2000 GROUP BY c.circuitId HAVING COUNT(r.raceId) = 4;
SELECT     c.name AS circuit_name,     c.location AS circuit_location,     r.name AS race_name FROM circuits c JOIN races r     ON c.circuitId = r.circuitId WHERE     c.country = 'USA'     AND r.year = 2006;
SELECT     r.name,     c.name,     c.location FROM races AS r JOIN circuits AS c     ON r.circuitId = c.circuitId WHERE     strftime('%m', r.date) = '09'     AND strftime('%Y', r.date) = '2005';
SELECT r.name FROM results res JOIN drivers d ON res.driverId = d.driverId JOIN races r ON res.raceId = r.raceId WHERE d.forename = 'Alex'   AND d.surname = 'Yoong'   AND res.position < 20;
SELECT COUNT(*) AS win_count FROM results r JOIN drivers d ON r.driverId = d.driverId JOIN races ra ON r.raceId = ra.raceId JOIN circuits c ON ra.circuitId = c.circuitId WHERE d.forename = 'Michael'   AND d.surname = 'Schumacher'   AND c.name = 'Sepang International Circuit'   AND r.points = (       SELECT MAX(r2.points)       FROM results r2       WHERE r2.raceId = r.raceId   );
SELECT     r.name AS race,     r.year AS year FROM results AS res JOIN drivers AS d     ON res.driverId = d.driverId JOIN races AS r     ON res.raceId = r.raceId WHERE     d.forename = 'Michael'     AND d.surname = 'Schumacher'     AND res.fastestLap IS NOT NULL ORDER BY     res.milliseconds ASC LIMIT 1;
SELECT AVG(r.points) AS average_points FROM results r JOIN drivers d ON r.driverId = d.driverId JOIN races ra ON r.raceId = ra.raceId WHERE d.forename = 'Eddie'   AND d.surname = 'Irvine'   AND ra.year = 2000;
SELECT     r.year,     res.points FROM results AS res JOIN drivers AS d     ON res.driverId = d.driverId JOIN races AS r     ON res.raceId = r.raceId WHERE     d.forename = 'Lewis'     AND d.surname = 'Hamilton' ORDER BY     r.year ASC LIMIT 1;
SELECT     r.raceId,     r.name,     c.country FROM     races r JOIN     circuits c     ON r.circuitId = c.circuitId WHERE     r.year = 2017 ORDER BY     r.date;
SELECT     r.name,     r.year,     c.location FROM results AS res JOIN races AS r   ON res.raceId = r.raceId JOIN circuits AS c   ON r.circuitId = c.circuitId ORDER BY res.laps DESC LIMIT 1;
SELECT      CAST(SUM(CASE WHEN c.country = 'Germany' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(*)  FROM races r JOIN circuits c ON r.circuitId = c.circuitId WHERE r.name = 'European Grand Prix';
SELECT lat, lng FROM circuits WHERE name = 'Silverstone Circuit';
SELECT name FROM circuits WHERE name IN ('Silverstone Circuit', 'Hockenheimring', 'Hungaroring') ORDER BY lat DESC LIMIT 1;
SELECT circuitRef FROM circuits WHERE name = 'Marina Bay Street Circuit';
SELECT country FROM circuits ORDER BY alt DESC LIMIT 1;
SELECT COUNT(*) FROM drivers WHERE code IS NULL;
SELECT      d.nationality FROM      drivers d ORDER BY      d.dob ASC LIMIT 1;
SELECT surname FROM drivers WHERE nationality = 'Italian';
SELECT url FROM drivers WHERE forename = 'Anthony' AND surname = 'Davidson';
SELECT driverRef FROM drivers WHERE forename = 'Lewis' AND surname = 'Hamilton';
SELECT c.name FROM circuits c JOIN races r ON c.circuitId = r.circuitId WHERE r.year = 2009   AND r.name = 'Spanish Grand Prix';
SELECT DISTINCT r.year FROM races r JOIN circuits c ON r.circuitId = c.circuitId WHERE c.name = 'Silverstone Circuit';
SELECT T1.url FROM races AS T1 JOIN circuits AS T2   ON T1.circuitId = T2.circuitId WHERE T2.name = 'Silverstone Circuit';
SELECT r.time FROM races r JOIN circuits c ON r.circuitId = c.circuitId WHERE r.year = 2010   AND c.name = 'Abu Dhabi Circuit';
SELECT COUNT(*) AS race_count FROM races r JOIN circuits c ON r.circuitId = c.circuitId WHERE c.country = 'Italy';
SELECT     r.date FROM races AS r JOIN circuits AS c     ON r.circuitId = c.circuitId WHERE c.name = 'Circuit de Barcelona-Catalunya';
SELECT DISTINCT c.url FROM circuits c JOIN races r   ON c.circuitId = r.circuitId WHERE r.name = 'Spanish Grand Prix'   AND r.year = 2009;
SELECT MIN(r.fastestLapTime) FROM results r JOIN drivers d ON r.driverId = d.driverId WHERE d.forename = 'Lewis'   AND d.surname = 'Hamilton';
SELECT     d.forename,     d.surname FROM results r JOIN drivers d     ON r.driverId = d.driverId ORDER BY     CAST(r.fastestLapSpeed AS REAL) DESC LIMIT 1;
SELECT     d.driverRef FROM results r JOIN races ra     ON r.raceId = ra.raceId JOIN drivers d     ON r.driverId = d.driverId WHERE     ra.name = 'Canadian Grand Prix'     AND ra.year = 2007     AND r.position = 1;
SELECT DISTINCT r.name FROM races r JOIN results res ON r.raceId = res.raceId JOIN drivers d ON res.driverId = d.driverId WHERE d.forename = 'Lewis' AND d.surname = 'Hamilton';
SELECT     r.name FROM     results AS res JOIN     drivers AS d     ON res.driverId = d.driverId JOIN     races AS r     ON res.raceId = r.raceId WHERE     d.forename = 'Lewis'     AND d.surname = 'Hamilton'     AND res.rank IS NOT NULL ORDER BY     res.rank ASC,     res.raceId ASC LIMIT 1;
SELECT MAX(r.fastestLapSpeed) FROM results r JOIN races ra ON r.raceId = ra.raceId WHERE ra.name = 'Spanish Grand Prix'   AND ra.year = 2009;
SELECT DISTINCT r.year FROM races r JOIN results res ON r.raceId = res.raceId JOIN drivers d ON res.driverId = d.driverId WHERE d.forename = 'Lewis'   AND d.surname = 'Hamilton';
SELECT     r.positionOrder FROM results AS r JOIN drivers AS d     ON r.driverId = d.driverId JOIN races AS ra     ON r.raceId = ra.raceId WHERE     d.forename = 'Lewis'     AND d.surname = 'Hamilton'     AND ra.name = 'Chinese Grand Prix'     AND ra.year = 2008;
SELECT     d.forename,     d.surname FROM results r JOIN races ra     ON r.raceId = ra.raceId JOIN drivers d     ON r.driverId = d.driverId JOIN circuits c     ON ra.circuitId = c.circuitId WHERE     ra.year = 1989     AND ra.name = 'Australian Grand Prix'     AND r.grid = 4;
SELECT COUNT(*) AS count FROM results r JOIN races ra ON r.raceId = ra.raceId WHERE ra.year = 2008   AND ra.name = 'Australian Grand Prix'   AND r.time IS NOT NULL;
SELECT     MIN(r.fastestLapTime) AS fastest_lap FROM     results r JOIN     drivers d ON r.driverId = d.driverId JOIN     races ra ON r.raceId = ra.raceId WHERE     d.forename = 'Lewis'     AND d.surname = 'Hamilton'     AND ra.year = 2008     AND ra.name = 'Australian Grand Prix';
SELECT     r.time FROM results AS r JOIN races AS ra     ON r.raceId = ra.raceId WHERE     ra.year = 2008     AND ra.name = 'Chinese Grand Prix'     AND r.position = 2;
SELECT     d.forename,     d.surname,     d.url FROM results r JOIN races ra     ON r.raceId = ra.raceId JOIN drivers d     ON r.driverId = d.driverId WHERE ra.year = 2008   AND ra.name = 'Australian Grand Prix'   AND r.position = 1   AND r.statusId = 1   AND r.time IS NOT NULL   AND r.time GLOB '[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]' LIMIT 1;
SELECT COUNT(DISTINCT r.driverId) AS driver_count FROM results r JOIN races ra ON r.raceId = ra.raceId JOIN drivers d ON r.driverId = d.driverId WHERE ra.year = 2008   AND ra.name = 'Australian Grand Prix'   AND d.nationality = 'British';
SELECT COUNT(DISTINCT r.driverId) FROM results r JOIN races ra ON r.raceId = ra.raceId WHERE ra.year = 2008   AND ra.name = 'Chinese Grand Prix'   AND r.time IS NOT NULL   AND r.time != ''   AND EXISTS (     SELECT 1     FROM results r2     WHERE r2.driverId = r.driverId   );
SELECT   SUM(r.points) FROM results AS r JOIN drivers AS d   ON r.driverId = d.driverId WHERE   d.forename = 'Lewis'   AND d.surname = 'Hamilton';
SELECT AVG(     CAST(SUBSTR(r.fastestLapTime, 1, INSTR(r.fastestLapTime, ':') - 1) AS REAL) * 60 +     CAST(SUBSTR(r.fastestLapTime, INSTR(r.fastestLapTime, ':') + 1) AS REAL) ) AS average_fastest_lap_time_seconds FROM results r JOIN drivers d ON r.driverId = d.driverId WHERE d.forename = 'Lewis'   AND d.surname = 'Hamilton'   AND r.fastestLapTime IS NOT NULL;
SELECT   CAST(COUNT(CASE WHEN r.time IS NOT NULL THEN 1 END) AS REAL) * 100 / COUNT(r.raceId) AS rate FROM results r JOIN races ra ON r.raceId = ra.raceId WHERE ra.year = 2008   AND ra.name = 'Australian Grand Prix';
WITH race_info AS (     SELECT          r.raceId,         r.year,         r.name     FROM races r     WHERE r.year = 2008        AND r.name = 'Australian Grand Prix' ), champion AS (     SELECT          res.driverId,         res.time AS champion_time,         res.milliseconds AS champion_ms     FROM results res     JOIN race_info ri ON res.raceId = ri.raceId     WHERE res.position = 1       AND res.time IS NOT NULL ), last_driver AS (     SELECT          res.driverId,         res.time AS last_time,         res.milliseconds AS last_ms     FROM results res     JOIN race_info ri ON res.raceId = ri.raceId     WHERE res.positionText = 'R'       AND res.time IS NOT NULL ), times AS (     SELECT          c.champion_ms,         l.last_ms,         (l.last_ms - c.champion_ms) AS incremental_ms     FROM champion c     CROSS JOIN last_driver l ) SELECT      ROUND(         (incremental_ms * 100.0) / last_ms,          2     ) AS percentage_faster FROM times;
SELECT COUNT(*) FROM circuits WHERE country = 'Australia' AND location = 'Adelaide';
SELECT lat, lng FROM circuits WHERE country = 'USA';
SELECT COUNT(*) FROM drivers WHERE nationality = 'British' AND dob > '1980-01-01';
SELECT MAX(cr.points) FROM constructorResults AS cr JOIN constructors AS c   ON cr.constructorId = c.constructorId WHERE c.nationality = 'British';
SELECT c.name FROM constructorStandings cs JOIN constructors c ON cs.constructorId = c.constructorId ORDER BY cs.points DESC LIMIT 1;
SELECT     c.name FROM constructorResults AS cr JOIN constructors AS c     ON cr.constructorId = c.constructorId WHERE     cr.raceId = 291     AND cr.points = 0;
SELECT COUNT(*) FROM (     SELECT         cr.constructorId     FROM constructorResults AS cr     JOIN constructors AS c         ON cr.constructorId = c.constructorId     WHERE c.nationality = 'Japanese'       AND cr.points = 0     GROUP BY cr.constructorId     HAVING COUNT(cr.raceId) = 2 ) AS sub;
SELECT DISTINCT c.name FROM constructorStandings cs JOIN constructors c ON cs.constructorId = c.constructorId WHERE cs.position = 1;
SELECT COUNT(*) FROM constructors c JOIN lapTimes lt ON c.constructorId = (     SELECT r.constructorId     FROM results r     WHERE r.raceId = lt.raceId       AND r.driverId = lt.driverId ) WHERE c.nationality = 'France'   AND lt.lap > 50;
SELECT   CAST(COUNT(CASE WHEN r.time IS NOT NULL THEN d.driverId END) AS REAL) * 100 / COUNT(d.driverId) AS completion_percentage FROM results r JOIN drivers d   ON r.driverId = d.driverId JOIN races ra   ON r.raceId = ra.raceId WHERE d.nationality = 'Japanese'   AND ra.year BETWEEN 2007 AND 2009;
WITH champion_results AS (     SELECT         r.year,         CAST(SUBSTR(res.time, 1, 2) AS INTEGER) * 3600 +         CAST(SUBSTR(res.time, 4, 2) AS INTEGER) * 60 +         CAST(SUBSTR(res.time, 7, 2) AS INTEGER) +         CAST(SUBSTR(res.time, 10, 3) AS REAL) / 1000.0 AS time_seconds     FROM results res     JOIN races r ON res.raceId = r.raceId     WHERE res.position = 1       AND res.time IS NOT NULL       AND r.year < 1975 ) SELECT     year,     AVG(time_seconds) AS avg_time_seconds FROM champion_results GROUP BY year;
SELECT     d.forename,     d.surname FROM drivers AS d JOIN driverStandings AS ds     ON d.driverId = ds.driverId WHERE     CAST(substr(d.dob, 1, 4) AS INTEGER) > 1975     AND ds.position = 2;
SELECT COUNT(*) FROM results r JOIN drivers d ON r.driverId = d.driverId WHERE d.nationality = 'Italian'   AND r.time IS NULL;
SELECT d.forename, d.surname FROM results r JOIN drivers d ON r.driverId = d.driverId WHERE r.fastestLapTime IS NOT NULL ORDER BY r.fastestLapTime ASC LIMIT 1;
SELECT     T1.fastestLap FROM results AS T1 INNER JOIN races AS T2     ON T1.raceId = T2.raceId WHERE     T2.year = 2009     AND T1.position = 1 ORDER BY     T1.milliseconds ASC LIMIT 1;
SELECT AVG(r.fastestLapSpeed) FROM results r JOIN races ra ON r.raceId = ra.raceId WHERE ra.name = 'Spanish Grand Prix'   AND ra.year = 2009;
SELECT     r.name,     r.year FROM results AS res JOIN races AS r   ON res.raceId = r.raceId WHERE res.milliseconds IS NOT NULL ORDER BY res.milliseconds ASC LIMIT 1;
SELECT   CAST(     SUM(CASE WHEN CAST(SUBSTR(d.dob, 1, 4) AS INTEGER) < 1985 AND r.laps > 50 THEN 1 ELSE 0 END) AS REAL   ) * 100 / COUNT(r.driverId) AS percentage FROM results r JOIN races ra ON r.raceId = ra.raceId JOIN drivers d ON r.driverId = d.driverId WHERE ra.year BETWEEN 2000 AND 2005;
SELECT COUNT(*) FROM lapTimes lt JOIN drivers d ON lt.driverId = d.driverId WHERE d.nationality = 'French'   AND lt.milliseconds < 120000;
SELECT code FROM drivers WHERE nationality = 'America';
SELECT raceId FROM races WHERE year = 2009;
SELECT COUNT(driverId) AS driver_count FROM results WHERE raceId = 18;
WITH YoungestDrivers AS (     SELECT          d.driverId,         d.code,         d.nationality,         d.dob,         ROW_NUMBER() OVER (ORDER BY d.dob DESC) AS rn     FROM drivers d ) SELECT      yd.code,     SUM(CASE WHEN yd.nationality = 'Dutch' THEN 1 ELSE 0 END) AS dutch_count FROM YoungestDrivers yd WHERE yd.rn <= 3;
SELECT driverRef FROM drivers WHERE forename = 'Robert' AND surname = 'Kubica';
SELECT COUNT(*) FROM drivers WHERE nationality = 'British' AND strftime('%Y', dob) = '1980';
WITH german_drivers AS (     SELECT          d.driverId,         d.forename,         d.surname,         d.dob     FROM drivers d     WHERE d.nationality = 'German'       AND strftime('%Y', d.dob) BETWEEN '1980' AND '1990' ), earliest_lap AS (     SELECT          lt.driverId,         MIN(lt.time) AS min_time     FROM lapTimes lt     INNER JOIN german_drivers gd ON lt.driverId = gd.driverId     GROUP BY lt.driverId ) SELECT      gd.forename,     gd.surname,     el.min_time FROM german_drivers gd INNER JOIN earliest_lap el ON gd.driverId = el.driverId ORDER BY el.min_time ASC LIMIT 3;
SELECT driverRef FROM drivers WHERE nationality = 'German' ORDER BY dob ASC LIMIT 1;
SELECT     d.driverId,     d.code FROM drivers AS d JOIN results AS r   ON d.driverId = r.driverId WHERE     strftime('%Y', d.dob) = '1971'     AND r.fastestLapTime IS NOT NULL;
WITH spanish_drivers AS (     SELECT          d.driverId,         d.forename,         d.surname,         d.dob     FROM drivers d     WHERE d.nationality = 'Spanish'       AND strftime('%Y', d.dob) < '1982' ), latest_lap_times AS (     SELECT          lt.driverId,         MAX(lt.time) AS latest_time     FROM lapTimes lt     JOIN spanish_drivers sd ON lt.driverId = sd.driverId     GROUP BY lt.driverId ) SELECT      sd.forename,     sd.surname,     ll.latest_time FROM spanish_drivers sd JOIN latest_lap_times ll ON sd.driverId = ll.driverId ORDER BY ll.latest_time DESC LIMIT 10;
SELECT r.year FROM results res JOIN races r ON res.raceId = r.raceId WHERE res.fastestLapTime IS NOT NULL ORDER BY res.fastestLapTime ASC LIMIT 1;
SELECT     r.year FROM     races AS r JOIN     lapTimes AS lt     ON r.raceId = lt.raceId GROUP BY     r.year ORDER BY     MAX(lt.time) ASC LIMIT 1;
SELECT     driverId FROM lapTimes WHERE lap = 1 ORDER BY time ASC LIMIT 5;
SELECT COUNT(*) AS disqualified_finishers FROM results WHERE raceId > 50   AND raceId < 100   AND statusId = 2   AND time IS NOT NULL;
SELECT     COUNT(*) AS count,     c.location,     c.lat,     c.lng FROM circuits AS c WHERE c.country = 'Austria';
SELECT r.raceId FROM results res JOIN races r ON res.raceId = r.raceId WHERE res.time IS NOT NULL GROUP BY res.raceId ORDER BY COUNT(*) DESC LIMIT 1;
SELECT     d.driverRef,     d.nationality,     d.dob FROM qualifying q JOIN drivers d     ON q.driverId = d.driverId WHERE     q.raceId = 23     AND q.q2 IS NOT NULL;
WITH YoungestDriver AS (     SELECT          d.driverId,         d.dob,         d.forename,         d.surname     FROM drivers d     WHERE d.dob IS NOT NULL     ORDER BY d.dob DESC     LIMIT 1 ), FirstQualifyingRace AS (     SELECT          q.raceId,         r.year,         r.name,         r.date,         r.time     FROM qualifying q     JOIN races r ON q.raceId = r.raceId     WHERE q.driverId = (SELECT driverId FROM YoungestDriver)     ORDER BY r.date ASC     LIMIT 1 ) SELECT      fqr.year,     fqr.name,     fqr.date,     fqr.time FROM FirstQualifyingRace fqr;
SELECT COUNT(*) FROM drivers d JOIN results r   ON d.driverId = r.driverId JOIN status s   ON r.statusId = s.statusId WHERE d.nationality = 'American'   AND s.status = 'Puncture';
SELECT     c.url FROM constructors AS c WHERE c.nationality = 'Italian' ORDER BY     (         SELECT             SUM(cr.points)         FROM constructorResults AS cr         WHERE cr.constructorId = c.constructorId     ) DESC LIMIT 1;
SELECT     c.url FROM constructors AS c JOIN constructorStandings AS cs     ON c.constructorId = cs.constructorId GROUP BY     c.constructorId,     c.url ORDER BY     SUM(cs.wins) DESC LIMIT 1;
SELECT     d.forename,     d.surname FROM lapTimes AS lt JOIN drivers AS d     ON lt.driverId = d.driverId JOIN races AS r     ON lt.raceId = r.raceId WHERE     r.name = 'French Grand Prix'     AND lt.lap = 3 ORDER BY     lt.milliseconds DESC LIMIT 1;
SELECT     r.raceId,     lt.milliseconds FROM lapTimes AS lt JOIN races AS r   ON lt.raceId = r.raceId WHERE lt.lap = 1 ORDER BY lt.milliseconds ASC LIMIT 1;
SELECT AVG(r.fastestLapTime) FROM results r JOIN races ra ON r.raceId = ra.raceId WHERE ra.year = 2006   AND ra.name = 'United States Grand Prix'   AND r.rank < 11;
SELECT     d.forename,     d.surname FROM     drivers d JOIN     pitStops p ON d.driverId = p.driverId WHERE     d.nationality = 'German'     AND strftime('%Y', d.dob) > '1980'     AND strftime('%Y', d.dob) < '1985' GROUP BY     d.driverId,     d.forename,     d.surname ORDER BY     SUM(p.milliseconds) * 1.0 / COUNT(p.milliseconds) ASC LIMIT 3;
SELECT   r.time FROM results r JOIN races ra ON r.raceId = ra.raceId WHERE ra.year = 2008   AND ra.name = 'Canadian Grand Prix'   AND r.position = 1;
SELECT     c.constructorRef,     c.url FROM results r JOIN races ra     ON r.raceId = ra.raceId JOIN constructors c     ON r.constructorId = c.constructorId WHERE     ra.year = 2009     AND ra.name = 'Singapore Grand Prix'     AND r.position = 1;
SELECT     d.forename,     d.surname,     d.dob FROM     drivers d WHERE     d.nationality = 'Austrian'     AND d.dob BETWEEN '1981-01-01' AND '1991-12-31';
SELECT     d.forename || ' ' || d.surname AS full_name,     d.url AS wiki_page_link,     d.dob AS date_of_birth FROM     drivers d WHERE     d.nationality = 'German'     AND strftime('%Y', d.dob) BETWEEN '1971' AND '1985' ORDER BY     d.dob DESC;
SELECT location, country, lat, lng FROM circuits WHERE name = 'Hungaroring';
WITH monaco_races AS (     SELECT          r.raceId,         r.year     FROM races r     WHERE r.name = 'Monaco Grand Prix'       AND r.year BETWEEN 1980 AND 2010 ), constructor_points AS (     SELECT          cr.constructorId,         SUM(cr.points) AS total_points     FROM constructorResults cr     INNER JOIN monaco_races mr ON cr.raceId = mr.raceId     GROUP BY cr.constructorId ), top_constructor AS (     SELECT          cp.constructorId,         cp.total_points     FROM constructor_points cp     ORDER BY cp.total_points DESC     LIMIT 1 ) SELECT      tc.total_points AS score,     c.name,     c.nationality FROM top_constructor tc INNER JOIN constructors c ON tc.constructorId = c.constructorId;
SELECT AVG(r.points) FROM results r JOIN drivers d ON r.driverId = d.driverId JOIN races ra ON r.raceId = ra.raceId WHERE d.forename = 'Lewis'   AND d.surname = 'Hamilton'   AND ra.name LIKE '%Turkish Grand Prix%';
SELECT      COUNT(r.raceId) * 1.0 / 10 AS annual_average_races FROM      races r WHERE      r.date BETWEEN '2000-01-01' AND '2010-12-31';
SELECT nationality FROM drivers GROUP BY nationality ORDER BY COUNT(*) DESC LIMIT 1;
SELECT     COUNT(*) AS victories FROM     driverStandings WHERE     points = (         SELECT             points         FROM             driverStandings         ORDER BY             points DESC         LIMIT 1 OFFSET 90     )     AND wins > 0;
SELECT r.name FROM results res JOIN races r ON res.raceId = r.raceId WHERE res.fastestLapTime IS NOT NULL ORDER BY res.fastestLapTime ASC LIMIT 1;
SELECT     c.location || ', ' || c.country AS full_location FROM races r JOIN circuits c     ON r.circuitId = c.circuitId ORDER BY     r.date DESC LIMIT 1;
WITH qualifying_races AS (     SELECT          q.raceId,         q.driverId,         q.q3,         r.year,         c.name AS circuit_name     FROM qualifying q     JOIN races r ON q.raceId = r.raceId     JOIN circuits c ON r.circuitId = c.circuitId     WHERE r.year = 2008       AND c.name = 'Marina Bay Street Circuit' ), ranked_qualifying AS (     SELECT          qr.raceId,         qr.driverId,         qr.q3,         ROW_NUMBER() OVER (ORDER BY qr.q3 ASC) AS q3_rank     FROM qualifying_races qr ) SELECT      d.forename,     d.surname FROM ranked_qualifying rq JOIN drivers d ON rq.driverId = d.driverId WHERE rq.q3_rank = 3;
SELECT      d.forename || ' ' || d.surname AS full_name,     d.nationality,     r.name AS first_race_name FROM drivers d JOIN (     SELECT          driverId,         MIN(raceId) AS first_race_id     FROM results     GROUP BY driverId ) first_race ON d.driverId = first_race.driverId JOIN races r ON first_race.first_race_id = r.raceId WHERE d.dob = (     SELECT MAX(dob)     FROM drivers );
SELECT COUNT(*) AS accident_count FROM results r JOIN races ra ON r.raceId = ra.raceId WHERE ra.name = 'Canadian Grand Prix'   AND r.statusId = 3   AND r.driverId = (     SELECT r2.driverId     FROM results r2     JOIN races ra2 ON r2.raceId = ra2.raceId     WHERE ra2.name = 'Canadian Grand Prix'       AND r2.statusId = 3     GROUP BY r2.driverId     ORDER BY COUNT(*) DESC     LIMIT 1   );
SELECT     COUNT(ds.wins) AS total_wins,     d.forename,     d.surname FROM drivers d JOIN driverStandings ds   ON d.driverId = ds.driverId WHERE d.dob = (     SELECT MIN(dob)     FROM drivers     WHERE dob IS NOT NULL ) GROUP BY     d.forename,     d.surname;
SELECT MAX(duration) FROM pitStops;
SELECT MIN(milliseconds) AS fastest_time FROM lapTimes;
SELECT MAX(ps.duration) FROM pitStops ps JOIN drivers d ON ps.driverId = d.driverId WHERE d.forename = 'Lewis'   AND d.surname = 'Hamilton';
SELECT     ps.lap FROM pitStops AS ps JOIN drivers AS d     ON ps.driverId = d.driverId JOIN races AS r     ON ps.raceId = r.raceId WHERE     d.forename = 'Lewis'     AND d.surname = 'Hamilton'     AND r.year = 2011     AND r.name = 'Australian Grand Prix';
SELECT     p.duration FROM pitStops AS p JOIN races AS r     ON p.raceId = r.raceId WHERE     r.year = 2011     AND r.name = 'Australian Grand Prix';
SELECT     MIN(lt.time) FROM lapTimes AS lt JOIN drivers AS d     ON lt.driverId = d.driverId WHERE     d.forename = 'Lewis'     AND d.surname = 'Hamilton';
SELECT     d.forename,     d.surname FROM lapTimes AS lt JOIN drivers AS d     ON lt.driverId = d.driverId ORDER BY     lt.milliseconds ASC LIMIT 1;
SELECT     c.position FROM     circuits c JOIN     races r ON c.circuitId = r.circuitId JOIN     results res ON r.raceId = res.raceId JOIN     drivers d ON res.driverId = d.driverId WHERE     d.forename = 'Lewis'     AND d.surname = 'Hamilton'     AND res.fastestLapTime = (         SELECT MIN(res2.fastestLapTime)         FROM             results res2         JOIN             drivers d2 ON res2.driverId = d2.driverId         WHERE             d2.forename = 'Lewis'             AND d2.surname = 'Hamilton'     );
SELECT     lt.time FROM lapTimes AS lt JOIN races AS r     ON lt.raceId = r.raceId JOIN circuits AS c     ON r.circuitId = c.circuitId WHERE c.name = 'Austrian Grand Prix Circuit' ORDER BY lt.milliseconds ASC LIMIT 1;
SELECT     c.circuitId,     c.name,     c.location,     c.country,     lt.time AS lap_record FROM circuits c JOIN races r     ON c.circuitId = r.circuitId JOIN lapTimes lt     ON r.raceId = lt.raceId WHERE c.country = 'Italy' ORDER BY     c.circuitId,     lt.milliseconds ASC;
SELECT     r.name FROM lapTimes AS lt JOIN races AS r   ON lt.raceId = r.raceId JOIN circuits AS c   ON r.circuitId = c.circuitId WHERE c.name = 'Austrian Grand Prix Circuit' ORDER BY lt.milliseconds ASC LIMIT 1;
WITH lap_record AS (     SELECT         lt.raceId,         lt.driverId,         lt.time     FROM lapTimes lt     JOIN circuits c       ON lt.raceId = (           SELECT r.raceId           FROM races r           WHERE r.circuitId = c.circuitId             AND c.name = 'Austrian Grand Prix Circuit'       )     ORDER BY lt.milliseconds ASC     LIMIT 1 ) SELECT     ps.duration FROM pitStops ps JOIN lap_record lr   ON ps.raceId = lr.raceId  AND ps.driverId = lr.driverId;
SELECT     c.lat,     c.lng FROM circuits AS c JOIN races AS r     ON c.circuitId = r.circuitId JOIN lapTimes AS lt     ON r.raceId = lt.raceId WHERE lt.time = '1:29.488'   AND lt.milliseconds = (       SELECT MIN(lt2.milliseconds)       FROM lapTimes AS lt2       JOIN races AS r2           ON lt2.raceId = r2.raceId       WHERE r2.circuitId = c.circuitId   );
SELECT AVG(ps.milliseconds) FROM pitStops ps JOIN drivers d ON ps.driverId = d.driverId WHERE d.forename = 'Lewis' AND d.surname = 'Hamilton';
SELECT AVG(lt.milliseconds) FROM lapTimes lt JOIN races r ON lt.raceId = r.raceId JOIN circuits c ON r.circuitId = c.circuitId WHERE c.country = 'Italy';
SELECT player_api_id FROM Player_Attributes ORDER BY overall_rating DESC LIMIT 1;
SELECT p.height, p.player_name FROM Player p ORDER BY p.height DESC LIMIT 1;
SELECT preferred_foot FROM Player_Attributes ORDER BY potential ASC LIMIT 1;
SELECT COUNT(*) FROM Player_Attributes WHERE overall_rating >= 60   AND overall_rating < 65   AND defensive_work_rate = 'low';
SELECT     p.id FROM     Player p JOIN     Player_Attributes pa         ON p.player_api_id = pa.player_api_id GROUP BY     p.id,     p.player_api_id ORDER BY     MAX(pa.crossing) DESC LIMIT 5;
SELECT     l.name FROM Match AS m JOIN League AS l     ON m.league_id = l.id WHERE     m.season = '2015/2016' GROUP BY     l.id,     l.name ORDER BY     SUM(m.home_team_goal + m.away_team_goal) DESC LIMIT 1;
SELECT     T.team_long_name FROM Match AS M JOIN Team AS T     ON M.home_team_api_id = T.team_api_id WHERE     M.season = '2015/2016'     AND M.home_team_goal < M.away_team_goal GROUP BY     T.team_long_name ORDER BY     COUNT(*) ASC LIMIT 1;
SELECT     p.player_name FROM Player AS p JOIN Player_Attributes AS pa     ON p.player_api_id = pa.player_api_id ORDER BY     pa.penalties DESC LIMIT 10;
SELECT     T.team_long_name FROM Match AS M JOIN League AS L     ON M.league_id = L.id JOIN Team AS T     ON M.away_team_api_id = T.team_api_id WHERE     L.name = 'Scotland Premier League'     AND M.season = '2009/2010'     AND M.away_team_goal > M.home_team_goal GROUP BY     T.team_long_name ORDER BY     COUNT(*) DESC LIMIT 1;
SELECT     T1.buildUpPlaySpeed FROM Team_Attributes AS T1 ORDER BY     T1.buildUpPlaySpeed DESC LIMIT 4;
SELECT     l.name FROM Match AS m JOIN League AS l     ON m.league_id = l.id WHERE     m.season = '2015/2016' GROUP BY     l.id,     l.name ORDER BY     SUM(CASE WHEN m.home_team_goal = m.away_team_goal THEN 1 ELSE 0 END) DESC LIMIT 1;
SELECT     T1.player_name,     CAST((julianday('now') - julianday(T1.birthday)) / 365.25 AS INTEGER) AS age FROM     Player AS T1     INNER JOIN Player_Attributes AS T2         ON T1.player_api_id = T2.player_api_id WHERE     T2.sprint_speed >= 97     AND strftime('%Y', T2.date) >= '2013'     AND strftime('%Y', T2.date) <= '2015';
SELECT     L.name,     COUNT(M.id) AS match_count FROM League AS L JOIN Match AS M     ON L.id = M.league_id GROUP BY     L.id,     L.name ORDER BY     match_count DESC LIMIT 1;
SELECT CAST(SUM(height) AS REAL) / COUNT(id) AS average_height FROM Player WHERE birthday >= '1990-01-01 00:00:00'   AND birthday < '1996-01-01 00:00:00';
SELECT     player_api_id FROM     Player_Attributes WHERE     substr(date, 1, 4) = '2010'     AND overall_rating = (         SELECT             MAX(overall_rating)         FROM             Player_Attributes         WHERE             substr(date, 1, 4) = '2010'     );
SELECT DISTINCT team_fifa_api_id FROM Team_Attributes WHERE buildUpPlaySpeed > 50   AND buildUpPlaySpeed < 60;
WITH AvgPassing AS (     SELECT          AVG(buildUpPlayPassing) AS avg_passing     FROM Team_Attributes     WHERE strftime('%Y', date) = '2012'       AND buildUpPlayPassing IS NOT NULL ) SELECT DISTINCT T.team_long_name FROM Team_Attributes TA JOIN Team T ON TA.team_api_id = T.team_api_id CROSS JOIN AvgPassing AP WHERE strftime('%Y', TA.date) = '2012'   AND TA.buildUpPlayPassing IS NOT NULL   AND TA.buildUpPlayPassing > AP.avg_passing;
SELECT   CAST(SUM(CASE WHEN pa.preferred_foot = 'left' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(pa.player_fifa_api_id) AS percentage FROM Player_Attributes pa JOIN Player p   ON pa.player_api_id = p.player_api_id WHERE strftime('%Y', p.birthday) BETWEEN '1987' AND '1992';
SELECT     l.name FROM League AS l JOIN Match AS m     ON l.id = m.league_id GROUP BY     l.id,     l.name ORDER BY     SUM(m.home_team_goal + m.away_team_goal) ASC LIMIT 5;
SELECT CAST(SUM(pa.long_shots) AS REAL) / COUNT(pa.player_fifa_api_id) AS average_long_shots FROM Player_Attributes pa JOIN Player p ON pa.player_api_id = p.player_api_id WHERE p.player_name = 'Ahmed Samir Farag';
SELECT     p.player_name FROM     Player p JOIN     Player_Attributes pa     ON p.player_fifa_api_id = pa.player_fifa_api_id WHERE     p.height > 180 GROUP BY     p.player_name ORDER BY     SUM(pa.heading_accuracy) * 1.0 / COUNT(pa.player_fifa_api_id) DESC LIMIT 10;
WITH cte AS (     SELECT         t.team_long_name,         ta.chanceCreationPassing     FROM Team_Attributes ta     JOIN Team t ON ta.team_api_id = t.team_api_id     WHERE ta.buildUpPlayDribblingClass = 'Normal'       AND ta.date >= '2014-01-01 00:00:00'       AND ta.date <= '2014-01-31 00:00:00' ), avg_cte AS (     SELECT         AVG(chanceCreationPassing) AS avg_passing     FROM cte ) SELECT     c.team_long_name FROM cte c CROSS JOIN avg_cte a WHERE c.chanceCreationPassing < a.avg_passing ORDER BY c.chanceCreationPassing DESC;
SELECT     L.name FROM League AS L JOIN Match AS M     ON L.id = M.league_id WHERE     M.season = '2009/2010' GROUP BY     L.id,     L.name HAVING     AVG(M.home_team_goal) > AVG(M.away_team_goal);
SELECT team_short_name FROM Team WHERE team_long_name = 'Queens Park Rangers';
SELECT     player_name FROM     Player WHERE     substr(birthday, 1, 7) = '1970-10';
SELECT pa.attacking_work_rate FROM Player_Attributes pa JOIN Player p ON pa.player_api_id = p.player_api_id WHERE p.player_name = 'Franco Zennaro';
SELECT     T1.buildUpPlayPositioningClass FROM Team_Attributes AS T1 INNER JOIN Team AS T2     ON T1.team_api_id = T2.team_api_id WHERE     T2.team_long_name = 'ADO Den Haag';
SELECT     pa.heading_accuracy FROM Player_Attributes AS pa JOIN Player AS p     ON pa.player_api_id = p.player_api_id WHERE     p.player_name = 'Francois Affolter'     AND pa.date = '2014-09-18 00:00:00';
SELECT     pa.overall_rating FROM Player_Attributes AS pa JOIN Player AS p     ON pa.player_api_id = p.player_api_id WHERE     p.player_name = 'Gabriel Tamas'     AND strftime('%Y', pa.date) = '2011';
SELECT COUNT(*) AS match_count FROM Match m JOIN League l ON m.league_id = l.id WHERE m.season = '2015/2016'   AND l.name = 'Scotland Premier League';
SELECT     pa.preferred_foot FROM Player AS p JOIN Player_Attributes AS pa     ON p.player_api_id = pa.player_api_id ORDER BY p.birthday DESC LIMIT 1;
SELECT p.player_name FROM Player p JOIN Player_Attributes pa ON p.player_api_id = pa.player_api_id WHERE pa.potential = (SELECT MAX(potential) FROM Player_Attributes);
SELECT COUNT(*) FROM Player p JOIN Player_Attributes pa ON p.player_api_id = pa.player_api_id WHERE p.weight < 130   AND pa.preferred_foot = 'left';
SELECT DISTINCT T.team_short_name FROM Team T JOIN Team_Attributes TA ON T.team_api_id = TA.team_api_id WHERE TA.chanceCreationPassingClass = 'Risky';
SELECT pa.defensive_work_rate FROM Player_Attributes pa JOIN Player p ON pa.player_api_id = p.player_api_id WHERE p.player_name = 'David Wilson';
SELECT p.birthday FROM Player p JOIN Player_Attributes pa ON p.player_api_id = pa.player_api_id ORDER BY pa.overall_rating DESC LIMIT 1;
SELECT l.name FROM League l JOIN Country c ON l.country_id = c.id WHERE c.name = 'Netherlands';
SELECT AVG(m.home_team_goal) AS average_home_team_goal FROM Match m JOIN Country c ON m.country_id = c.id WHERE c.name = 'Poland'   AND m.season = '2010/2011';
WITH HeightRange AS (     SELECT          MIN(height) AS min_height,         MAX(height) AS max_height     FROM Player ), PlayersInRange AS (     SELECT          p.player_name,         pa.finishing     FROM Player p     JOIN Player_Attributes pa ON p.player_api_id = pa.player_api_id     CROSS JOIN HeightRange hr     WHERE p.height BETWEEN hr.min_height AND hr.max_height ) SELECT      player_name FROM PlayersInRange GROUP BY player_name ORDER BY AVG(finishing) DESC LIMIT 1;
SELECT player_name FROM Player WHERE height > 180;
SELECT COUNT(*) AS player_count FROM Player WHERE strftime('%Y', birthday) > '1990';
SELECT COUNT(*) FROM Player WHERE player_name LIKE 'Adam%'   AND weight > 170;
SELECT     p.player_name FROM Player_Attributes AS pa JOIN Player AS p     ON pa.player_api_id = p.player_api_id WHERE     pa.overall_rating > 80     AND strftime('%Y', pa.date) BETWEEN '2008' AND '2010';
SELECT pa.potential FROM Player_Attributes pa JOIN Player p ON pa.player_api_id = p.player_api_id WHERE p.player_name = 'Aaron Doran';
SELECT player_name FROM Player JOIN Player_Attributes ON Player.player_api_id = Player_Attributes.player_api_id WHERE Player_Attributes.preferred_foot = 'left';
SELECT T.team_long_name FROM Team T JOIN Team_Attributes TA ON T.team_api_id = TA.team_api_id WHERE TA.buildUpPlaySpeedClass = 'Fast';
SELECT     ta.buildUpPlayPassingClass FROM Team_Attributes AS ta JOIN Team AS t     ON ta.team_api_id = t.team_api_id WHERE     t.team_short_name = 'CLB';
SELECT     T.team_short_name FROM Team AS T JOIN Team_Attributes AS TA     ON T.team_api_id = TA.team_api_id WHERE     TA.buildUpPlayPassing > 70;
SELECT      SUM(pa.overall_rating) * 1.0 / COUNT(pa.id) AS average_overall_rating FROM Player_Attributes pa JOIN Player p ON pa.player_api_id = p.player_api_id WHERE strftime('%Y', pa.date) >= '2010'    AND strftime('%Y', pa.date) <= '2015'   AND p.height > 170;
SELECT player_name FROM Player ORDER BY height ASC LIMIT 1;
SELECT c.name FROM League l JOIN Country c ON l.country_id = c.id WHERE l.name = 'Italy Serie A';
SELECT     t.team_short_name FROM Team_Attributes AS ta JOIN Team AS t     ON ta.team_api_id = t.team_api_id WHERE     ta.buildUpPlaySpeed = 31     AND ta.buildUpPlayDribbling = 53     AND ta.buildUpPlayPassing = 32;
SELECT AVG(pa.overall_rating) AS average_overall_rating FROM Player_Attributes pa JOIN Player p ON pa.player_api_id = p.player_api_id WHERE p.player_name = 'Aaron Doran';
SELECT COUNT(*) FROM Match AS m JOIN League AS l   ON m.league_id = l.id WHERE l.name = 'Germany 1. Bundesliga'   AND strftime('%Y-%m', m.date) BETWEEN '2008-08' AND '2008-10';
SELECT T.team_short_name FROM Team AS T JOIN Match AS M ON T.team_api_id = M.home_team_api_id WHERE M.home_team_goal = 10;
SELECT p.player_name FROM Player p JOIN Player_Attributes pa ON p.player_api_id = pa.player_api_id WHERE pa.potential = 61   AND pa.balance = (     SELECT MAX(balance)     FROM Player_Attributes     WHERE potential = 61   );
SELECT AVG(CASE WHEN p.player_name = 'Abdou Diallo' THEN pa.ball_control END) - AVG(CASE WHEN p.player_name = 'Aaron Appindangoye' THEN pa.ball_control END) AS difference FROM Player_Attributes pa JOIN Player p ON pa.player_api_id = p.player_api_id WHERE p.player_name IN ('Abdou Diallo', 'Aaron Appindangoye');
SELECT team_long_name FROM Team WHERE team_short_name = 'GEN';
SELECT player_name FROM Player WHERE player_name IN ('Aaron Lennon', 'Abdelaziz Barrada') ORDER BY birthday DESC LIMIT 1;
SELECT player_name FROM Player ORDER BY height DESC LIMIT 1;
SELECT COUNT(*) FROM Player_Attributes WHERE preferred_foot = 'left'   AND attacking_work_rate = 'low';
SELECT c.name FROM League l JOIN Country c ON l.country_id = c.id WHERE l.name = 'Belgium Jupiler League';
SELECT L.name FROM League AS L JOIN Country AS C ON L.country_id = C.id WHERE C.name = 'Germany';
SELECT p.player_name FROM Player p JOIN Player_Attributes pa ON p.player_api_id = pa.player_api_id ORDER BY pa.overall_rating DESC LIMIT 1;
SELECT COUNT(DISTINCT pa.player_api_id) AS count FROM Player_Attributes pa JOIN Player p ON pa.player_api_id = p.player_api_id WHERE strftime('%Y', p.birthday) < '1986'   AND pa.defensive_work_rate = 'high';
SELECT p.player_name FROM Player p JOIN Player_Attributes pa ON p.player_api_id = pa.player_api_id WHERE p.player_name IN ('Alexis', 'Ariel Borysiuk', 'Arouna Kone') GROUP BY p.player_name ORDER BY MAX(pa.crossing) DESC LIMIT 1;
SELECT pa.heading_accuracy FROM Player_Attributes pa JOIN Player p ON pa.player_api_id = p.player_api_id WHERE p.player_name = 'Ariel Borysiuk';
SELECT COUNT(*) FROM Player p JOIN Player_Attributes pa ON p.player_api_id = pa.player_api_id WHERE p.height > 180   AND pa.volleys > 70;
SELECT     p.player_name FROM Player AS p JOIN Player_Attributes AS pa     ON p.player_api_id = pa.player_api_id WHERE     pa.volleys > 70     AND pa.dribbling > 70;
SELECT COUNT(*) FROM Match m JOIN Country c ON m.country_id = c.id WHERE c.name = 'Belgium'   AND m.season = '2008/2009';
SELECT pa.long_passing FROM Player p JOIN Player_Attributes pa ON p.player_api_id = pa.player_api_id ORDER BY p.birthday ASC LIMIT 1;
SELECT COUNT(*) AS match_count FROM Match AS m JOIN League AS l   ON m.league_id = l.id WHERE l.name = 'Belgium Jupiler League'   AND SUBSTR(m.date, 1, 7) = '2009-04';
SELECT L.name FROM League L JOIN Match M ON L.id = M.league_id WHERE M.season = '2008/2009' GROUP BY L.id, L.name ORDER BY COUNT(M.id) DESC LIMIT 1;
SELECT   CAST(SUM(T1.overall_rating) AS REAL) / COUNT(T1.id) AS average_overall_rating FROM Player_Attributes AS T1 JOIN Player AS T2   ON T1.player_api_id = T2.player_api_id WHERE   strftime('%Y', T2.birthday) < '1986';
SELECT   CAST((     (       SELECT pa.overall_rating       FROM Player_Attributes pa       JOIN Player p ON pa.player_api_id = p.player_api_id       WHERE p.player_name = 'Ariel Borysiuk'     ) - (       SELECT pa.overall_rating       FROM Player_Attributes pa       JOIN Player p ON pa.player_api_id = p.player_api_id       WHERE p.player_name = 'Paulin Puel'     )   ) AS REAL) * 100 / (     SELECT pa.overall_rating     FROM Player_Attributes pa     JOIN Player p ON pa.player_api_id = p.player_api_id     WHERE p.player_name = 'Paulin Puel'   ) AS percentage_difference;
SELECT AVG(T1.buildUpPlaySpeed) AS average_build_up_play_speed FROM Team_Attributes AS T1 INNER JOIN Team AS T2   ON T1.team_api_id = T2.team_api_id WHERE T2.team_long_name = 'Heart of Midlothian';
SELECT AVG(pa.overall_rating) AS average_overall_rating FROM Player_Attributes pa JOIN Player p ON pa.player_api_id = p.player_api_id WHERE p.player_name = 'Pietro Marino';
SELECT SUM(T1.crossing) AS total_crossing_score FROM Player_Attributes AS T1 INNER JOIN Player AS T2   ON T1.player_api_id = T2.player_api_id WHERE T2.player_name = 'Aaron Lennox';
SELECT     MAX(T1.chanceCreationPassing) AS max_chance_creation_passing,     T1.chanceCreationPassingClass AS chance_creation_passing_class FROM Team_Attributes AS T1 INNER JOIN Team AS T2     ON T1.team_api_id = T2.team_api_id WHERE     T2.team_long_name = 'Ajax';
SELECT pa.preferred_foot FROM Player_Attributes pa JOIN Player p ON pa.player_api_id = p.player_api_id WHERE p.player_name = 'Abdou Diallo';
SELECT MAX(pa.overall_rating) FROM Player_Attributes pa JOIN Player p ON pa.player_api_id = p.player_api_id WHERE p.player_name = 'Dorlan Pabon';
SELECT AVG(M.away_team_goal) AS average_goals FROM Match M JOIN Team T ON M.away_team_api_id = T.team_api_id JOIN Country C ON M.country_id = C.id WHERE T.team_long_name = 'Parma'   AND C.name = 'Italy';
SELECT p.player_name FROM Player_Attributes pa JOIN Player p ON pa.player_api_id = p.player_api_id WHERE pa.overall_rating = 77   AND pa.date LIKE '2016-06-23%' ORDER BY p.birthday ASC LIMIT 1;
SELECT pa.overall_rating FROM Player_Attributes pa JOIN Player p ON pa.player_api_id = p.player_api_id WHERE p.player_name = 'Aaron Mooy'   AND pa.date LIKE '2016-02-04%';
SELECT pa.potential FROM Player_Attributes pa JOIN Player p ON pa.player_api_id = p.player_api_id WHERE p.player_name = 'Francesco Parravicini'   AND pa.date = '2010-08-30 00:00:00';
SELECT     pa.attacking_work_rate FROM Player_Attributes AS pa JOIN Player AS p     ON pa.player_api_id = p.player_api_id WHERE     p.player_name = 'Francesco Migliore'     AND pa.date LIKE '2015-05-01%';
SELECT     pa.defensive_work_rate FROM Player_Attributes AS pa JOIN Player AS p     ON pa.player_api_id = p.player_api_id WHERE     p.player_name = 'Kevin Berigaud'     AND pa.date = '2013-02-22 00:00:00';
SELECT pa.date FROM Player_Attributes pa JOIN Player p ON pa.player_api_id = p.player_api_id WHERE p.player_name = 'Kevin Constant' ORDER BY pa.crossing DESC, pa.date ASC LIMIT 1;
SELECT     ta.buildUpPlaySpeedClass FROM Team_Attributes AS ta JOIN Team AS t     ON ta.team_api_id = t.team_api_id WHERE     t.team_long_name = 'Willem II'     AND ta.date = '2012-02-22';
SELECT     ta.buildUpPlayDribblingClass FROM Team_Attributes AS ta JOIN Team AS t     ON ta.team_api_id = t.team_api_id WHERE     t.team_short_name = 'LEI'     AND ta.date = '2015-09-10 00:00:00';
SELECT     ta.buildUpPlayPassingClass FROM Team_Attributes AS ta JOIN Team AS t     ON ta.team_api_id = t.team_api_id WHERE     t.team_long_name = 'FC Lorient'     AND ta.date LIKE '2010-02-22%';
SELECT     ta.chanceCreationPassingClass FROM Team_Attributes AS ta JOIN Team AS t     ON ta.team_api_id = t.team_api_id WHERE     t.team_long_name = 'PEC Zwolle'     AND ta.date = '2013-09-20 00:00:00';
SELECT     ta.chanceCreationCrossingClass FROM Team_Attributes AS ta JOIN Team AS t     ON ta.team_api_id = t.team_api_id WHERE     t.team_long_name = 'Hull City'     AND ta.date = '2010-02-22 00:00:00';
SELECT     ta.defenceAggressionClass FROM Team_Attributes AS ta JOIN Team AS t     ON ta.team_api_id = t.team_api_id WHERE     t.team_long_name = 'Hannover 96'     AND ta.date LIKE '2015-09-10%';
SELECT AVG(pa.overall_rating) AS average_overall_rating FROM Player_Attributes pa JOIN Player p ON pa.player_api_id = p.player_api_id WHERE p.player_name = 'Marko Arnautovic'   AND substr(pa.date, 1, 10) BETWEEN '2007-02-22' AND '2016-04-21';
SELECT   CAST(     (       SELECT pa.overall_rating       FROM Player_Attributes pa       JOIN Player p ON pa.player_api_id = p.player_api_id       WHERE p.player_name = 'Landon Donovan'         AND pa.date = '2013-07-12'     ) - (       SELECT pa.overall_rating       FROM Player_Attributes pa       JOIN Player p ON pa.player_api_id = p.player_api_id       WHERE p.player_name = 'Jordan Bowery'         AND pa.date = '2013-07-12'     ) AS REAL   ) * 100 / (     SELECT pa.overall_rating     FROM Player_Attributes pa     JOIN Player p ON pa.player_api_id = p.player_api_id     WHERE p.player_name = 'Landon Donovan'       AND pa.date = '2013-07-12'   ) AS percentage
SELECT player_name FROM Player ORDER BY height DESC LIMIT 1;
SELECT player_api_id FROM Player ORDER BY weight DESC LIMIT 10;
SELECT     p.player_name FROM Player AS p WHERE     datetime(CURRENT_TIMESTAMP, 'localtime') - datetime(p.birthday) > 34;
SELECT SUM(M.home_team_goal) FROM Match AS M JOIN Player AS P   ON M.home_player_1 = P.player_api_id  OR M.home_player_2 = P.player_api_id  OR M.home_player_3 = P.player_api_id  OR M.home_player_4 = P.player_api_id  OR M.home_player_5 = P.player_api_id  OR M.home_player_6 = P.player_api_id  OR M.home_player_7 = P.player_api_id  OR M.home_player_8 = P.player_api_id  OR M.home_player_9 = P.player_api_id  OR M.home_player_10 = P.player_api_id  OR M.home_player_11 = P.player_api_id WHERE P.player_name = 'Aaron Lennon';
SELECT   SUM(CASE         WHEN m.away_team_goal IS NOT NULL THEN m.away_team_goal         ELSE 0       END) AS total_away_goals FROM Match m WHERE   m.away_player_1 IN (     SELECT p.player_api_id     FROM Player p     WHERE p.player_name IN ('Daan Smith', 'Filipe Ferreira')   )   OR m.away_player_2 IN (     SELECT p.player_api_id     FROM Player p     WHERE p.player_name IN ('Daan Smith', 'Filipe Ferreira')   )   OR m.away_player_3 IN (     SELECT p.player_api_id     FROM Player p     WHERE p.player_name IN ('Daan Smith', 'Filipe Ferreira')   )   OR m.away_player_4 IN (     SELECT p.player_api_id     FROM Player p     WHERE p.player_name IN ('Daan Smith', 'Filipe Ferreira')   )   OR m.away_player_5 IN (     SELECT p.player_api_id     FROM Player p     WHERE p.player_name IN ('Daan Smith', 'Filipe Ferreira')   )   OR m.away_player_6 IN (     SELECT p.player_api_id     FROM Player p     WHERE p.player_name IN ('Daan Smith', 'Filipe Ferreira')   )   OR m.away_player_7 IN (     SELECT p.player_api_id     FROM Player p     WHERE p.player_name IN ('Daan Smith', 'Filipe Ferreira')   )   OR m.away_player_8 IN (     SELECT p.player_api_id     FROM Player p     WHERE p.player_name IN ('Daan Smith', 'Filipe Ferreira')   )   OR m.away_player_9 IN (     SELECT p.player_api_id     FROM Player p     WHERE p.player_name IN ('Daan Smith', 'Filipe Ferreira')   )   OR m.away_player_10 IN (     SELECT p.player_api_id     FROM Player p     WHERE p.player_name IN ('Daan Smith', 'Filipe Ferreira')   )   OR m.away_player_11 IN (     SELECT p.player_api_id     FROM Player p     WHERE p.player_name IN ('Daan Smith', 'Filipe Ferreira')   );
SELECT SUM(m.home_team_goal) AS total_home_goals FROM Match m JOIN Player p   ON m.home_player_1 = p.player_api_id  OR m.home_player_2 = p.player_api_id  OR m.home_player_3 = p.player_api_id  OR m.home_player_4 = p.player_api_id  OR m.home_player_5 = p.player_api_id  OR m.home_player_6 = p.player_api_id  OR m.home_player_7 = p.player_api_id  OR m.home_player_8 = p.player_api_id  OR m.home_player_9 = p.player_api_id  OR m.home_player_10 = p.player_api_id  OR m.home_player_11 = p.player_api_id WHERE julianday('now') - julianday(p.birthday) <= 31 * 365.25;
SELECT p.player_name FROM Player p JOIN Player_Attributes pa ON p.player_api_id = pa.player_api_id WHERE pa.overall_rating = (SELECT MAX(overall_rating) FROM Player_Attributes);
SELECT p.player_name FROM Player p JOIN Player_Attributes pa ON p.player_api_id = pa.player_api_id WHERE pa.potential = (SELECT MAX(potential) FROM Player_Attributes);
SELECT DISTINCT p.player_name FROM Player p JOIN Player_Attributes pa ON p.player_api_id = pa.player_api_id WHERE pa.attacking_work_rate = 'high';
SELECT     p.player_name FROM Player AS p JOIN Player_Attributes AS pa     ON p.player_api_id = pa.player_api_id WHERE     pa.finishing = 1 ORDER BY     p.birthday ASC LIMIT 1;
SELECT DISTINCT p.player_name FROM Player p JOIN Match m ON p.player_api_id IN (     m.home_player_1, m.home_player_2, m.home_player_3, m.home_player_4, m.home_player_5,     m.home_player_6, m.home_player_7, m.home_player_8, m.home_player_9, m.home_player_10, m.home_player_11,     m.away_player_1, m.away_player_2, m.away_player_3, m.away_player_4, m.away_player_5,     m.away_player_6, m.away_player_7, m.away_player_8, m.away_player_9, m.away_player_10, m.away_player_11 ) JOIN Country c ON m.country_id = c.id WHERE c.name = 'Belgium';
SELECT DISTINCT     c.name AS country FROM Player_Attributes pa JOIN Player p     ON pa.player_api_id = p.player_api_id JOIN Match m     ON p.player_api_id IN (         m.home_player_1, m.home_player_2, m.home_player_3, m.home_player_4, m.home_player_5,         m.home_player_6, m.home_player_7, m.home_player_8, m.home_player_9, m.home_player_10, m.home_player_11,         m.away_player_1, m.away_player_2, m.away_player_3, m.away_player_4, m.away_player_5,         m.away_player_6, m.away_player_7, m.away_player_8, m.away_player_9, m.away_player_10, m.away_player_11     ) JOIN Country c     ON m.country_id = c.id WHERE pa.vision > 89;
SELECT      c.name AS country_name,     AVG(p.weight) AS average_weight FROM      Player p JOIN      Match m ON p.player_api_id IN (         m.home_player_1, m.home_player_2, m.home_player_3, m.home_player_4, m.home_player_5,         m.home_player_6, m.home_player_7, m.home_player_8, m.home_player_9, m.home_player_10, m.home_player_11,         m.away_player_1, m.away_player_2, m.away_player_3, m.away_player_4, m.away_player_5,         m.away_player_6, m.away_player_7, m.away_player_8, m.away_player_9, m.away_player_10, m.away_player_11     ) JOIN      Country c ON m.country_id = c.id GROUP BY      c.name ORDER BY      average_weight DESC LIMIT 1;
SELECT T.team_long_name FROM Team T JOIN Team_Attributes TA ON T.team_api_id = TA.team_api_id WHERE TA.buildUpPlaySpeedClass = 'Slow';
SELECT DISTINCT T.team_short_name FROM Team T JOIN Team_Attributes TA ON T.team_api_id = TA.team_api_id WHERE TA.chanceCreationPassingClass = 'Safe';
SELECT AVG(p.height) FROM Player p JOIN Match m   ON p.player_api_id IN (        m.home_player_1, m.home_player_2, m.home_player_3, m.home_player_4, m.home_player_5,        m.home_player_6, m.home_player_7, m.home_player_8, m.home_player_9, m.home_player_10, m.home_player_11,        m.away_player_1, m.away_player_2, m.away_player_3, m.away_player_4, m.away_player_5,        m.away_player_6, m.away_player_7, m.away_player_8, m.away_player_9, m.away_player_10, m.away_player_11      ) JOIN Country c   ON m.country_id = c.id WHERE c.name = 'Italy';
SELECT player_name FROM Player WHERE height > 180 ORDER BY player_name ASC LIMIT 3;
SELECT COUNT(*) FROM Player WHERE player_name LIKE 'Aaron%' AND birthday > '1990';
SELECT      (SELECT jumping FROM Player_Attributes WHERE id = 6) -      (SELECT jumping FROM Player_Attributes WHERE id = 23) AS difference
SELECT     p.id FROM Player AS p JOIN Player_Attributes AS pa     ON p.player_api_id = pa.player_api_id WHERE     pa.preferred_foot = 'right' ORDER BY     pa.potential ASC LIMIT 5;
SELECT COUNT(*) FROM Player_Attributes WHERE preferred_foot = 'left'   AND crossing = (     SELECT MAX(crossing)     FROM Player_Attributes     WHERE preferred_foot = 'left'   );
SELECT   CAST(SUM(CASE WHEN stamina > 80 AND strength > 80 THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(*) FROM Player_Attributes;
SELECT c.name FROM League l JOIN Country c ON l.country_id = c.id WHERE l.name = 'Poland Ekstraklasa';
SELECT     m.home_team_goal,     m.away_team_goal FROM Match AS m JOIN League AS l     ON m.league_id = l.id WHERE     m.date LIKE '2008-09-24%'     AND l.name = 'Belgium Jupiler League';
SELECT     pa.sprint_speed,     pa.agility,     pa.acceleration FROM Player_Attributes pa JOIN Player p     ON pa.player_api_id = p.player_api_id WHERE p.player_name = 'Alexis Blin';
SELECT DISTINCT T1.buildUpPlaySpeedClass FROM Team_Attributes AS T1 INNER JOIN Team AS T2 ON T1.team_api_id = T2.team_api_id WHERE T2.team_long_name = 'KSV Cercle Brugge';
SELECT COUNT(*) AS games_played FROM Match WHERE season = '2015/2016'   AND league_id = (     SELECT id     FROM League     WHERE name = 'Italy Serie A'   );
SELECT MAX(m.home_team_goal) AS highest_home_score FROM Match m JOIN League l ON m.league_id = l.id WHERE l.name = 'Netherlands Eredivisie';
SELECT     pa.finishing,     pa.curve FROM Player_Attributes pa JOIN Player p     ON pa.player_api_id = p.player_api_id WHERE p.weight = (     SELECT MAX(weight)     FROM Player );
SELECT     L.name FROM     Match AS M JOIN     League AS L     ON M.league_id = L.id WHERE     M.season = '2015/2016' GROUP BY     L.name ORDER BY     COUNT(M.id) DESC LIMIT 4;
SELECT T.team_long_name FROM Team T JOIN Match M ON T.team_api_id = M.away_team_api_id ORDER BY M.away_team_goal DESC LIMIT 1;
SELECT p.player_name FROM Player p JOIN Player_Attributes pa ON p.player_api_id = pa.player_api_id ORDER BY pa.overall_rating DESC LIMIT 1;
SELECT   CAST(COUNT(CASE WHEN T1.height < 180 AND T2.overall_rating > 70 THEN 1 END) AS REAL) * 100 / COUNT(T1.id) FROM Player AS T1 JOIN Player_Attributes AS T2   ON T1.player_api_id = T2.player_api_id;
WITH male_admissions AS (     SELECT          SUM(CASE WHEN Admission = '+' THEN 1 ELSE 0 END) AS in_patient_count,         SUM(CASE WHEN Admission = '-' THEN 1 ELSE 0 END) AS out_patient_count     FROM Patient     WHERE SEX = 'M' ) SELECT      CASE          WHEN in_patient_count > out_patient_count THEN 'in-patient'         WHEN out_patient_count > in_patient_count THEN 'outpatient'         ELSE 'equal'     END AS category,     ABS(in_patient_count - out_patient_count) * 100.0 / NULLIF(out_patient_count, 0) AS deviation_percentage FROM male_admissions;
SELECT   CAST(SUM(CASE WHEN strftime('%Y', Birthday) > '1930' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(ID) FROM Patient WHERE SEX = 'F';
SELECT      CAST(SUM(CASE WHEN Admission = '+' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(*) AS percentage FROM Patient WHERE Birthday BETWEEN '1930-01-01' AND '1940-12-31';
SELECT      CAST(COUNT(CASE WHEN Diagnosis = 'SLE' AND Admission = '+' THEN ID END) AS REAL) * 1.0 /      COUNT(CASE WHEN Diagnosis = 'SLE' AND Admission = '-' THEN ID END) AS ratio FROM      Patient;
SELECT     p.Diagnosis,     l.Date FROM Patient AS p JOIN Laboratory AS l   ON p.ID = l.ID WHERE p.ID = 30609;
SELECT     p.SEX,     p.Birthday,     e.`Examination Date`,     e.Symptoms FROM Patient AS p JOIN Examination AS e   ON p.ID = e.ID WHERE p.ID = 163109;
SELECT     p.ID,     p.SEX,     p.Birthday FROM Patient AS p JOIN Laboratory AS l     ON p.ID = l.ID WHERE l.LDH > 500;
SELECT   p.ID,   CAST(strftime('%Y', 'now') AS INTEGER) - CAST(strftime('%Y', p.Birthday) AS INTEGER) AS age FROM Patient AS p JOIN Examination AS e   ON p.ID = e.ID WHERE e.RVVT = '+';
SELECT     p.ID,     p.SEX,     p.Diagnosis FROM Patient AS p JOIN Examination AS e     ON p.ID = e.ID WHERE e.Thrombosis = 2;
SELECT   p.ID FROM Patient AS p JOIN Laboratory AS l   ON p.ID = l.ID WHERE   strftime('%Y', p.Birthday) = '1937'   AND l.`T-CHO` >= 250;
SELECT     p.ID,     p.SEX,     p.Diagnosis FROM Patient AS p JOIN Laboratory AS l     ON p.ID = l.ID WHERE l.ALB < 3.5;
SELECT   CAST(SUM(CASE WHEN T1.SEX = 'F' AND (T2.TP < 6.0 OR T2.TP > 8.5) THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(T1.ID) FROM Patient AS T1 JOIN Laboratory AS T2   ON T1.ID = T2.ID;
SELECT AVG(e.`aCL IgG`) FROM Examination e JOIN Patient p ON e.ID = p.ID WHERE p.Admission = '+'   AND (strftime('%Y', 'now') - strftime('%Y', p.Birthday)) >= 50;
SELECT COUNT(*) FROM Patient WHERE SEX = 'F' AND STRFTIME('%Y', Description) = '1997' AND Admission = '-';
SELECT MIN(SUBSTR(`First Date`, 1, 4) - SUBSTR(Birthday, 1, 4)) AS age FROM Patient WHERE `First Date` IS NOT NULL   AND Birthday IS NOT NULL;
SELECT COUNT(*) AS count FROM Examination AS E JOIN Patient AS P   ON E.ID = P.ID WHERE E.Thrombosis = 1   AND strftime('%Y', E.`Examination Date`) = '1997'   AND P.SEX = 'F';
SELECT MAX(CAST(STRFTIME('%Y', P.Birthday) AS INTEGER)) - MIN(CAST(STRFTIME('%Y', P.Birthday) AS INTEGER)) AS age_gap FROM Patient P JOIN Laboratory L ON P.ID = L.ID WHERE L.TG >= 200;
SELECT     e.Symptoms,     p.Diagnosis FROM Examination e JOIN Patient p     ON e.ID = p.ID WHERE e.Symptoms IS NOT NULL ORDER BY p.Birthday DESC LIMIT 1;
SELECT   CAST(COUNT(DISTINCT l.ID) AS REAL) / 12 AS avg_male_patients_per_month FROM Laboratory l JOIN Patient p   ON l.ID = p.ID WHERE p.SEX = 'M'   AND l.Date BETWEEN '1998-01-01' AND '1998-12-31';
WITH OldestSJS AS (     SELECT          p.ID,         p.Birthday,         p.`First Date`,         l.`Date` AS LabDate     FROM Patient p     JOIN Laboratory l ON p.ID = l.ID     WHERE p.Diagnosis = 'SJS'     ORDER BY p.Birthday ASC     LIMIT 1 ) SELECT      LabDate,     (strftime('%Y', `First Date`) - strftime('%Y', Birthday)) AS Age FROM OldestSJS;
SELECT      CAST(SUM(CASE WHEN p.SEX = 'M' AND l.UA <= 8.0 THEN 1 ELSE 0 END) AS REAL) * 1.0 /      NULLIF(SUM(CASE WHEN p.SEX = 'F' AND l.UA <= 6.5 THEN 1 ELSE 0 END), 0) AS ratio FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE (p.SEX = 'M' AND l.UA <= 8.0) OR (p.SEX = 'F' AND l.UA <= 6.5);
SELECT COUNT(DISTINCT p.ID) AS patient_count FROM Patient p LEFT JOIN Examination e   ON p.ID = e.ID  AND (strftime('%Y', e.`Examination Date`) - strftime('%Y', p.`First Date`)) >= 1 WHERE p.`First Date` IS NOT NULL   AND e.ID IS NULL;
SELECT COUNT(*) FROM Examination AS e JOIN Patient AS p ON e.ID = p.ID WHERE strftime('%Y', e.`Examination Date`) BETWEEN '1990' AND '1993'   AND (CAST(strftime('%Y', e.`Examination Date`) AS INTEGER) - CAST(strftime('%Y', p.Birthday) AS INTEGER)) < 18;
SELECT COUNT(*) AS count FROM Patient AS p JOIN Laboratory AS l   ON p.ID = l.ID WHERE p.SEX = 'M'   AND l.`T-BIL` >= 2.0;
SELECT     T1.Diagnosis FROM Examination AS T1 WHERE     T1.`Examination Date` BETWEEN '1985-01-01' AND '1995-12-31' GROUP BY     T1.Diagnosis ORDER BY     COUNT(T1.Diagnosis) DESC LIMIT 1;
SELECT AVG(1999 - CAST(strftime('%Y', T1.Birthday) AS INTEGER)) AS average_age FROM Patient AS T1 JOIN Laboratory AS T2   ON T1.ID = T2.ID WHERE T2.Date BETWEEN '1991-10-01' AND '1991-10-30';
SELECT      (strftime('%Y', e.`Examination Date`) - strftime('%Y', p.`Birthday`)) AS age,     p.`Diagnosis` AS doctor_diagnosis FROM      Examination e JOIN      Patient p ON e.ID = p.ID JOIN      Laboratory l ON e.ID = l.ID AND e.`Examination Date` = l.`Date` ORDER BY      l.HGB DESC LIMIT 1;
SELECT `ANA` FROM `Examination` WHERE `ID` = 3605340 AND `Examination Date` = '1996-12-02';
SELECT      CASE          WHEN T1.`T-CHO` < 250 THEN 'Yes'          ELSE 'No'      END AS `Is Normal` FROM      `Laboratory` T1 WHERE      T1.`ID` = 2927464      AND T1.`Date` = '1995-09-04';
SELECT   p.SEX FROM Patient AS p WHERE p.Diagnosis = 'AORTITIS' ORDER BY p.ID LIMIT 1;
SELECT     e.`aCL IgM` FROM     Examination AS e JOIN     Patient AS p     ON e.ID = p.ID WHERE     p.`Diagnosis` = 'SLE'     AND p.`Description` = '1994-02-19'     AND e.`Examination Date` = '1993-11-12';
SELECT   CASE     WHEN p.SEX = 'M' THEN 'man'     WHEN p.SEX = 'F' THEN 'women'   END AS gender FROM Patient AS p JOIN Laboratory AS l   ON p.ID = l.ID WHERE   l.Date = '1992-06-12'   AND l.GPT = 9;
SELECT   CAST(strftime('%Y', T1.Date) AS INTEGER) - CAST(strftime('%Y', T2.Birthday) AS INTEGER) FROM Laboratory AS T1 JOIN Patient AS T2   ON T1.ID = T2.ID WHERE   T1.UA = 8.4   AND T1.Date = '1991-10-21';
SELECT COUNT(l.ID) AS total_laboratory_tests FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE p.`First Date` = '1991-06-13'   AND p.Diagnosis = 'SJS'   AND l.Date LIKE '1995-%';
SELECT p.Diagnosis FROM Patient p JOIN Examination e ON p.ID = e.ID WHERE e.Diagnosis = 'SLE'   AND e.`Examination Date` = '1997-01-27';
SELECT e.Symptoms FROM Examination e JOIN Patient p ON e.ID = p.ID WHERE p.Birthday = '1959-03-01'   AND e.`Examination Date` = '1993-09-27';
SELECT   SUM(CASE WHEN p.Birthday = '1959-02-18' AND l.Date LIKE '1981-11-%' THEN l.`T-CHO` ELSE 0 END) -   SUM(CASE WHEN p.Birthday = '1959-02-18' AND l.Date LIKE '1981-12-%' THEN l.`T-CHO` ELSE 0 END) AS decrease_rate FROM Patient p JOIN Laboratory l ON p.ID = l.ID;
SELECT DISTINCT p.ID FROM Patient p JOIN Examination e ON p.ID = e.ID WHERE p.Diagnosis LIKE '%Behcet%'   AND e.`Examination Date` >= '1997-01-01'   AND e.`Examination Date` < '1998-01-01';
SELECT COUNT(*) AS count, ID FROM Laboratory WHERE Date BETWEEN '1987-07-06' AND '1996-01-31'   AND GPT > 30   AND ALB < 4 GROUP BY ID;
SELECT ID FROM Patient WHERE SEX = 'F'   AND strftime('%Y', Birthday) = '1964'   AND Admission = '+';
SELECT COUNT(*) FROM Examination WHERE Thrombosis = 2   AND `ANA Pattern` = 'S'   AND `aCL IgM` > (SELECT AVG(`aCL IgM`) FROM Examination) * 1.2;
SELECT      CAST(SUM(CASE WHEN UA <= 6.5 THEN 1 ELSE 0 END) AS REAL) * 100 /      SUM(CASE WHEN `U-PRO` > 0 AND `U-PRO` < 30 THEN 1 ELSE 0 END) AS percentage FROM Laboratory WHERE `U-PRO` > 0 AND `U-PRO` < 30;
SELECT   CAST(SUM(CASE WHEN Diagnosis = 'BEHCET' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(*) FROM Patient WHERE SEX = 'M'   AND strftime('%Y', `First Date`) = '1981';
SELECT DISTINCT p.ID FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE p.Admission = '-'   AND l.Date LIKE '1991-10%'   AND l.`T-BIL` < 2.0;
SELECT COUNT(*) AS count FROM Patient p JOIN Examination e ON p.ID = e.ID WHERE e.`ANA Pattern` != 'P'   AND p.SEX = 'F'   AND p.Birthday BETWEEN '1980-01-01' AND '1989-12-31';
SELECT     p.SEX FROM Patient AS p JOIN Examination AS e     ON p.ID = e.ID JOIN Laboratory AS l     ON p.ID = l.ID WHERE     e.Diagnosis = 'PSS'     AND l.CRP = '2+'     AND l.CRE = 1     AND l.LDH = 123;
SELECT AVG(T1.ALB) FROM Laboratory AS T1 INNER JOIN Patient AS T2   ON T1.ID = T2.ID WHERE T2.SEX = 'F'   AND T1.PLT > 400   AND T2.Diagnosis = 'SLE';
SELECT T1.Symptoms FROM Examination AS T1 INNER JOIN Patient AS T2 ON T1.ID = T2.ID WHERE T2.Diagnosis = 'SLE' GROUP BY T1.Symptoms ORDER BY COUNT(*) DESC LIMIT 1;
SELECT     `Description`,     `Diagnosis` FROM     `Patient` WHERE     `ID` = 48473;
SELECT COUNT(*) FROM Patient WHERE SEX = 'F' AND Diagnosis = 'APS';
SELECT COUNT(DISTINCT l.ID) AS patient_count FROM Laboratory l WHERE strftime('%Y', l.Date) = '1997'   AND (l.TP <= 6 OR l.TP >= 8.5);
SELECT   CAST(SUM(CASE WHEN e.Diagnosis LIKE '%SLE%' THEN 1 ELSE 0 END) AS REAL) * 100 / SUM(CASE WHEN e.Symptoms LIKE '%thrombocytopenia%' THEN 1 ELSE 0 END) AS proportion FROM Examination e WHERE e.Symptoms LIKE '%thrombocytopenia%';
SELECT      CAST(SUM(CASE WHEN SEX = 'F' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(SEX) AS percentage FROM      Patient WHERE      STRFTIME('%Y', Birthday) = '1980'     AND Diagnosis = 'RA';
SELECT COUNT(*) AS count FROM Patient AS p JOIN Examination AS e   ON p.ID = e.ID WHERE p.SEX = 'M'   AND e.`Examination Date` BETWEEN '1995-01-01' AND '1997-12-31'   AND e.Diagnosis = 'Behcet'   AND p.Admission = '-';
SELECT COUNT(DISTINCT p.ID) AS count FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE p.SEX = 'F'   AND l.WBC < 3.5;
SELECT DATEDIFF(e.`Examination Date`, p.`First Date`) AS days FROM Patient p JOIN Examination e ON p.ID = e.ID WHERE p.ID = 821298;
SELECT   CASE     WHEN (l.UA > 8.0 AND p.SEX = 'M') OR (l.UA > 6.5 AND p.SEX = 'F') THEN 'yes'     ELSE 'no'   END FROM Laboratory AS l JOIN Patient AS p   ON l.ID = p.ID WHERE p.ID = 57266;
SELECT     l.Date FROM     Laboratory l WHERE     l.ID = 48473     AND l.GOT >= 60;
SELECT     p.ID,     p.SEX,     p.Birthday FROM Patient AS p JOIN Laboratory AS l     ON p.ID = l.ID WHERE l.GOT < 60   AND strftime('%Y', l.Date) = '1994';
SELECT DISTINCT p.ID FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE p.SEX = 'M'   AND l.GPT >= 60;
SELECT     p.Diagnosis FROM     Patient p JOIN     Laboratory l     ON p.ID = l.ID WHERE     l.GPT > 60 ORDER BY     p.Birthday ASC;
SELECT AVG(LDH) FROM Laboratory WHERE LDH < 500;
SELECT   p.ID,   CAST(strftime('%Y', 'now') AS INTEGER) - CAST(strftime('%Y', p.Birthday) AS INTEGER) AS age FROM Patient AS p JOIN Laboratory AS l   ON p.ID = l.ID WHERE l.LDH BETWEEN 600 AND 800;
SELECT      CASE          WHEN p.Admission = '+' THEN 'Inpatient'         WHEN p.Admission = '-' THEN 'Outpatient'         ELSE 'Unknown'     END AS Admission_Type FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE l.ALP < 300;
SELECT      p.ID,     CASE          WHEN l.ALP < 300 THEN 'Yes'          ELSE 'No'      END AS ALP_within_normal_range FROM      Patient p LEFT JOIN      Laboratory l ON p.ID = l.ID WHERE      p.Birthday = '1982-04-01';
SELECT     p.ID,     p.SEX,     p.Birthday FROM Patient AS p JOIN Laboratory AS l     ON p.ID = l.ID WHERE l.TP < 6.0;
SELECT   T1.ID,   T1.TP - 8.5 AS deviation FROM   Laboratory AS T1   JOIN Patient AS T2     ON T1.ID = T2.ID WHERE   T2.SEX = 'F'   AND T1.TP > 8.5;
SELECT p.* FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE p.SEX = 'M'   AND (l.ALB <= 3.5 OR l.ALB >= 5.5) ORDER BY p.Birthday DESC;
SELECT      p.ID,     CASE          WHEN l.ALB BETWEEN 3.5 AND 5.5 THEN 'Yes'         ELSE 'No'     END AS Is_ALB_Within_Normal_Range FROM Patient p LEFT JOIN Laboratory l ON p.ID = l.ID WHERE strftime('%Y', p.Birthday) = '1982';
SELECT    CAST(SUM(CASE WHEN T1.UA > 6.5 THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(*)  FROM Laboratory AS T1 JOIN Patient AS T2    ON T1.ID = T2.ID WHERE T2.SEX = 'F';
WITH LatestLab AS (     SELECT         l.ID,         l.Date,         l.UA,         ROW_NUMBER() OVER (PARTITION BY l.ID ORDER BY l.Date DESC) AS rn     FROM Laboratory l ), LatestLabFiltered AS (     SELECT         ll.ID,         ll.UA     FROM LatestLab ll     WHERE ll.rn = 1 ), PatientWithLatestUA AS (     SELECT         p.ID,         p.SEX,         ll.UA     FROM Patient p     JOIN LatestLabFiltered ll ON p.ID = ll.ID ) SELECT     AVG(pw.UA) AS avg_ua FROM PatientWithLatestUA pw WHERE     (pw.SEX = 'M' AND pw.UA < 8.0)     OR     (pw.SEX = 'F' AND pw.UA < 6.5);
SELECT     p.ID,     p.SEX,     p.Birthday FROM Patient AS p JOIN Laboratory AS l     ON p.ID = l.ID WHERE l.UN = 29;
SELECT     p.ID,     p.SEX,     p.Birthday FROM Patient AS p JOIN Laboratory AS l     ON p.ID = l.ID WHERE     p.Diagnosis = 'RA'     AND l.UN < 30;
SELECT COUNT(*) FROM Patient AS P JOIN Laboratory AS L ON P.ID = L.ID WHERE P.SEX = 'M'   AND L.CRE >= 1.5;
SELECT   CASE     WHEN SUM(CASE WHEN p.SEX = 'M' THEN 1 ELSE 0 END) > SUM(CASE WHEN p.SEX = 'F' THEN 1 ELSE 0 END)     THEN 'True'     ELSE 'False'   END FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE l.CRE >= 1.5;
SELECT     p.ID,     p.SEX,     p.Birthday FROM Patient AS p JOIN Laboratory AS l     ON p.ID = l.ID WHERE l.`T-BIL` = (     SELECT MAX(`T-BIL`)     FROM Laboratory );
SELECT      p.SEX,     GROUP_CONCAT(DISTINCT p.ID) AS patient_ids FROM      Patient p JOIN      Laboratory l ON p.ID = l.ID WHERE      l.`T-BIL` >= 2.0 GROUP BY      p.SEX;
SELECT   p.ID,   l.[T-CHO] FROM Patient AS p JOIN Laboratory AS l   ON p.ID = l.ID ORDER BY   p.Birthday ASC,   l.[T-CHO] DESC LIMIT 1;
SELECT   CAST(SUM(CAST(strftime('%Y', 'now') AS INTEGER) - CAST(strftime('%Y', T1.Birthday) AS INTEGER)) AS REAL) * 1.0 / COUNT(T1.ID) AS average_age FROM Patient AS T1 JOIN Laboratory AS T2   ON T1.ID = T2.ID WHERE   T1.SEX = 'M'   AND T2.`T-CHO` >= 250;
SELECT DISTINCT p.ID, p.Diagnosis FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE l.TG > 300;
SELECT COUNT(DISTINCT T1.ID) FROM Patient AS T1 JOIN Laboratory AS T2   ON T1.ID = T2.ID WHERE T2.TG >= 200   AND (strftime('%Y', 'now') - strftime('%Y', T1.Birthday)) > 50;
SELECT DISTINCT p.ID FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE p.Admission = '-'   AND l.CPK < 250;
SELECT COUNT(DISTINCT p.ID) AS count FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE p.SEX = 'M'   AND CAST(strftime('%Y', p.Birthday) AS INTEGER) BETWEEN 1936 AND 1956   AND l.CPK >= 250;
SELECT     p.ID,     p.SEX,     CAST(strftime('%Y', 'now') AS INTEGER) - CAST(strftime('%Y', p.Birthday) AS INTEGER) AS age FROM Patient AS p JOIN Laboratory AS l     ON p.ID = l.ID WHERE l.GLU >= 180   AND l.`T-CHO` < 250;
SELECT     p.ID,     l.GLU FROM Patient AS p JOIN Laboratory AS l     ON p.ID = l.ID WHERE     strftime('%Y', p.Description) = '1991'     AND l.GLU < 180;
SELECT     p.ID,     p.SEX,     p.Birthday FROM Patient p JOIN Laboratory l     ON p.ID = l.ID WHERE     l.WBC <= 3.5     OR l.WBC >= 9.0 ORDER BY     p.SEX,     p.Birthday ASC;
SELECT     p.ID,     p.Diagnosis,     CAST(strftime('%Y', 'now') AS INTEGER) - CAST(strftime('%Y', p.Birthday) AS INTEGER) AS age FROM Patient AS p JOIN Laboratory AS l     ON p.ID = l.ID WHERE l.RBC < 3.5;
SELECT     p.ID,     p.Admission FROM Patient AS p JOIN Laboratory AS l     ON p.ID = l.ID WHERE     p.SEX = 'F'     AND (strftime('%Y', 'now') - strftime('%Y', p.Birthday)) >= 50     AND (l.RBC <= 3.5 OR l.RBC >= 6.0);
SELECT DISTINCT p.ID, p.SEX FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE p.Admission = '-'   AND l.HGB < 10;
SELECT     p.ID,     p.SEX FROM Patient AS p JOIN Laboratory AS l     ON p.ID = l.ID WHERE     p.Diagnosis = 'SLE'     AND l.HGB > 10     AND l.HGB < 17 ORDER BY     p.Birthday ASC LIMIT 1;
SELECT   p.ID,   CAST(strftime('%Y', 'now') AS INTEGER) - CAST(strftime('%Y', p.Birthday) AS INTEGER) AS age FROM Patient AS p JOIN Laboratory AS l   ON p.ID = l.ID WHERE l.HCT >= 52 GROUP BY p.ID HAVING COUNT(l.ID) > 2;
SELECT AVG(HCT) FROM Laboratory WHERE Date LIKE '1991%' AND HCT < 29;
SELECT      SUM(CASE WHEN PLT < 100 THEN 1 ELSE 0 END) - SUM(CASE WHEN PLT > 400 THEN 1 ELSE 0 END) AS difference FROM Laboratory WHERE PLT <= 100 OR PLT >= 400;
SELECT DISTINCT     p.ID FROM     Patient p JOIN     Laboratory l     ON p.ID = l.ID WHERE     strftime('%Y', l.Date) = '1984'     AND (strftime('%Y', 'now') - strftime('%Y', p.Birthday)) < 50     AND l.PLT BETWEEN 100 AND 400;
SELECT      CAST(SUM(CASE WHEN L.PT >= 14 AND P.SEX = 'F' THEN 1 ELSE 0 END) AS REAL) * 100 /      SUM(CASE WHEN L.PT >= 14 THEN 1 ELSE 0 END) AS percentage FROM Patient P JOIN Laboratory L ON P.ID = L.ID WHERE (strftime('%Y', 'now') - strftime('%Y', P.Birthday)) > 55;
SELECT DISTINCT p.ID FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE strftime('%Y', p.`First Date`) > '1992'   AND l.PT < 14;
SELECT COUNT(*) FROM Examination WHERE `Examination Date` > '1997-01-01'   AND APTT < 45;
SELECT COUNT(DISTINCT T1.ID) AS count FROM Laboratory AS T1 JOIN Examination AS T2   ON T1.ID = T2.ID WHERE T1.APTT > 45   AND T2.Thrombosis = 0;
SELECT COUNT(DISTINCT T1.ID) FROM Patient AS T1 JOIN Laboratory AS T2   ON T1.ID = T2.ID WHERE T1.SEX = 'M'   AND T2.WBC > 3.5   AND T2.WBC < 9.0   AND (T2.FG <= 150 OR T2.FG >= 450);
SELECT COUNT(DISTINCT p.ID) AS patient_count FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE p.Birthday > '1980-01-01'   AND (l.FG < 150 OR l.FG > 450);
SELECT DISTINCT p.Diagnosis FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE l.`U-PRO` >= 30;
SELECT   p.ID FROM Patient AS p JOIN Laboratory AS l   ON p.ID = l.ID WHERE   l.`U-PRO` > 0   AND l.`U-PRO` < 30   AND p.Diagnosis = 'SLE';
SELECT COUNT(DISTINCT ID) FROM Laboratory WHERE IGG >= 2000;
SELECT COUNT(*) FROM Examination WHERE EXISTS (     SELECT 1     FROM Laboratory     WHERE Laboratory.ID = Examination.ID       AND Laboratory.IGG > 900       AND Laboratory.IGG < 2000 ) AND Examination.Symptoms IS NOT NULL;
SELECT p.Diagnosis FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE l.IGA BETWEEN 80 AND 500 ORDER BY l.IGA DESC LIMIT 1;
SELECT COUNT(DISTINCT p.ID) AS patient_count FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE l.IGA > 80   AND l.IGA < 500   AND p.`First Date` IS NOT NULL   AND strftime('%Y', p.`First Date`) >= '1990';
SELECT     p.Diagnosis FROM     Patient p     JOIN Laboratory l ON p.ID = l.ID WHERE     l.IGM <= 40     OR l.IGM >= 400 GROUP BY     p.Diagnosis ORDER BY     COUNT(p.Diagnosis) DESC LIMIT 1;
SELECT COUNT(*) AS count FROM Patient WHERE Description IS NULL   AND EXISTS (     SELECT 1     FROM Laboratory     WHERE Laboratory.ID = Patient.ID       AND Laboratory.CRP = '+'   );
SELECT COUNT(DISTINCT p.ID) AS count FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE l.CRE >= 1.5   AND (strftime('%Y', 'now') - strftime('%Y', p.Birthday)) < 70;
SELECT COUNT(DISTINCT e.ID) AS count FROM Examination e JOIN Laboratory l   ON e.ID = l.ID WHERE e.KCT = '+'   AND l.RA IN ('-', '+-');
SELECT DISTINCT p.Diagnosis FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE p.Birthday >= '1985-01-01'   AND l.RA IN ('-', '+-');
SELECT   p.ID FROM Patient AS p JOIN Laboratory AS l   ON p.ID = l.ID WHERE   l.RF < 20   AND (strftime('%Y', 'now') - strftime('%Y', p.Birthday)) > 60;
SELECT COUNT(DISTINCT e.ID) AS patient_count FROM Examination e JOIN Laboratory l   ON e.ID = l.ID WHERE l.RF < 20   AND e.Thrombosis = 0;
SELECT COUNT(DISTINCT p.ID) AS patient_count FROM Patient p JOIN Laboratory l ON p.ID = l.ID JOIN Examination e ON p.ID = e.ID WHERE l.C3 > 35   AND e.`ANA Pattern` = 'P';
SELECT   e.ID FROM Examination AS e JOIN Laboratory AS l   ON e.ID = l.ID WHERE l.HCT <= 29    OR l.HCT >= 52 ORDER BY   e.`aCL IgA` DESC LIMIT 1;
SELECT COUNT(DISTINCT T1.ID) FROM Examination AS T1 JOIN Laboratory AS T2   ON T1.ID = T2.ID WHERE T1.Diagnosis = 'APS'   AND T2.C4 > 10;
SELECT COUNT(DISTINCT p.ID) FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE p.Admission = '+'   AND l.RNP IN ('-', '+-');
SELECT     p.Birthday FROM Patient AS p JOIN Laboratory AS l     ON p.ID = l.ID WHERE     l.RNP NOT IN ('-', '+-') ORDER BY     p.Birthday DESC LIMIT 1;
SELECT COUNT(*) AS count FROM Examination e JOIN Laboratory l   ON e.ID = l.ID WHERE l.SM IN ('-', '+-')   AND e.Thrombosis = 0;
SELECT   p.ID FROM Patient AS p JOIN Laboratory AS l   ON p.ID = l.ID WHERE l.SM NOT IN ('negative', '0') ORDER BY p.Birthday DESC LIMIT 3;
SELECT DISTINCT e.ID FROM Examination e JOIN Laboratory l   ON e.ID = l.ID  AND l.SC170 IN ('negative', '0') WHERE e.`Examination Date` > '1997-01-01';
SELECT COUNT(DISTINCT p.ID) FROM Patient p JOIN Laboratory l ON p.ID = l.ID JOIN Examination e ON p.ID = e.ID WHERE l.SC170 IN ('negative', '0')   AND p.SEX = 'F'   AND e.Symptoms IS NULL;
SELECT COUNT(DISTINCT p.ID) AS patient_count FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE l.SSA IN ('-', '+-')   AND p.`First Date` IS NOT NULL   AND strftime('%Y', p.`First Date`) < '2000';
SELECT   p.ID FROM Patient AS p JOIN Laboratory AS l   ON p.ID = l.ID WHERE l.SSA NOT IN ('negative', '0') ORDER BY p.`First Date` ASC LIMIT 1;
SELECT COUNT(DISTINCT e.ID) AS patient_count FROM Examination e WHERE e.Diagnosis = 'SLE'   AND e.SSB IN ('-', '+-');
SELECT COUNT(DISTINCT e.ID) AS count FROM Examination e JOIN Laboratory l   ON e.ID = l.ID WHERE l.SSB IN ('negative', '0')   AND e.Symptoms IS NOT NULL;
SELECT COUNT(DISTINCT p.ID) AS male_count FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE l.CENTROMEA IN ('-', '+-')   AND l.SSB IN ('-', '+-')   AND p.SEX = 'M';
SELECT DISTINCT p.Diagnosis FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE l.DNA >= 8;
SELECT COUNT(DISTINCT p.ID) AS patient_count FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE l.DNA < 8   AND p.Description IS NULL;
SELECT COUNT(DISTINCT p.ID) AS admitted_count FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE l.IGG > 900   AND l.IGG < 2000   AND p.Admission = '+';
SELECT   CAST(COUNT(CASE WHEN l.GOT >= 60 AND p.Diagnosis = 'SLE' THEN l.ID END) AS REAL) * 100 / COUNT(l.ID) FROM Laboratory l JOIN Patient p   ON l.ID = p.ID WHERE l.GOT >= 60;
SELECT COUNT(*) FROM Patient AS P JOIN Laboratory AS L   ON P.ID = L.ID WHERE P.SEX = 'M'   AND L.GOT < 60;
SELECT MIN(T1.Birthday) FROM Patient AS T1 JOIN Laboratory AS T2   ON T1.ID = T2.ID WHERE T2.GOT >= 60;
SELECT     p.Birthday FROM     Patient p JOIN     Laboratory l     ON p.ID = l.ID WHERE     l.GPT < 60 ORDER BY     l.GPT DESC LIMIT 3;
SELECT COUNT(*) AS male_count FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE l.GOT < 60   AND p.SEX = 'M';
WITH NormalLDH AS (     SELECT          L.ID,         L.LDH,         P."First Date"     FROM Laboratory L     JOIN Patient P ON L.ID = P.ID     WHERE L.LDH < 500 ), MaxLDH AS (     SELECT          ID,         "First Date"     FROM NormalLDH     ORDER BY LDH DESC     LIMIT 1 ) SELECT "First Date" FROM MaxLDH;
SELECT MAX(l.Date) FROM Laboratory l JOIN Patient p ON l.ID = p.ID WHERE l.LDH >= 500   AND p.ID = (     SELECT ID     FROM Patient     WHERE "First Date" IS NOT NULL     ORDER BY "First Date" DESC     LIMIT 1   );
SELECT COUNT(DISTINCT p.ID) AS admitted_count FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE l.ALP >= 300   AND p.Admission = '+';
SELECT COUNT(DISTINCT p.ID) AS patient_count FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE p.Admission = '-'   AND l.ALP < 300;
SELECT DISTINCT p.Diagnosis FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE l.TP < 6.0;
SELECT COUNT(*) FROM Patient AS P JOIN Laboratory AS L ON P.ID = L.ID WHERE P.Diagnosis = 'SJS'   AND L.TP > 6.0   AND L.TP < 8.5;
SELECT T1.`Examination Date` FROM Examination AS T1 JOIN Laboratory AS T2   ON T1.ID = T2.ID WHERE T2.ALB > 3.5   AND T2.ALB < 5.5 ORDER BY T2.ALB DESC LIMIT 1;
SELECT COUNT(*) FROM Patient AS P JOIN Laboratory AS L   ON P.ID = L.ID WHERE P.SEX = 'M'   AND L.ALB > 3.5   AND L.ALB < 5.5   AND L.TP BETWEEN 6.0 AND 8.5;
SELECT     e.`aCL IgG`,     e.`aCL IgM`,     e.`aCL IgA` FROM Examination AS e JOIN Patient AS p   ON e.ID = p.ID JOIN Laboratory AS l   ON e.ID = l.ID WHERE     p.SEX = 'F'     AND l.UA <= 6.50 ORDER BY     l.UA DESC LIMIT 1;
SELECT MAX(e.ANA) FROM Examination e JOIN Laboratory l   ON e.ID = l.ID WHERE l.CRE < 1.5;
SELECT     e.ID FROM Examination AS e JOIN Laboratory AS l     ON e.ID = l.ID WHERE     l.CRE < 1.5 ORDER BY     e.`aCL IgA` DESC LIMIT 1;
SELECT COUNT(DISTINCT p.ID) AS count FROM Patient p JOIN Laboratory l ON p.ID = l.ID JOIN Examination e ON p.ID = e.ID WHERE l.`T-BIL` >= 2.0   AND e.`ANA Pattern` LIKE '%P%';
SELECT     e.ANA FROM Examination AS e JOIN Laboratory AS l     ON e.ID = l.ID WHERE l.`T-BIL` < 2.0 ORDER BY l.`T-BIL` DESC LIMIT 1;
SELECT COUNT(DISTINCT e.ID) AS count FROM Examination e JOIN Laboratory l   ON e.ID = l.ID WHERE l.`T-CHO` >= 250   AND e.KCT = '-';
SELECT COUNT(DISTINCT e.ID) AS count FROM Examination e JOIN Laboratory l   ON e.ID = l.ID WHERE l.`T-CHO` < 250   AND e.`ANA Pattern` = 'P';
SELECT COUNT(*) AS count FROM Examination e JOIN Laboratory l   ON e.ID = l.ID WHERE l.TG < 200   AND e.Symptoms IS NOT NULL;
SELECT     p.Diagnosis FROM Patient AS p JOIN Laboratory AS l     ON p.ID = l.ID WHERE     l.TG < 200 ORDER BY     l.TG DESC LIMIT 1;
SELECT   e.ID FROM Examination AS e JOIN Laboratory AS l   ON e.ID = l.ID WHERE   e.Thrombosis = 0   AND l.CPK < 250;
SELECT COUNT(DISTINCT p.ID) AS count FROM Patient p JOIN Laboratory l ON p.ID = l.ID JOIN Examination e ON p.ID = e.ID WHERE l.CPK < 250   AND (e.KCT = '+' OR e.RVVT = '+' OR e.LAC = '+');
SELECT   p.Birthday FROM Patient AS p JOIN Laboratory AS l   ON p.ID = l.ID WHERE   l.GLU > 180 ORDER BY   p.Birthday ASC LIMIT 1;
SELECT COUNT(*) FROM Examination AS E JOIN Laboratory AS L   ON E.ID = L.ID WHERE L.GLU < 180   AND E.Thrombosis = 0;
SELECT COUNT(DISTINCT p.ID) AS patient_count FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE p.Admission = '+'   AND l.WBC BETWEEN 3.5 AND 9.0;
SELECT COUNT(DISTINCT p.ID) AS patient_count FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE p.Diagnosis = 'SLE'   AND l.WBC BETWEEN 3.5 AND 9.0;
SELECT DISTINCT l.ID FROM Laboratory l JOIN Patient p ON l.ID = p.ID WHERE (l.RBC <= 3.5 OR l.RBC >= 6.0)   AND p.Admission = '-';
SELECT COUNT(DISTINCT p.ID) AS count FROM Patient p JOIN Laboratory l ON p.ID = l.ID WHERE l.PLT > 100   AND l.PLT < 400   AND p.Diagnosis IS NOT NULL;
SELECT     l.PLT FROM Laboratory AS l JOIN Patient AS p     ON l.ID = p.ID WHERE     p.Diagnosis = 'MCTD'     AND l.PLT > 100     AND l.PLT < 400;
SELECT AVG(l.PT) FROM Laboratory l JOIN Patient p ON l.ID = p.ID WHERE p.SEX = 'M'   AND l.PT < 14;
SELECT COUNT(*) FROM Examination AS E JOIN Laboratory AS L   ON E.ID = L.ID WHERE E.Thrombosis IN (1, 2)   AND L.PT < 14;
