SELECT     m.phone FROM member AS m JOIN major AS mj     ON m.link_to_major = mj.major_id WHERE     mj.major_name = 'Business'     AND mj.college = 'College of Agriculture and Applied Sciences';
SELECT m.email FROM member m JOIN expense e ON m.member_id = e.link_to_member WHERE e.expense_date BETWEEN '2019-09-10' AND '2019-11-19'   AND e.cost > 20;
SELECT COUNT(*) AS member_count FROM member m JOIN major ma ON m.link_to_major = ma.major_id WHERE ma.college = 'College of Education & Human Services'   AND ma.major_name = 'education'   AND m.position = 'Member';
SELECT      CAST(SUM(CASE WHEN b.remaining < 0 THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(e.event_id) AS percentage FROM event e LEFT JOIN budget b ON e.event_id = b.link_to_event;
SELECT event_id, location, status FROM event WHERE event_date BETWEEN '2019-11-01' AND '2020-03-31';
SELECT expense_description FROM expense GROUP BY expense_description HAVING SUM(cost) / COUNT(expense_id) > 50;
SELECT first_name, last_name FROM member WHERE t_shirt_size = 'X-Large';
SELECT      CAST(SUM(CASE WHEN type = 'PO Box' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(zip_code) AS percentage FROM      zip_code;
SELECT e.event_name, e.location FROM event e JOIN budget b ON e.event_id = b.link_to_event WHERE b.remaining > 0;
SELECT     e.event_name,     e.event_date FROM event AS e JOIN budget AS b     ON e.event_id = b.link_to_event JOIN expense AS ex     ON b.budget_id = ex.link_to_budget WHERE     ex.expense_description = 'Pizza'     AND ex.cost > 50     AND ex.cost < 100;
SELECT     m.first_name,     m.last_name,     mj.major_name FROM member AS m JOIN expense AS e     ON m.member_id = e.link_to_member LEFT JOIN major AS mj     ON m.link_to_major = mj.major_id WHERE e.cost > 100;
SELECT z.city, z.state FROM event e JOIN member m ON m.zip = z.zip_code JOIN income i ON i.link_to_member = m.member_id JOIN attendance a ON a.link_to_member = m.member_id AND a.link_to_event = e.event_id JOIN zip_code z ON m.zip = z.zip_code GROUP BY e.event_id, z.city, z.state HAVING COUNT(i.income_id) > 40;
SELECT     m.first_name,     m.last_name FROM     member m JOIN     expense e     ON m.member_id = e.link_to_member JOIN     budget b     ON e.link_to_budget = b.budget_id JOIN     event ev     ON b.link_to_event = ev.event_id GROUP BY     m.member_id HAVING     COUNT(DISTINCT ev.event_id) > 1 ORDER BY     MAX(e.cost) DESC LIMIT 1;
SELECT   SUM(e.cost) * 1.0 / COUNT(ev.event_id) AS average_amount_paid FROM expense e JOIN member m   ON e.link_to_member = m.member_id JOIN attendance a   ON m.member_id = a.link_to_member JOIN event ev   ON a.link_to_event = ev.event_id WHERE m.position <> 'Member';
SELECT     e.event_name FROM event AS e JOIN budget AS b   ON e.event_id = b.link_to_event JOIN expense AS ex   ON b.budget_id = ex.link_to_budget WHERE     b.category = 'Parking'     AND ex.cost < (         SELECT             SUM(ex2.cost) * 1.0 / COUNT(e2.event_id)         FROM event AS e2         JOIN budget AS b2           ON e2.event_id = b2.link_to_event         JOIN expense AS ex2           ON b2.budget_id = ex2.link_to_budget         WHERE             b2.category = 'Parking'     );
SELECT      CAST(SUM(e.cost) AS REAL) * 100 / COUNT(ev.event_id) AS percentage FROM expense e JOIN budget b ON e.link_to_budget = b.budget_id JOIN event ev ON b.link_to_event = ev.event_id WHERE ev.type = 'Meeting';
SELECT b.budget_id FROM expense e JOIN budget b ON e.link_to_budget = b.budget_id WHERE e.expense_description = 'Water, chips, cookies' ORDER BY e.cost DESC LIMIT 1;
WITH MemberSpending AS (     SELECT          m.member_id,         m.first_name,         m.last_name,         MAX(e.cost) AS max_spending     FROM member m     JOIN expense e ON m.member_id = e.link_to_member     GROUP BY m.member_id, m.first_name, m.last_name ) SELECT      first_name,     last_name FROM MemberSpending ORDER BY max_spending DESC LIMIT 5;
SELECT     m.first_name,     m.last_name,     m.phone FROM member AS m JOIN expense AS e   ON m.member_id = e.link_to_member WHERE e.cost > (     SELECT AVG(cost)     FROM expense );
SELECT      (         (             SELECT                  CAST(SUM(CASE WHEN z.state = 'New Jersey' THEN 1 ELSE 0 END) AS REAL) * 100.0 / COUNT(*)             FROM member m             JOIN zip_code z ON m.zip = z.zip_code             WHERE m.position = 'Member'         )     ) - (         (             SELECT                  CAST(SUM(CASE WHEN z.state = 'Vermont' THEN 1 ELSE 0 END) AS REAL) * 100.0 / COUNT(*)             FROM member m             JOIN zip_code z ON m.zip = z.zip_code             WHERE m.position = 'Member'         )     );
SELECT m.major_name, m.department FROM member AS mem JOIN major AS m ON mem.link_to_major = m.major_id WHERE mem.first_name = 'Garrett' AND mem.last_name = 'Gerke';
SELECT     m.first_name,     m.last_name,     e.cost FROM expense AS e JOIN member AS m     ON e.link_to_member = m.member_id WHERE e.expense_description = 'Water, Veggie tray, supplies';
SELECT     m.last_name,     m.phone FROM member AS m JOIN major AS mj     ON m.link_to_major = mj.major_id WHERE mj.major_name = 'Elementary Education';
SELECT b.category, b.amount FROM budget b JOIN event e ON b.link_to_event = e.event_id WHERE e.event_name = 'January Speaker';
SELECT DISTINCT e.event_name FROM event e JOIN budget b ON e.event_id = b.link_to_event WHERE b.category = 'Food';
SELECT     m.first_name,     m.last_name,     i.amount FROM member AS m JOIN income AS i     ON m.member_id = i.link_to_member WHERE i.date_received = '9/9/2019';
SELECT b.category FROM expense e JOIN budget b ON e.link_to_budget = b.budget_id WHERE e.expense_description = 'Posters';
SELECT      m.first_name,     m.last_name,     ma.college FROM member m LEFT JOIN major ma ON m.link_to_major = ma.major_id WHERE m.position = 'Secretary';
SELECT      SUM(b.spent) AS total_amount_spent,     e.event_name FROM budget b JOIN event e ON b.link_to_event = e.event_id WHERE b.category = 'Speaker Gifts' GROUP BY e.event_name;
SELECT z.city FROM member m JOIN zip_code z ON m.zip = z.zip_code WHERE m.first_name = 'Garrett' AND m.last_name = 'Gerke';
SELECT     m.first_name,     m.last_name,     m.position FROM member AS m JOIN zip_code AS z     ON m.zip = z.zip_code WHERE     z.city = 'Lincolnton'     AND z.state = 'North Carolina'     AND z.zip_code = 28092;
SELECT COUNT(*) FROM gasstations WHERE Country = 'CZE' AND Segment = 'Premium';
SELECT      CAST(SUM(CASE WHEN Currency = 'EUR' THEN 1 ELSE 0 END) AS REAL) /      NULLIF(SUM(CASE WHEN Currency = 'CZK' THEN 1 ELSE 0 END), 0) AS ratio FROM customers;
SELECT     c.CustomerID FROM yearmonth AS ym JOIN customers AS c     ON ym.CustomerID = c.CustomerID WHERE     c.Segment = 'LAM'     AND ym.Date BETWEEN '201201' AND '201212' ORDER BY     ym.Consumption ASC LIMIT 1;
SELECT AVG(ym.Consumption) / 12 AS average_monthly_consumption FROM yearmonth ym JOIN customers c   ON ym.CustomerID = c.CustomerID WHERE c.Segment = 'SME'   AND ym.Date BETWEEN '201301' AND '201312';
SELECT c.CustomerID FROM customers c JOIN yearmonth ym ON c.CustomerID = ym.CustomerID WHERE c.Currency = 'CZK'   AND ym.Date BETWEEN '201101' AND '201112' ORDER BY ym.Consumption DESC LIMIT 1;
SELECT COUNT(DISTINCT T1.CustomerID) FROM customers AS T1 JOIN yearmonth AS T2   ON T1.CustomerID = T2.CustomerID WHERE T1.Segment = 'KAM'   AND T2.Date BETWEEN '201201' AND '201212'   AND T2.Consumption < 30000;
SELECT   SUM(CASE WHEN c.Currency = 'CZK' THEN y.Consumption ELSE 0 END) -   SUM(CASE WHEN c.Currency = 'EUR' THEN y.Consumption ELSE 0 END) AS difference FROM yearmonth y JOIN customers c   ON y.CustomerID = c.CustomerID WHERE y.Date BETWEEN '201201' AND '201212';
SELECT   strftime('%Y', t.Date) AS Year FROM   transactions_1k t   JOIN customers c ON t.CustomerID = c.CustomerID WHERE   c.Currency = 'EUR' GROUP BY   strftime('%Y', t.Date) ORDER BY   SUM(t.Amount) DESC LIMIT 1;
SELECT c.Segment FROM customers c JOIN yearmonth y ON c.CustomerID = y.CustomerID GROUP BY c.Segment ORDER BY SUM(y.Consumption) ASC LIMIT 1;
SELECT   SUBSTR(y.Date, 1, 4) AS Year FROM   yearmonth y   JOIN customers c ON y.CustomerID = c.CustomerID WHERE   c.Currency = 'CZK' GROUP BY   SUBSTR(y.Date, 1, 4) ORDER BY   SUM(y.Consumption) DESC LIMIT 1;
SELECT     ym.Date FROM     yearmonth AS ym JOIN     customers AS c     ON ym.CustomerID = c.CustomerID WHERE     c.Segment = 'SME'     AND ym.Date BETWEEN '201301' AND '201312' ORDER BY     ym.Consumption DESC LIMIT 1;
WITH cze_customers AS (     SELECT          c.CustomerID,         c.Segment     FROM customers c     WHERE c.Currency = 'CZK' ), customer_consumption AS (     SELECT          cc.CustomerID,         cc.Segment,         SUM(ym.Consumption) AS total_consumption     FROM cze_customers cc     JOIN yearmonth ym ON cc.CustomerID = ym.CustomerID     WHERE ym.Date BETWEEN '201301' AND '201312'     GROUP BY cc.CustomerID, cc.Segment ), lowest_consumption_per_segment AS (     SELECT          Segment,         MIN(total_consumption) AS min_consumption     FROM customer_consumption     GROUP BY Segment ), customers_with_lowest_consumption AS (     SELECT          cc.CustomerID,         cc.Segment,         cc.total_consumption     FROM customer_consumption cc     JOIN lowest_consumption_per_segment lcs ON cc.Segment = lcs.Segment AND cc.total_consumption = lcs.min_consumption ), segment_annual_average AS (     SELECT          Segment,         AVG(total_consumption) AS annual_average     FROM customers_with_lowest_consumption     GROUP BY Segment ) SELECT      (SELECT annual_average FROM segment_annual_average WHERE Segment = 'SME') -      (SELECT annual_average FROM segment_annual_average WHERE Segment = 'LAM') AS sme_lam_diff,     (SELECT annual_average FROM segment_annual_average WHERE Segment = 'LAM') -      (SELECT annual_average FROM segment_annual_average WHERE Segment = 'KAM') AS lam_kam_diff,     (SELECT annual_average FROM segment_annual_average WHERE Segment = 'KAM') -      (SELECT annual_average FROM segment_annual_average WHERE Segment = 'SME') AS kam_sme_diff
WITH consumption_by_segment_year AS (     SELECT          c.Segment,         CAST(SUBSTR(ym.Date, 1, 4) AS INTEGER) AS Year,         SUM(ym.Consumption) AS TotalConsumption     FROM yearmonth ym     JOIN customers c ON ym.CustomerID = c.CustomerID     WHERE c.Currency = 'EUR'       AND c.Segment IN ('SME', 'LAM', 'KAM')       AND CAST(SUBSTR(ym.Date, 1, 4) AS INTEGER) IN (2012, 2013)     GROUP BY c.Segment, CAST(SUBSTR(ym.Date, 1, 4) AS INTEGER) ), segment_consumption AS (     SELECT          Segment,         SUM(CASE WHEN Year = 2012 THEN TotalConsumption ELSE 0 END) AS Consumption2012,         SUM(CASE WHEN Year = 2013 THEN TotalConsumption ELSE 0 END) AS Consumption2013     FROM consumption_by_segment_year     GROUP BY Segment ), segment_percentage AS (     SELECT          Segment,         (Consumption2013 - Consumption2012) AS IncreaseDecrease,         ((Consumption2013 - Consumption2012) / Consumption2013) * 100 AS PercentageIncrease     FROM segment_consumption     WHERE Consumption2013 != 0 ) SELECT      Segment,     PercentageIncrease FROM segment_percentage ORDER BY      CASE          WHEN PercentageIncrease = (SELECT MAX(PercentageIncrease) FROM segment_percentage) THEN 1         WHEN PercentageIncrease = (SELECT MIN(PercentageIncrease) FROM segment_percentage) THEN 2         ELSE 3     END;
SELECT SUM(Consumption) FROM yearmonth WHERE CustomerID = 6 AND Date BETWEEN '201308' AND '201311';
SELECT   (SELECT COUNT(*) FROM gasstations WHERE Country = 'CZE' AND Segment = 'Discount') -   (SELECT COUNT(*) FROM gasstations WHERE Country = 'SVK' AND Segment = 'Discount') AS difference;
SELECT      (SELECT Consumption FROM yearmonth WHERE CustomerID = 7 AND Date = '201304') -      (SELECT Consumption FROM yearmonth WHERE CustomerID = 5 AND Date = '201304') AS difference;
SELECT      SUM(CASE WHEN Currency = 'CZK' THEN 1 ELSE 0 END) -      SUM(CASE WHEN Currency = 'EUR' THEN 1 ELSE 0 END) AS difference FROM customers WHERE Segment = 'SME';
SELECT c.CustomerID FROM customers c JOIN yearmonth ym ON c.CustomerID = ym.CustomerID WHERE c.Segment = 'LAM'   AND c.Currency = 'EUR'   AND ym.Date = '201310' ORDER BY ym.Consumption DESC LIMIT 1;
SELECT      c.CustomerID,     SUM(ym.Consumption) AS TotalConsumption FROM      customers c JOIN      yearmonth ym ON c.CustomerID = ym.CustomerID WHERE      c.Segment = 'KAM' GROUP BY      c.CustomerID ORDER BY      TotalConsumption DESC LIMIT 1;
SELECT SUM(ym.Consumption) AS total_consumption FROM yearmonth ym JOIN customers c ON ym.CustomerID = c.CustomerID WHERE c.Segment = 'KAM'   AND ym.Date = '201305';
WITH lam_customers AS (     SELECT          c.CustomerID,         COALESCE(SUM(ym.Consumption), 0) AS total_consumption     FROM customers c     LEFT JOIN yearmonth ym ON c.CustomerID = ym.CustomerID     WHERE c.Segment = 'LAM'     GROUP BY c.CustomerID ) SELECT      (COUNT(CASE WHEN total_consumption > 46.73 THEN 1 END) * 100.0 / COUNT(*)) AS percentage FROM lam_customers;
SELECT      Country,     COUNT(*) AS TotalValueForMoneyStations FROM      gasstations WHERE      Segment = 'Value for money' GROUP BY      Country ORDER BY      TotalValueForMoneyStations DESC;
SELECT      CAST(SUM(CASE WHEN Currency = 'EUR' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(*)  FROM customers WHERE Segment = 'KAM';
SELECT      CAST(SUM(CASE WHEN Consumption > 528.3 THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(*) AS percentage FROM yearmonth WHERE Date = '201202';
SELECT      CAST(SUM(CASE WHEN gs.Segment = 'Premium' THEN 1 ELSE 0 END) AS REAL) * 100.0 / COUNT(*) AS percentage FROM gasstations gs WHERE gs.Country = 'SVK';
SELECT CustomerID FROM yearmonth WHERE Date = '201309' ORDER BY Consumption DESC LIMIT 1;
SELECT     c.Segment FROM     yearmonth y JOIN     customers c     ON y.CustomerID = c.CustomerID WHERE     y.Date = '201309' GROUP BY     c.Segment ORDER BY     SUM(y.Consumption) ASC LIMIT 1;
SELECT c.CustomerID FROM customers c JOIN yearmonth ym ON c.CustomerID = ym.CustomerID WHERE c.Segment = 'SME'   AND ym.Date = '201206' ORDER BY ym.Consumption ASC LIMIT 1;
SELECT MAX(Consumption) AS highest_monthly_consumption FROM yearmonth WHERE substr(Date, 1, 4) = '2012';
WITH euro_customers AS (     SELECT          c.CustomerID     FROM          customers c     WHERE          c.Currency = 'EUR' ), monthly_consumption AS (     SELECT          ym.CustomerID,         SUM(ym.Consumption) / 12.0 AS MonthlyConsumption     FROM          yearmonth ym     INNER JOIN          euro_customers ec ON ym.CustomerID = ec.CustomerID     GROUP BY          ym.CustomerID ) SELECT      MAX(MonthlyConsumption) AS BiggestMonthlyConsumption FROM      monthly_consumption;
SELECT DISTINCT p.Description FROM products p JOIN transactions_1k t ON p.ProductID = t.ProductID WHERE strftime('%Y%m', t.Date) = '201309';
SELECT DISTINCT gs.Country FROM gasstations gs JOIN transactions_1k t ON gs.GasStationID = t.GasStationID WHERE strftime('%Y%m', t.Date) = '201306';
SELECT DISTINCT gs.ChainID FROM gasstations gs JOIN transactions_1k t ON gs.GasStationID = t.GasStationID JOIN customers c ON t.CustomerID = c.CustomerID WHERE c.Currency = 'EUR';
SELECT DISTINCT p.Description FROM products p JOIN transactions_1k t ON p.ProductID = t.ProductID JOIN customers c ON t.CustomerID = c.CustomerID WHERE c.Currency = 'EUR';
SELECT AVG(Price) AS average_total_price FROM transactions_1k WHERE Date LIKE '2012-01%';
SELECT COUNT(DISTINCT c.CustomerID) FROM customers c JOIN yearmonth ym ON c.CustomerID = ym.CustomerID WHERE c.Currency = 'EUR'   AND ym.Consumption > 1000;
SELECT DISTINCT p.Description FROM products p JOIN transactions_1k t ON p.ProductID = t.ProductID JOIN gasstations g ON t.GasStationID = g.GasStationID WHERE g.Country = 'CZE';
SELECT DISTINCT t.Time FROM transactions_1k t JOIN gasstations g ON t.GasStationID = g.GasStationID WHERE g.ChainID = 11;
SELECT COUNT(*) FROM transactions_1k t JOIN gasstations g ON t.GasStationID = g.GasStationID WHERE g.Country = 'CZE'   AND t.Price > 1000;
SELECT COUNT(*) FROM transactions_1k t JOIN gasstations g ON t.GasStationID = g.GasStationID WHERE g.Country = 'CZE'   AND t.Date > '2012-01-01';
SELECT AVG(t.Price) AS average_total_price FROM transactions_1k t JOIN gasstations g ON t.GasStationID = g.GasStationID WHERE g.Country = 'CZE';
WITH euro_customers AS (     SELECT CustomerID     FROM customers     WHERE Currency = 'EUR' ), customer_totals AS (     SELECT          t.CustomerID,         SUM(t.Price) AS total_price     FROM transactions_1k t     INNER JOIN euro_customers ec ON t.CustomerID = ec.CustomerID     GROUP BY t.CustomerID ) SELECT AVG(total_price) AS average_total_price FROM customer_totals;
SELECT c.CustomerID FROM transactions_1k t JOIN customers c ON t.CustomerID = c.CustomerID WHERE t.Date = '2012-08-25' ORDER BY t.Amount DESC LIMIT 1;
SELECT gs.Country FROM transactions_1k t JOIN gasstations gs ON t.GasStationID = gs.GasStationID WHERE t.Date = '2012-08-25' ORDER BY t.TransactionID LIMIT 1;
SELECT c.Currency FROM transactions_1k t JOIN customers c ON t.CustomerID = c.CustomerID WHERE t.Date = '2012-08-24'   AND t.Time = '16:25:00';
SELECT c.Segment FROM customers c JOIN transactions_1k t ON c.CustomerID = t.CustomerID WHERE t.Date = '2012-08-23'   AND t.Time = '21:20:00';
SELECT COUNT(*) AS transaction_count FROM transactions_1k t JOIN customers c ON t.CustomerID = c.CustomerID WHERE t.Date = '2012-08-26'   AND t.Time < '13:00:00'   AND c.Currency = 'CZK';
SELECT c.Segment FROM customers c ORDER BY c.CustomerID ASC LIMIT 1;
SELECT T2.Country FROM transactions_1k AS T1 JOIN gasstations AS T2 ON T1.GasStationID = T2.GasStationID WHERE T1.Date = '2012-08-24' AND T1.Time = '12:42:00';
SELECT ProductID FROM transactions_1k WHERE Date = '2012-08-23' AND Time = '21:20:00';
SELECT     ym.Date,     ym.Consumption FROM yearmonth AS ym JOIN transactions_1k AS t   ON ym.CustomerID = t.CustomerID WHERE t.Date = '2012-08-24'   AND t.Price = 124.05   AND ym.Date LIKE '201201%';
SELECT COUNT(*) AS count FROM transactions_1k t JOIN gasstations g ON t.GasStationID = g.GasStationID WHERE t.Date = '2012-08-26'   AND t.Time BETWEEN '08:00:00' AND '09:00:00'   AND g.Country = 'CZE';
SELECT c.Currency FROM customers c JOIN yearmonth ym ON c.CustomerID = ym.CustomerID WHERE ym.Date = '201306'   AND ym.Consumption = 214582.17;
SELECT gs.Country FROM transactions_1k t JOIN gasstations gs ON t.GasStationID = gs.GasStationID WHERE t.CardID = 667467 LIMIT 1;
SELECT c.Currency FROM customers c JOIN yearmonth ym ON c.CustomerID = ym.CustomerID WHERE ym.Consumption = 548.4   AND ym.Date = '201208';
WITH customers_eur AS (     SELECT COUNT(DISTINCT c.CustomerID) AS eur_count     FROM customers c     JOIN transactions_1k t ON c.CustomerID = t.CustomerID     WHERE c.Currency = 'EUR'       AND t.Date = '2012-08-25' ), all_customers AS (     SELECT COUNT(DISTINCT t.CustomerID) AS total_count     FROM transactions_1k t     WHERE t.Date = '2012-08-25' ) SELECT      CASE          WHEN a.total_count = 0 THEN 0.0         ELSE (e.eur_count * 100.0) / a.total_count     END AS percentage FROM customers_eur e CROSS JOIN all_customers a;
WITH target_customer AS (     SELECT CustomerID     FROM transactions_1k     WHERE Date = '2012-08-25'       AND Price = 634.8 ), consumption_2012 AS (     SELECT SUM(Consumption) AS total_2012     FROM yearmonth     WHERE CustomerID = (SELECT CustomerID FROM target_customer)       AND Date LIKE '2012%' ), consumption_2013 AS (     SELECT SUM(Consumption) AS total_2013     FROM yearmonth     WHERE CustomerID = (SELECT CustomerID FROM target_customer)       AND Date LIKE '2013%' ) SELECT (c2012.total_2012 - c2013.total_2013) / c2012.total_2012 AS consumption_decrease_rate FROM consumption_2012 c2012 CROSS JOIN consumption_2013 c2013;
SELECT gs.GasStationID FROM gasstations gs JOIN transactions_1k t ON gs.GasStationID = t.GasStationID GROUP BY gs.GasStationID ORDER BY SUM(t.Amount) DESC LIMIT 1;
SELECT   CAST(SUM(CASE WHEN gs.Segment = 'Premium' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(*) FROM gasstations AS gs WHERE gs.Country = 'SVK';
SELECT      (SELECT SUM(t.Amount)       FROM transactions_1k t       WHERE t.CustomerID = 38508) AS total_amount_spent,     (SELECT ym.Consumption       FROM yearmonth ym       WHERE ym.CustomerID = 38508         AND ym.Date = '201201') AS january_2012_consumption;
SELECT p.Description FROM products p JOIN transactions_1k t ON p.ProductID = t.ProductID GROUP BY p.ProductID, p.Description ORDER BY SUM(t.Amount) DESC LIMIT 5;
WITH customer_totals AS (     SELECT          t.CustomerID,         SUM(t.Price) AS total_price,         SUM(t.Amount) AS total_amount     FROM transactions_1k t     GROUP BY t.CustomerID ), ranked_customers AS (     SELECT          ct.CustomerID,         ct.total_price,         ct.total_amount,         ct.total_price / ct.total_amount AS avg_price_per_item,         RANK() OVER (ORDER BY ct.total_price DESC) AS rank     FROM customer_totals ct ) SELECT      rc.CustomerID,     rc.avg_price_per_item,     c.Currency FROM ranked_customers rc JOIN customers c ON rc.CustomerID = c.CustomerID WHERE rc.rank = 1;
SELECT gs.Country FROM transactions_1k t JOIN gasstations gs ON t.GasStationID = gs.GasStationID WHERE t.ProductID = 2 ORDER BY t.Price DESC LIMIT 1;
SELECT     ym.CustomerID,     ym.Consumption FROM     yearmonth AS ym JOIN     transactions_1k AS t     ON ym.CustomerID = t.CustomerID WHERE     t.ProductID = 5     AND t.Price / t.Amount > 29.00     AND ym.Date = '201208';
